/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230111-10","meetingId":"r05-cm01","date":"2023年1月11日","dateIso":"2023-01-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"令和４年第４回定例会","agenda":"令和４年第４回定例会","exchanges":[{"speaker":"石田委員","kind":"質問","question":"１点だけ伺いたいのですが、補正予算と区長給与の条例について、なぜ最終本会議というタイミングで出されるのか、理由を伺いたいと思います。","respondent":"森澤区長","answer":"区長給与の件に関しましては、様々整理が必要だったため、本来は初日に行わせていただきたかったのですが、いろいろ文言の整理等が必要だったため、最終日となりました。どうぞご理解のほどよろしくお願いいたします。","id":"exchange-001"}]},{"id":"topic-02","title":"議員提出第５号議案、品川区議会個人情報の保護に関する条例","agenda":"議員提出第５号議案、品川区議会個人情報の保護に関する条例","exchanges":[{"speaker":"石田委員","kind":"確認","question":"それと、個人情報ファイル簿についても、区議会としては作らない、現在も作っていないですし、想定もし難いとご説明いただいていますけれども、これからも作る考えはないということでいいのか、確認させてください。","respondent":"工藤区議会事務局長","answer":"２点目の個人情報ファイル簿の件につきましては、こちらも前回の議会運営委員会の中で、区議会の中では想定をしていない、そのように取り扱うファイルはないということでお答えしていますが、今後についても、そのような多くの方。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"最終的な確認をしたいのですけれども、住民側のリスクはないということでいいですかという確認をしたいのと、リスクが想定されるのかという部分と、あと、金額の部分なのですけれども、別表の第３０条関係の金額の部分で、写し１枚につき５０円以内で議長が定める額、ビデオテープ等が７００円以内とあるのですが、これの根拠というか、現状はコピー代１０円になっているのですけれども。","respondent":"工藤区議会事務局長","answer":"住民側のリスクという観点ですけれども、今回改正された個人情報保護法につきましては、社会全体のデジタル化に対応するため、個人情報の保護とデータの流通という２つの側面から、しっかりと情報については取扱いを図っていこうという法律の趣旨のものですので。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"金額の部分、現在の品川区の情報公開の規定だと、カラーに関して、白黒以外のものによっては７０円という金額だったのですけれども、それよりも下がると考えていいのかというところを伺わせてください。","respondent":"工藤区議会事務局長","answer":"委員おっしゃるとおり、現在７０円ということが、今回５０円になるです。下がるです。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"確認ができました。今後なのですけれども、今、印刷もどんどん安くなってきているというか、それに沿って、時代に沿って、この１０円とかの金額も下がっていくのかなというところが気になってしまうので、確認をしたいのですけれども、そのときには条例改正になるのですか。","respondent":"工藤区議会事務局長","answer":"この後、料金改定、下がるという部分、上がるというところは今後のことで、今お答えできませんけれども、金額につきましては、執行機関側では規則の中で、区議会のほうでは規程の中で、詳細を定めてまいりますので、その中で執行機関側が金額を変更するということであれば。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、要望で。今、印刷代とかもどんどん下がっていっていますので、そのときの状態に合わせて、議会や区のほうが高かったらあれかなと思うので、そのときに合わせて下げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田委員","kind":"確認","question":"仮名加工情報も匿名加工情報も利用する考えはないということ、個人情報ファイルも作る想定はしていないということを確認しましたので、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"令和４年陳情第５６号、行政及び議会が宗教によって「政治的な差別」を行わないことを求める陳情","agenda":"令和４年陳情第５６号、行政及び議会が宗教によって「政治的な差別」を行わないことを求める陳情","exchanges":[{"speaker":"湯澤委員","kind":"意見","question":"今回の陳情について、一定程度理解できますし、現在、国による調査の動向、また社会情勢や世論、住民感情など、十分留意して検討すべき内容だと考えておりますが、陳情項目にあります宣言をしない、調査をしないという結論を区議会として一律に決めることは、適切ではないと考えるものであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"その後、旧統一教会問題をめぐりまして、悪質な霊感商法、また法外な献金強要などの被害の実態が改めて浮き彫りになったことは事実であります。これは被害者の防止、救済法ということになっております。ですから、この新法に関しても、今後は適正に運用されているかを注視して改善をしていくということは、国会で決まっているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"私は、品川区議会としても宣言や決議をすべきだと考えていますが、ここにいらっしゃる会派の皆さんのご意見が伺えたらと思います。それで、陳情項目２については、宗教等の信仰については、思想・信条の自由が憲法で保障されていますし、調査などを行うことは、信教の自由の侵害、否定につながると思います。なので、以上の理由から、共産党としては賛同することはできないと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"憲法第２０条の、信教の自由は誰にでも認められる権利といって、これは侵害してはならないと。そのとおりなのですけれども、第２項にある「何人も、宗教上の行為、祝典、儀式又は行事に参加することを強制されない」という部分についても、今、例えば２世の問題とかでは、子どもたちが強制されてしまっているなどといった問題もあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、不採択です。ごめんなさい、先ほど１点言い忘れてしまったのですけれども、陳情項目２にある「調査・質問をしないこと」というのは、反社会的な行為や違法行為がもしあったならば、私たちは議員として、議会として、調査をしなければならないので、そういったところからも、この陳情項目には賛同はできないということで、不採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-04","title":"令和５年第１回定例会","agenda":"令和５年第１回定例会","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"(3)の予算特別委員会の運営について、審査日程のところで、以前共産党として、予算・決算特別委員会の民生費の款別審査について、民生費の部分と、国保、介護、後期高齢者医療特別会計の３つある中で、これを２日間に分けて審議を行えないかといったことを、議会改革推進会議等で検討していただきたいと要望はしてきたのですけれども、その後、検討はどのような状況か伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"直ちには難しいということで、以前から要望をしてきていることでして、しかるべき場で今後の議論はということでご説明がありましたので、ぜひ引き続き、ご議論・ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"ネットも今の石田委員と同じように、２日に分けてということを思っていたので、直ちには難しいということは理解したので、前向きに議論していただければと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"議長会等の報告等","agenda":"議長会等の報告等","exchanges":[{"speaker":"石田委員","kind":"確認","question":"それに関連してなのですけれども、今、議会傍聴が制限されている状況ですが、今はまだ感染拡大が、また増えるのか、減っていくのか、どうなるか分からない状況ですが、しかるべき時期に制限を今までどおりに戻すという検討をする必要があると思いますので、お願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"今の議長のご報告の中で、議会として、今後はホームページでの掲載、各議員への通知は行わないということは理解できたのですけれども、会議等への欠席の場合は連絡するようにと。感染の事実自体、陽性の事実自体は、もう報告をしなくていいということなのでしょうか。","respondent":"本多議長","answer":"感染が分かったことの事実だけは、事務局にお知らせをいただければと思います。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":19079,"voices":94}},{"id":"r05-20230112-7","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"厚生委員会","time":"午後 １時４１分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"第１１９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１１９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田委員","kind":"質問","question":"品川区出産・子育て応援交付金事業ということで、出産の費用は、大体７０万円から８０万円ぐらいかかってきてしまうと思うのですけれども、この間、私たちも一般質問等で取り上げてきているのですが、国が少し増額して、５０万円が一時金として出るわけです。それで今回、品川区が行う事業によって、実質、出産費用が無償化するということで考えられているのか、そういう考えなのか伺いたいと思います。","respondent":"若生健康課長","answer":"出産費用の無償化という観点での本事業との関係ですけれども、当然、出産費用も含めまして、出産・子育てに要する費用については、国の総合経済対策で従来から議論されて、そちらについての予算として１２月に成立して、市区町村で実施の運びになるというような流れですので。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"妊娠して、そして出産するまででも、本当にお金がかかることなので、安心して出産できるというところでは、すごくよかったなと思っているのですが、これは一時的な事業なのか、それともずっと続く事業なのか、そこを伺いたいと思います。","respondent":"若生健康課長","answer":"本事業につきましては、今回の補正予算は、令和４年度の予算ということで上程しているものですが、国の説明では、これは継続的に令和５年度以降も実施していく予定だということを聞いておりまして、当然、区としても、これを今年度のタイミングで終わらせるのではなく。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。国のほうも異次元の子育て支援ということで、本当に少子化が深刻化している中で、少子化が深刻化している理由は政治にもあると思っているのですが、こうした応援対策をさらに充実させていただきたいと思いますし、国にも求めていっていただきたいと思います。","respondent":"若生健康課長","answer":"こちらの予算の歳出の内訳の表記ですけれども、2)のほうが出産後の支給分、単価が１０万円となっているところですが、こちらについては、先ほどの説明で触れさせていただいた遡及適用分、出産を既にされている方に対しての支給が、令和４年度の分としては。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"分かりました。それで、ギフトのほかに、伴走型相談支援も充実させていくと書いてありまして、そうすると、先ほどの説明で表を読み上げていただき、充実を図るということなのですが、この中で新しいものはどれなのか、それから、伴走型相談支援で漏れなく妊娠された方、出産された方が１００％応援ギフトを知って、それで申請する方は申請するということになるのか伺いたいと思います。","respondent":"若生健康課長","answer":"それに加えまして、２回目の部分、妊娠８か月頃の面談については、表の中の米印にあるように、必要に応じて個別に保健師等が実施しているところではありますが、必ずこの時期に定期的にやっているというものではございませんで、こちらの部分を実施することによって。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、電子クーポンになるということです。電子クーポンというと、それを使うには、大体スマホとかパソコンになってくるのかなと思うのですけれども、若い方なので、そういうのを持っていない方というのはあまりいないのかなとは思うのですが、まれにいたりもするので、こうしたツールがない方がいた場合はどうするのでしょうか。","respondent":"柏木品川区保健所品川保健センター所長","answer":"電子クーポンが使えない方の対応ですが、今もやっております都の出産応援ギフトにつきましては電子クーポンなのですけれども、電子クーポンで対応できない方については、こちらのコールセンターに連絡をすると、紙のギフトが送られてきて。","id":"exchange-005"},{"speaker":"いながき委員","kind":"意見","question":"面談に関してお尋ねしたいのですけれども、面談の日程は平日だけなのか、働いている方が行けるのかどうなのかというのが一つと、２回目を新しくつくるということなのですが、この頃に面談をする目的、実施内容はあるのですけれども、そもそも面談をしないと、この事業の交付金というのはいただけないものなのかというのを、まずお尋ねします。","respondent":"柏木品川区保健所品川保健センター所長","answer":"お尋ねを２ついただいています。１つ目、面談が平日だけかということですけれども、現在のところ、平日のみで考えてあります。面談は絶対必要かという部分ですけれども、国の通知等によると、面談は必須ということになってあります。","id":"exchange-006"},{"speaker":"いながき委員","kind":"質問","question":"オンラインも可能ということを聞いて、少し安心はしたのですが、今現在、平日のみということで、やはり平日お仕事で難しい方たち宛てに、できれば土日とかの対応も、今後はご検討いただければと思います。それと、もし、アンケートを出すのが難しいという方たちに対しては、この支援は届かないということなのでしょうか。それとも、何がしかの手当てをしていただけるということなのでしょうか。","respondent":"柏木品川区保健所品川保健センター所長","answer":"先ほど面談は必須と申し上げましたが、やむを得ない事情の場合については個別に判断ということが、国からのＱ＆Ａで示されておりますので、そのときの状況によってご相談をさせていただきたいと思います。","id":"exchange-007"},{"speaker":"いながき委員","kind":"質問","question":"個別に丁寧にやっていただけるということで、ありがとうあります。安心しました。２枚目の事業スキームのところなのですけれども、私の調べ方が足りなかったのか、あれなのですが、各種子育ての支援サービスというのは今現在、具体的にどういったものがあるのかというのをお尋ねしてもよろしいでしょうか。","respondent":"若生健康課長","answer":"具体的な支援のギフト等の内容についてですけれども、東京都の委託事業者での対応になるところですので、今現在、東京都で検討を進めており、まだ詳細が示されていないところですが、既に実施している出産応援事業のところでのメニューとしては、例えば育児用品とかですと。","id":"exchange-008"},{"speaker":"いながき委員","kind":"確認","question":"スケジュールのところの要綱整備というのがあるのですが、要綱は今現在はあるものなのですか、これからつくられるものですか。一応、保健センターとかのホームページを探したのですけれども、見つからなくて、あるのだったら確認したいのですが。","respondent":"若生健康課長","answer":"こちらは全く新規の事業になりまして、補助金というか、交付金という形での事業になりますので、新たに一から要綱をこれから組み立てるということです。","id":"exchange-009"},{"speaker":"いながき委員","kind":"質問","question":"遡及的措置をというお話だったのですけれども、これはどこまで遡っていっていただけるものなのでしょうか。本当に困っていらっしゃる、きちんとお医者さんにアクセスをしていないで、出産のときだけ行かれる方というのもまだたくさんいらっしゃるので、そういった方たちに、何よりも早くこういった情報が届いてほしいと思うので、情報の周知がどのぐらい行くのかということ。","respondent":"若生健康課長","answer":"区といたしましても、そういった考え方ですとか、本事業の趣旨、それから、都が広域連携で事業をクーポンで実施するのでというところで、効率的かつ早期の実施というところの観点からは、クーポンで行うというところが適当と判断したところであります。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"２つ質問したいのですが、その中でもう一つが、妊娠届出時の対象世帯の中で、本事業をご案内する際には、流産をされた方も支給されるということが厚労省からも通知が出ていると理解しているのですが、きちんとこのことも周知してくださいということをお願いしていましたが、ここのところがきちんと明記されているのかどうかということが１つ。その２つを伺います。","respondent":"柏木品川区保健所品川保健センター所長、若生健康課長","answer":"面談後、ギフトを渡した後に流産・死産した場合にも、それは返品を求めないということが書かれてあります。遡及適用者へのＩＤ等の送付が、これは東京都の事業の広域連携を活用してという関係で、どうしても区独自で、すぐにスキームを組んでやるというのは難しいところでございまして、東京都が遡及適用者等も含めまして。","id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"提案","question":"分かりました。ごめんなさい、もう一つ、もう分かっていますけれども、一つ確認させてください。東京都の時限措置でやっている今のギフト、１０万円分の出生のギフトと、こちらは全く別のものであって、東京都内の方に関しては、２０万円分の恩恵が受けられるのかということを確認させていただきたいと思います。","respondent":"柏木品川区保健所品川保健センター所長","answer":"もともと都の出産応援事業は今年度で終了ということでしたけれども、２年間延長ということで、今、予算を出していると聞いていますので、来年度以降は先ほどご指摘あったとおり、出産応援事業で１０万円、こちらの伴走型ので５万円・５万円と、プラス２０万円という形になります。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"すみません、１点だけ。今、皆さんの質疑で私もほとんど理解できたので、１点だけお聞きしたいのですけれども、伴走型の支援は面談が１回、実質増えているのですが、保健センターなどの助産師・保健師の業務としては、大丈夫というか、人数を増やす予定とかがあるのかということとか、その業務が過多にならないのかというところで、そこだけお聞きしたいのですけれども。","respondent":"柏木品川区保健所品川保健センター所長","answer":"それで１００％近くになるのではないかと想定しておりますので、当然、面談数は増えて、プラス、２回目の面談もあるということで、それについては算出をしておりまして、今後は人事等とも調整をしていきたいと思います。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"これから検討していくということで、オンラインも可能ということも先ほどお話があったので、対象の方の意向もお聞きしながら、オンラインを活用していくと、少しはまた違ってくると思いますので、そういうところも検討して、あとは助産師・保健師の業務もしっかり検討していただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"態度としては賛成ですが、東京都の１０万円の出産応援事業が、２年延長されたとはいえ、時限的なものというところでは、私たちも一般質問で求めましたけれども、区独自に、安心して出産できるための支援をすべきだと思っていますし、国も異次元の子育て支援、少子化対策と言っておりますけれども、ここまで少子化が進んだ大きな原因は、政治にあると思いますので、国に対しても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成です。面談をされるので、そこのところで、子育てというところのフォローが一番大事なところだと思うので、しっかりとそちらをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":12009,"voices":51}},{"id":"r05-20230112-5","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"総務委員会","time":"午後 １時４１分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"第１２０号議案、品川区長の給与の特例に関する条例","agenda":"第１２０号議案、品川区長の給与の特例に関する条例","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"今回、品川区長の給与削減の提案ですが、大半の区民の実質所得や区内産業、中小規模の区内産業の実質収入が減っている中で、国民生活や区内産業の運営が厳しいことから、新区長は給与を減額するということになったかと思います。これについては、私は称賛される行動だと思います。できれば、品川区議会議員も同率減額して同調すべきだと思います。今回のこの議案については、私自身は賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"給与と退職金の２割カットということなのですけれども、これはなぜ２割なのかということと、それから、区長の給与がどれくらいあるべきかという基準の考え方があるのか、その点についてまず伺いたいと思います。そもそものところで、地域手当が、何が基準で１２％という数字がつけられているのか、地域手当とはどういうものなのかということについても伺いたいと思います。","respondent":"古巻総務課長","answer":"区長の給与の考え方ですけれども、周辺自治体の額も含めて適正な額という意味でいうと、さほど乖離しない額ということになろうかと思いますけれども、基本的には、特別職報酬等審議会のご意見を伺った中でこれまで定めてきた額が条例上の額になりますので。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここ（品川区長および副区長の給与および旅費条例）では「１００分の２０を乗じて得た額」とか、「１００分の２５を乗じて得た額」ということしか書いていないのですけれども、この２０％と２５％というのは、なぜこれがプラスされるのかという、その理由についても伺いたいと思います。","respondent":"古巻総務課長","answer":"２３区の区長の給料の状況ですけれども、若干、前後はありますし、また、今年度まだ報酬等審議会が開かれていない区もありますので、昨年の６月１日の現状で申し上げますと、基本給与額について、品川区は１１４万円ですけれども、例えば目黒区は１０５万５,０００円。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろありがとうあります。これが給料、地域手当、期末手当、そのトータルで削減される額ということで計算したのですけれども、これでいいかということを確認をさせていただきたいと思います。","respondent":"古巻総務課長","answer":"手元にあるのが条例の本則の部分ですので、場合によって、少し短期的なのか、減額している区があることは認識しておりますので、若干前後はあるかと思いますけれども、もともと品川区の場合は、区長の給与が、大体中位、２３区の中では真ん中ぐらいなので。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１期務めてこれだけの退職金が出るのは、結構出るものだなと、感想としてはあるのですけれども、この退職手当の給与月額の４.８倍が１年間に手当の額として規定されているという、この４.８倍というのは何を基準にして出されているのか、これは各区で違うものなのか、この考え方と仕組みがどういうふうになっているのか、職員の計算の仕方とも違うのか。","respondent":"古巻総務課長","answer":"その後、いろいろな経緯によって若干上下するということはありますけれども、各区の状況を見ますと、大体、４００から５００ぐらい、その割合で定められておりますので、周辺区でありますとか、いろいろな状況に応じて定められているものという認識です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことからすると、１年間でこれだけ出るということが規定されていますので、これも１年間分を４年でまとめて、退職のときに出るのだと思うのですけれども、ただ、１年ごとにという計算をされるので、それも含めて計算をしたのですけれども、そうすると、退職手当の１年分というものも含めた場合は、これまで２,７１５万３,６６０円、それが２,１７２万２,９２８円ということで。","respondent":"古巻総務課長","answer":"報酬等審議会につきましては、また改めて日程を定めて、どこかのタイミングで開かせていただいて、議員の方々の報酬等の額をどうするのかということもご意見を伺う必要があろうかと思いますので、そういった形で今後は進めていくような予定で考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、今回、特例という形での条例なので、今回の２割カットということに対しては、この報酬等審議会の意見を聞くということは、今後、これからも聞くということはなく、特例ということで、４年間はこれでいくのだということで進んでいくのかということの確認だけさせてください。","respondent":"古巻総務課長","answer":"具体的に意見を聞くということはないとは思いますけれども、当然、今回、給与の減額を条例で特例で定めておりますので、それを踏まえた上で、いろいろご意見を伺うというような形にはなろうかと思います。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"基礎的なことで大変申し訳ないのですけれども、この議案の付則の第３項というのですか、前項の規定は、前項というのは、この第２項のことだと思うのですけれども、それは、令和５年３月、だから今年の３月に支給する期末手当の額を計算する場合においては、適用しないということなのですけれども、この理由といいますか、どう読み取っていいのかが分からなくて、教えていただけますか。","respondent":"古巻総務課長","answer":"全体として２割にするということで、調整のさらに調整ということでご理解いただければと思います。ぴったり２割にするための規定です。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"ちょっとだけ意見を言わせてください。そもそも区長とかこういう方たちの給与が幾らぐらいであるべきかということについては、一般的な庶民感覚で言うと、様々議論があるかと思います。これだけ減らしてもこれだけの額になるのだということを今回改めて確認させていただいたようなことで、その額が本当に妥当なのかということは別の議論が必要かとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"第１１９号議案、令和４年度品川区一般会計補正予算","agenda":"第１１９号議案、令和４年度品川区一般会計補正予算","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今ご説明いただきました歳入のところなのですけれども、これ、都支出金ということですけれども、東京都を通して国から来ている分がどれぐらいあるのかということで、国と東京都と区の負担の割合が、３分の２が国で、６分の１と６分の１が東京都と区ということで伺ったのですけれども、それでいいのかということを１つお聞かせいただきたいと思います。","respondent":"黒田財政課長","answer":"他区の状況ですが、補正予算を早々に編成した区があるということも聞いておりますし、基本的にはどの自治体も、時期の差はあれど、実施するというふうに伺っているものです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"来ていたら、どのようなものが方向性として出されているのか、その点についても伺えたらと思います。","respondent":"黒田財政課長","answer":"令和５年度の国の予算もこれから国会で審議されますので、そういった中で実施主体が区市町村になるものにつきましては、区としても、しっかりその内容をとらまえて対応してまいりたいと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に少子化が深刻な状況というところでは、子育て支援は、区独自にも様々に対策を打っていくことがすごく必要だと思います。教育費にお金がかかり過ぎるということが本当に大きな父母の負担にもなっていますので、そういうところも含めて、国に対しても言っていただきたいと思いますし、ぜひとも区独自にも、これから対策をとっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"これはこれでいいと思いますが、やはりもっと皆さんの、何に母親が苦しんでいるのか、どうすれば子どもたちが、もっと安心して出産できて、子育てできるのかということを、国も、都も、品川区も考えて、少子化が少しでも改善できるような方向性に持っていけたらいいなというふうに思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問","question":"そうすると、恒久化していくと、６分の１というのはずっとついてくると思うのですが、どういうふうな予算、財源配分になるかというのはあると思うのですけれども、今回は、品川区は基金繰入金で８,６６７万円ということなのですが、５億２,０００万円ぐらいになっていくのかなとなったときに、今の既存の予算配分になると６分の１、ここについては、今回は基金繰入だけれども。","respondent":"黒田財政課長","answer":"次年度以降につきましては、この事業につきましては、国のほうで、令和５年度の９月までは今回の補正予算で財源を確保して、１０月以降については令和５年度の国の予算を措置する方向で検討を進めていると聞いてございまして、令和６年度以降の事業につきましては。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういうことで、当然、国である程度の方向性が出たときに、区としても、しっかりその辺りを対応できるように、ぜひまた準備等をお願いしたいというところと、今回、妊娠届時については、流産、死産等をされた方でも、カタログギフトについては返還を求めない、返金を求めないという形でご活用いただけるというところを、先ほどの所管委員会で確認させていただいたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"少しだけ意見を言わせてください。なぜ子どもをなかなか持ちにくいのかということについては、ぜひ区としても様々な視点から、きちんとその理由を探っていただいて、抜本的な対策をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2256#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14994,"voices":57}},{"id":"r05-20230112-10","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"議会運営委員会","time":"午後 ３時４０分～午後 ３時４２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1067,"voices":8}},{"id":"r05-20230123-6","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"区民委員会","time":"午後 １時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"引越し手続きのオンラインサービス開始","agenda":"引越し手続きのオンラインサービス開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"デジタル社会の形成を図るための関係法律の整備に関する法律の制定に伴いということで、この法律で制定されたことが２月６日から施行されることに伴って、引っ越しに伴う行政手続き等のオンライン化が実施されるという理解でよろしいのでしょうか。これを伺います。念のため。","respondent":"吉野戸籍住民課長","answer":"２月６日なのですけれども、こちらに関しましては、委員のご指摘のとおりでして、２月６日、デジタル社会の、こちらの関係法律が制定されたことに伴ってのものになります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"分かりました。マイナンバーカードを普及させたいという政府の意向が働いているのだろうと思います。この不安にやはり正面から応え切れていないと思いますので、応えないまま、マイナンバーカードのサービスを拡大していくのは、私はやめるべきだと思います。これを意見として述べさせていただいて、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"松本委員","kind":"意見","question":"この整備ですね、オンラインの届出ができるのは、品川区でもできる状態かと思うのですけれども、この新しいサービスと、既存のサービスもマイナンバーカードを利用して転出届、オンライン手続きということでホームページ上も掲載されていると思うのですが、この既存のものと今回のものの違いというか、どういう差があるのかというところのご説明をお願いいたします。","respondent":"吉野戸籍住民課長","answer":"転入するに当たって、いつ手続きに行きますという予約もできるような形になっています。ただし、時間は指定できないのですけれども、いつ来られるということで、こちらも準備ができるというような、そういった手続きになります。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"既存のオンラインのほうの転出というのは、これは品川区でやられていたということでしょうか。それで今回のマイナポータル、マイナポータルということは全国でということで、これまでは基盤は品川区で予算をかけて整備していたけれども、それが国の予算で新しい仕組みになるという理解でよろしいでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりになります。今までのものに関しましては、マイナポータルを使わずに、グラファーという独自のものを使っておりました。","id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"グラファーですね。今おっしゃったものは、これまではどのくらいの費用をかけていたのか。その意図としては、これが全国のほうに移行するということは、品川区としての費用というのはなくなると理解していいのか、それはどのくらいの額なのか、分かればお願いいたします。","respondent":"吉野戸籍住民課長","answer":"今度のサービスに関しましては、全て補助金のほうになります。ですので、グラファーのほうの使用料なのですけれども、そちらはかからなくなります。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"これまでのグラファーは、これは区の持ち出しというか、補助、国庫とか、全くなかったという理解でよろしいでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、これまでは区の持ち出しという形になっておりました。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"届出は必ず窓口に来なくてはいけないという話だったのですけれども、ここで、まず、転出・転入で、転出届とかをオンラインで、資料の（１）で入力して……、ごめんなさい、あまり引っ越しをしたことがないので、具体的に分かっていないのですが、何がどう変わるのかをしっかり理解したいと思いますので、改めての質問なのですが、転出届等、オンラインで（１）で入力しますと。こういう理解でよろしいですか。","respondent":"吉野戸籍住民課長","answer":"今までは申請書を書いていただいていたのですけれども、その申請書自体が署名だけで済むようなサービスになります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"もしそうだとして、やはりここも来庁して本人確認をせざるを得ないものなのか、マイナンバーカードで基本的には個人認証されているわけなので、誰が転居届を出しているのか特定されているわけだから、窓口まで来なくても転居を認めるということはできるのではないのかなと思うのですけれども、そこが来てくださいとなっている事情というのはどういうところでしょうか。","respondent":"吉野戸籍住民課長","answer":"これに関しましては、マイナンバーカードには顔写真がありまして、まず間違いなくあなたが引っ越されてきますねという確認をしますので、転入と同様に、やはり転居も不正を防ぐという意味で、まず顔と一致させていただいて、それで手続きを行うという段取りになっています。","id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"そのような手続き、必ず１回本人確認、本人の顔写真つきのものと本人が間違いないと窓口で確認しますということは、これは法律で決まっているのですか。それとも区としての判断なのか、そこを教えてください。","respondent":"吉野戸籍住民課長","answer":"こちらなのですけれども、住民基本台帳法で本人確認をするようにということで、あと戸籍法でも本人確認をするようにということで、こういったことは決まっております。","id":"exchange-009"}]},{"id":"topic-02","title":"「第３２回伝統の技と味／しながわ展」の開催","agenda":"「第３２回伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"この第３２回のしながわ展のもう少し詳しい説明というか、そういうページに飛ぶのですけれども、せっかくだったら、事務的なお知らせだけではなくて、伝統工芸で出されている商品とか、それを作られている職人の思いや、あるいはそういった歴史などを書いたりといった、一番いいのはきゅりあんに行って見ていただくことなのですけれども、行かなくても分かるよというようなホームページにしておくと。","respondent":"遠藤商業・ものづくり課長","answer":"今回、こういう形のイベントで、いわゆる検索の件数が増えるだろうなというところでもありますので、その辺、うまく活用して、今の委員ご指摘の部分も含めまして、思いとかそういうものがあれば、そういう部分も広げられるような形で、工夫を考えていければと考えています。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"第３２回を迎えまして、本当に事業がそれぞれ展開されることを望みますが、この長い歴史の中で、匠の技の種類ですか、これがどういうふうになっているのか。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、なかなか技術自体を、やはり後継ぎとなりますと、正直、応募するというのも変なのですけれども、そもそも弟子をとらない、これでやめるのだとおっしゃっているようなところで、なかなか厳しい部分で、区としてもお話を聞くところではあるのですけれども。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"ありがとうございました。本当に自主的に努力していかなければいけない部分も多いかと思いますが、ぜひ伝統を後世に伝えることを課題に置いて、努めていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"塚本委員","kind":"確認","question":"すみません、１つだけ確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"今回の昔遊びのコーナーについては、特別にそういう専門家といいますか、そういう方を配置する予定はないというのが正直なところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"所管が違うのですかね。少なくとも道具がないと駄目といいますか、コマとかけん玉とか、結構な数。そういうのは、区としては多分持っていなくて、どこかからさくっと借りられるような状況にあるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"こちら、例えば児童センターとかはあろうかと思いますので、ただすみません、今回どこから持ってくるかというのはお答えが難しいところですが、ただ、経験から、いろいろなところで持っているかなと考えています。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2950#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":9376,"voices":45}},{"id":"r05-20230123-7","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"厚生委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"品川区立東大井地域密着型多機能ホーム指定管理者候補者の公募","agenda":"品川区立東大井地域密着型多機能ホーム指定管理者候補者の公募","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"この東大井地域密着型多機能ホームの指定管理の公募を、こういう福祉施設等は、継続性とか利用者との信頼関係とか、そういうのもあって、あまり変更しない、継続して行っていくということで、品川の指定管理のところも進んでいると思うのですけれども、今回、説明のところで改定という言葉もあったと思うのですが、どう変わったのか、そこをもう一度ご説明いただきたいのと、そうすると、ほかの施設等も。","respondent":"菅野高齢者福祉課長","answer":"制度運営の透明性や公平性を図る観点から、指定管理者の更新限度年数を、先ほどの説明で、当初の運営期間終了後連続して１０年というのは、当初の運営期間が５年で連続して１０年なので、合わせて１５年というところで、そこを経過したものについては公募をするという方法に。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"分かりました。では、問題があってということではないので、公募要項の中身というのはおおよそ変わらないまま、公募がされていくということでいいのですか。","respondent":"菅野高齢者福祉課長","answer":"公募の中身等につきましては、指定管理者が行う業務、３番のところに記載しておりますが、こちらは今までもこの施設で行われているサービスのことについてですので、中身は変えずに同じような形で公募を行うということです。","id":"exchange-002"},{"speaker":"いながき委員","kind":"質問・要望","question":"今回、初ということなので、公募となると、より広くの方にお知らせをする形になるかと思うのですが、募集要項の配布とかをなるたけ丁寧にしていただきたいなと思うのですが、それがどういうふうに今後進んでいくのか、どういったところに配られるのかというのをお尋ねしたいのと、選定基準はこの（３）が基本かなとは思うのですが、その評価基準を改めてお尋ねしたいのと、やはり委員会のメンバーの方たちが。","respondent":"菅野高齢者福祉課長","answer":"そのときの福祉部における選考基準を定めておりまして、サービスの施設ごとに４つの視点ということで、サービスの質、維持管理能力、組織力、リスク等の管理能力等から評価するという基準ができておりますので、それにのっとって選定をする予定です。","id":"exchange-003"},{"speaker":"あくつ副委員長","kind":"質問","question":"東大井の小規模多機能の施設の公募ということなのですが、私も視察に、もう何年も前ですが伺ったことがあって、認知症対策の切り札ということで、この小規模多機能の施設は展開していただいているのですが、今現在行っていただいている指定管理者はどこなのかというところをまず伺います。","respondent":"菅野高齢者福祉課長","answer":"現在行ってもらっている指定管理者は、株式会社大起エンゼルヘルプという会社となっております。こちらの会社は、平成２１年４月に開設してから、以来１５年近くお願いしている運営事業者です。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"質問","question":"事業所自体は私は分からない。私の知っている方も入っておられましたけれども。そうすると、永遠に事業者が継続されてしまうということにもなりかねないとは思うのですけれども、例えば能力が同レベルだというふうに判断をしたときに、実績みたいなものがその評価の基準になるのかというところをお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"２点ご質問していただいたと思います。１点目の、現在の運営事業者が今回のこの制度のことをご理解されているかということで、これはもう令和３年にこちらの制度が改正されたということで、その部分については事業者には説明をしています。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、課長が、できれば今やっている方に応募していただきたいとおっしゃったのですが、それだったら、プロポーザルをやるというのとの関係で、一般論として伺いますが、ほかのこういう指定管理のところでも、同じようにそういう発言をされるのですか。それと今の課長の発言は、どうなのかなというところがあるのですが、そのあたりはいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"もちろん今いらっしゃる利用者との顔なじみの関係等の部分があるということも前提にはあるのですけれども、そうはいっても、きちんと、募集をする際には公平に審査は行いたいというのがもちろんのことですので、しっかりと徹底したいと考えています。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"確認","question":"今、確認で、公平に行っていただけるというお話だったので、大丈夫です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"品川区立北品川高齢者多世代交流支援施設（北品川ゆうゆうプラザ）指定管理者候補者の公募","agenda":"品川区立北品川高齢者多世代交流支援施設（北品川ゆうゆうプラザ）指定管理者候補者の公募","exchanges":[{"speaker":"石田委員","kind":"質問","question":"この北品川ゆうゆうプラザの、高齢者の健康維持や増進および生きがいづくりを支援するということで、ここでミニデイとかも入れるということになってくるのか、伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"あくまでも令和６年４月の開設の予定ではありますが、地域ミニデイの実施は、現状に合わせて予定をしたいとは考えてあります。ただ、あくまでも予定の段階です。まだ決定ではありません。","id":"exchange-008"},{"speaker":"石田委員","kind":"確認","question":"全てにおいてミニデイがあるというわけではなかったでしたか。そこの確認と、やはり指定管理、ミニデイ等も入るとなると、そういうことも管理できる、運営できる指定管理者ということになってくると思うのですが、そうすると、今の段階ではそこはそもそも入っている、検討事項なのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"実際に開設してから何の事業を実施するかというところまでは、まだ、もちろん現段階では未定です。","id":"exchange-009"},{"speaker":"いながき委員","kind":"確認","question":"同じような質問になってしまいますけれども、やはりこの公募に関しても、これは初ということでしょうか。そして、やはり委員会のメンバーの方たちも、どういった方たちが入るのかをお尋ねしたいのと、やはりお使いになる方たちにとって、一番いい形のものが作れればなと思うので、利用者の声はどういった形で反映されるのか、されないのか、そういった点を教えていただけますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"４つ目の利用者の方の意見を取り込んでいるかというところに関しては、やはり各種の住民説明会全体に関しても、そういった質問等も承っているだけでなく、毎年、令和２年、令和３年、令和４年にかけて、利用者を対象とした説明会、あと高齢者クラブの会長を対象とした説明会。","id":"exchange-010"}]},{"id":"topic-03","title":"品川区医師会館内改修工事に伴う休日診療所の休診および代替実施","agenda":"品川区医師会館内改修工事に伴う休日診療所の休診および代替実施","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"この改修工事というのは、品川区医師会の中にある休日診療所の改修工事ということでいいのかという確認と、この改修工事が品川区医師会の施設内で行われることについて、医師会から、そうした改修工事への区からの工事費の支援というのも要望で出ていたかと思うのですが、そこら辺への対応というのは何かされるのか、伺いたいと思います。","respondent":"若生健康課長","answer":"改修工事への工事費の支援のお話ですけれども、医師会からは、予算をご要望としていただいております。区としても、こちらについては現在検討中というところでございまして、来年度の予算編成のところでの回答になるかとは思うのですけれども、現在検討中です。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"なので、さらに改修工事となると、本当に経費の部分で大変な負担になってくると思いますので、そこは早急な経済的支援というのを行っていただきたいと思いますけれども、その検討というのは、ごめんなさい、聞こえなかったのですが、もう一回、いつぐらいまでにどういう支援がされるというのがあるのか、伺いたいと思うのですが。","respondent":"若生健康課長","answer":"こちらの経済的支援のところですけれども、現在、来年度予算についての予算編成というところでの検討というところで、検討しているということでお答えさせていただいたところです。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"来年度予算のところで検討ということで、でも、来年度に入る前の工事というところでは、大変負担になってくると思いますので、そこは早急な対応を私は取るべきだなと思いますし、取っていただきたいという要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問","question":"行ってみて、あれ、やっていなかったとならないようにするのが非常に重要なのかなということで、周知の部分でご説明があったのですが、ホームページで周知、広報しながわでとあるのですけれども、例えば、やるとは思うのですが、ＳＮＳ等で、今子育て世代の皆さん、スマートフォン等をお持ちですので、かなり分かりやすく、この日はここですよ、この日はここですよということをやはり強力にお知らせしないと。","respondent":"若生健康課長","answer":"休日診療所につきまして、従来から広報しながわで毎号に一覧で、今度の休日もしくは土曜日についてはどこの診療所というところはご案内しているところではありますけれども、今回、そういった意味では、改修工事に伴って従来と変わる部分ですので。","id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ＳＮＳというお話もあったのですが、品川区のＬＩＮＥが結構頻繁な確率で飛んでくるのですが、やはり非常に有益な情報というか、自分に関心のある情報は結構目に飛び込んでくるので、そこについては目につくような表示の仕方で、ぜひ周知をさらに進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今の周知の件ですが、もう２月からこういうふうになるということなので、できるだけ早くということで、今、副委員長からもお話があったと思うのですが、しながわパパママ応援アプリ、そこから区のホームページに飛べるようになっているので、区のホームページの改修を早くしていただきたいと、担当がどこになるのか分かりませんが、休日・夜間診療というところをクリックすれば区のホームページに飛ぶので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"いながき委員","kind":"意見","question":"よくこの場で検討中というお言葉を聞くのですけれども、それというのは大体、内容にもよるとは思うのですが、どれぐらい検討したらばこれは諦めるとか、どれぐらい検討したらばこれはやるとかという、何か基準とかがあるのかなというのが１つと、今のに関して言えば、石田委員がおっしゃったように、これは来年度の予算で検討中というお話なのですが、確かに工事が３月３１日までと今年度のものなので。","respondent":"若生健康課長","answer":"区からの支援という形になりますと、やはり所管だけで決められない部分も当然ありますし、予算を要求していってというような形の段取りというか、期間というところでの検討も一定かかりますので、そういったところで、来年度の予算編成に向けた検討というところで、医師会からは。","id":"exchange-017"},{"speaker":"いながき委員","kind":"意見","question":"何かつまずきがあるのかとお尋ねしたらば、そうでもないということだったので、どこまで、例えば１００％は無理だと思うのですが、９０％何か問題があった部分が解消されれば次に行くとか、もう本当に８年間２０％しかいかなかったから、もうこれはやめにしましょうとかいう、その一定の基準とか、判断する基準はないのかな……。","respondent":"高橋（伸）委員長","answer":"いながき委員、本日、報告事項は代替実施についてということなので、それに関してのご質疑をお願いします。","id":"exchange-018"},{"speaker":"いながき委員","kind":"質問","question":"駄目ということなので、そういった疑問がありますので、何かのときに教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-04","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"医療費が上がることにもなりますし、それにより受診控えも起きてしまいますし、検査も全て有料になってくるというところでは、本当にもう何か野放しになっていくという状況になるのではないかなと思うのですが、区としては５類への移行についてはどのような見解をお持ちなのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"報道の情報のみですけれども、それだけでどうだということはなかなか言いにくいのかなと。国のほうも、先週の金曜日も国の別件の説明会があったのですが、全然それに関してはなしです。今のところ情報はないということです。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。なので、やはり区としても、そうした葛飾区のような、症状が出ていても検査ができる、そして、抗原検査キットを配布する、そういうことを区民にもしていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"葛飾区のお話だったのですけれども、どういうスキームか承知していないのですけれども、結局、発熱外来の有症状の人が受診する枠は東京都のホームページに載っておりまして、それを見ていただければというのもありますし、もちろん保健所に電話をいただけたら。","id":"exchange-021"},{"speaker":"石田委員","kind":"質問・要望","question":"すみません、私も葛飾区のはスキームを知らずに言っているので、でも、そういう対応はされているというところでは、すごく、何ていうのですかね、熱が出た、コロナかなというふうに、今この状況ではみんなが心配されると思うのですが、そこで検査にたどり着くまでに時間がかかると、結果が出るまで結局時間がかかって、では、仕事がどうなるのか、家族との接触はどうなるのかというのがすぐに分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"いながき委員","kind":"質問・要望","question":"３月末で終了して、その後、国からは今のところ何もないということなのですが、その場合、区として独自で何かこういったことをやろうというものは、今現在、何かあるのか。本当に国から何も来なかったときに、どういった対策とか、もし今現在、もしくは将来的に何かこういった方向で考えているというものがあれば、教えていただきたいのですが。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ワクチンのことかと思われますので、私のほうでお答えします、ワクチン自体は区で独自で供給が賄えるのではなくて、全て国で行っているものです。","id":"exchange-023"},{"speaker":"いながき委員","kind":"質問","question":"おっしゃるとおりで、離れ小島ではないのでそうだとは思います。本当にテレビでもよく取り上げられていたと思っていて、そういうところがすごく品川区はいいなと思っているので、そういった部分が継続的にこれからも進んでいければなと思っての質問でした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"産後ケア（日帰り型）の会場変更","agenda":"産後ケア（日帰り型）の会場変更","exchanges":[{"speaker":"石田委員","kind":"質問","question":"しかも、品川保健センターになって、７月中旬からは、荏原保健センターが仮施設に入ればまた変更されるというところで、結構次々変わっていってしまうというところがあると思うので、そこら辺への対応、周知、しかもこれ、全部場所が近くないですよね。なので、大変だなと思ったりしたのですけれども、そこら辺の利用する側の利便性や声、そういったところは何か出ているのか伺いたいと思います。","respondent":"柏木品川区保健所品川保健センター所長","answer":"利用する側の不便ですが、まずこちらの産後ケア日帰り型ですが、使えるのは１回ということですので、１人の方が何回も使って会場が毎回違うとか、そういうことではございませんので、こちらはきっちり周知することで解消できるかと考えております。","id":"exchange-025"},{"speaker":"いながき委員","kind":"質問・要望","question":"それよりは、やはり使える時間であるとか周りの雰囲気とか、そういったところで産後ケアのお母さんたちの支援を続けていただきたいなということがありますので、それはご検討いただけるのでしょうか。","respondent":"柏木品川区保健所品川保健センター所長","answer":"会場の点ですが、こちらは内部で検討する際にも、代替のホテルという話はございました。ただ、先ほどの説明の中でも申し上げたのですが、産後ケアをやっている中で、やはり助産師が気になる母親の情報が、年々増えてきている。約３割の方が情報共有という状況があります。","id":"exchange-026"},{"speaker":"いながき委員","kind":"意見","question":"連絡が後になってしまうというお話があったのですけれども、今、本当にＳＮＳとかで、すぐに連絡も取れる状態ですし、その一点をもってして保健センターでというよりは、私はこの支援の主目的から考えれば、もちろん速やかに、ケアが必要な方に一日も早くという気持ちも分かるのですけれども、それプラス、その日のリラックスであるとか、こちらの雰囲気づくりとかも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"何点かあって、まず、今も質疑の中であったのですが、無知で申し訳ないのですが、産後ケア事業者から情報共有があってというお話で、その事業者というのはどういったところなのかというのを教えていただきたいのと、私も今、いながき委員がおっしゃっていたことで考えていて、先日、世田谷区立産後ケアセンターを視察したのですが、別に産後ケアに特化した建物を造ってほしいとかではないのですが。","respondent":"柏木品川区保健所品川保健センター所長","answer":"産後ケアの内容ですが、まず部屋につきましては、大きいことはできませんが、一応内装等で雰囲気をつくれるような形で、備品等もそろえて対応していきたいと考えています。","id":"exchange-028"},{"speaker":"せお委員","kind":"意見","question":"今のお話で、品川保健センターから荏原保健センターに変わるときに、少し議論していく余地はあるのかなと思ったので、昼食は難しいかもしれませんが、できるだけ母子に寄り添ったところの内容を充実させて、そこからいかに相談につなげていくかというか、支援につなげていくかというところかなと思っているので、そこの検討をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":21600,"voices":96}},{"id":"r05-20230123-8","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"建設委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年２月都営住宅入居者募集","agenda":"令和５年２月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの応募倍率などの実績、戸数も含めて、それを伺いたいと思います。","respondent":"竹田住宅課長","answer":"昨年１年間の応募数等をご説明します。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のでいくと、９.９倍から５２.０倍ですか、昨年、都営住宅の応募があったということで、この応募の数を含め倍率の変動というのは、区としてどのように見ているのかと、どういうところに多いとか、そういったのがあれば伺いたいと思います。それを、区として都に増設すべきだと求めていただきたい、求めるべきではないかと思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"区内には都営住宅以外にも区営住宅、民間賃貸住宅等も現在十分ある状況です。公的住宅だけでなく民間住宅も含めて、総合的に様々な施策を組み合わせていくべきだと考えておりますので、都へ都営住宅の増設を働きかける考えはございません。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"その傾向というのですか、区としてどのように見ているのか、そこを伺いたいというのが１点と、２点目の、増設を求める考えはないということでしたけれども、やはり民間住宅は高くてなかなか借りられないという状況があると思うのです。","respondent":"竹田住宅課長","answer":"倍率の傾向ですが、昨年１年間を例にご説明しますと、８月は４戸の募集で２０８人の応募がありましたので、５２.０倍となっております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"居住支援協議会とも相談するということですけれども、その協議会は民間の活用が基本、それを目的としたものなので、都営住宅、区営住宅の公的住宅の役割を発揮させていくというのは、やはり品川区がそれを考えていかなければならないと思いますので、今の状況下でいきますと、公営住宅をさらに、この倍率を見ても増設して、住民の暮らしをしっかり支えていく、保障していくということが必要だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"戸越公園駅交通広場に関する都市計画素案","agenda":"戸越公園駅交通広場に関する都市計画素案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、その隣、右側の交通広場の計画イメージのところで、防災性の高い空間を確保ということが書かれているのですが、それはどういった空間になるのか、そこを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"なかなか年配の方が、年配の方だけではなく子連れの方とかも、駅前に車をつけて乗り降りするというのが非常に難しいといいますか、人混みがあるので避けているような状況です。皆さん、２６号線などに車を止めて、そこから駅に歩いているというのが今の現状です。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、交通結節機能というのは駅へのアクセスが向上する、そういう意味ですかね。分かりました。それと、住民への周知ですが、今回、この都市計画素案をつくるということで、説明会とか、チラシも配布をしたということですけれども、今回、この都市計画素案の説明会の前に、住民の方にこうした計画があるよということはお知らせしているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"その記載の中に駅前広場の考え方、またはどこの位置に設置するか、イメージなど、そういったものは今までも説明してきているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民への説明のところは、私が少しお話を聞きに行ったところでも、知らない方も、少し前ですがいらっしゃったので、やはりいきなりこうした話を聞くと、なかなかびっくりして、特に自分の住んでいるところが地域に入っていたりすると、びっくりしてしまうというところもありますので、そこはしっかりお知らせをしていただきたいと思うのですが、このスケジュールの中で。","respondent":"中道まちづくり立体化担当課長","answer":"配布枚数は約１万１,０００枚と、非常に丁寧に今回、説明を進めているところです。用地補償の説明会の日程ですけれども、こちらの資料、別紙２の最後のページになりますけれども、用地補償の説明会は、この事業認可を取得した後となります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"実際に具体的に確定していくのは測量した後だということですけれども、大体このくらいというのは、区としてつかんでいると思うのですが、もしそれがありましたら伺いたいと思います。単純にこの今の計画図を見ますと、１６棟ですかね、建物が範囲内に入っているというふうに見えますので、この中にはマンションもあるのかな。","respondent":"中道まちづくり立体化担当課長","answer":"そうしたところも、今後、東京都と連携しながら、また検討していきたいと考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"補償は金銭補償が原則ということですが、原則ということは、求めれば代替地も確保されるということか、そこも伺いたいと思います。駅前広場との関係、進捗、そこを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"補償に対しての仕組みについては、東京都と今後、検討して、仕組みづくりをしていきたいと考えています。北地区との関係性ですが、今回、交通広場ですけれども、今、北地区で準備組合があります。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問","question":"私は２点ありまして、１つは、先ほどの質問の中で、交通結節機能を強化というところで、タクシーと自家用車、そして、バスというふうにもお答えされたと思いますが、そのほかにも何かありますでしょうか。シェアサイクルの設置場所というのもやるのかどうかというのを、分かる範囲でいいので教えてください。","respondent":"中道まちづくり立体化担当課長","answer":"観光バスについては、検討する中で、今後、詳細に検討するのですけれども、現時点では観光バスを中に入れるという考えはなく、そこにやはり大きい車を入れるとなると、敷地が大きくなるというところで、ご協力いただく用地も多く必要になってくることになります。","id":"exchange-010"}]},{"id":"topic-03","title":"環境講演会","agenda":"環境講演会","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点確認ですけれども、フードドライブをまた今回も開催されるということで、今、区民の方々、お困りの方がたくさん増えていらっしゃいますので、できる限り受入れをしていただきたいという思いがあってお聞きするのですが、フードドライブの受付時間ですとか、あと、今回何か新たに、前回と比べて変更点ですとか、何かありましたら教えてください。","respondent":"河内環境課長","answer":"利用しやすさなども含めまして、工夫を重ねてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"この環境講演会ですけれども、３００名の定員で７００名の応募があったということですが、来られない方が、行きたいけれど行けないという方がたくさんいらっしゃると思うのですが、この講演会というのを、その後、区のホームページで、例えばＹｏｕＴｕｂｅであったり映像であったり、行けなかったけど行きたかったなという人が見られるような状況というのをつくる計画はあるのでしょうか。","respondent":"河内環境課長","answer":"ただ、今回に限りましては、ＹｏｕＴｕｂｅの発信となりますとまた別の契約料金もございまして、環境講演会だけでやれば５０万円というところでご理解いただきながら、進めさせていただきまして、また別の講座などによりまして。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"参考までに伺いたいと思います。今、澤田委員が質問された、いわゆるＹｏｕＴｕｂｅ等になると、ほかの契約ということですが、この講師料というのは大体どれぐらいになるのでしょうか。予算はどれぐらいで計画されているのでしょうか。かなりの応募倍率になっていて、有名な方々を講師にお招きするとなると、大体、今回はどれぐらいの予算でこの講演会が行われるのか、参考までに教えてください。","respondent":"河内環境課長","answer":"相場感で言うと大変、何か少し言い方はあれなのですが、ディスカウントをお願いするといいますか、値切るといいますか、趣旨をご説明させていただきまして、併せてエコルとごしなどで行われておりますフードドライブの件も説明させていただき、公共へのご協力というところで。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いしますが、まずこの人選についてお伺いしたいと思います。この方のＹｏｕＴｕｂｅ、私も以前から見ていて、料理研究家と言いながら、料理をする前に自分でハイボールを飲んでべろべろになるような方で、非常に面白い方なのです。これ、まず誰が選ばれているのかというのを１点、お聞かせいただきたいのと、あと、今の澤田委員の質問にも関連するのですが、非常に多くの申込みがある。","respondent":"河内環境課長","answer":"こういった点を踏まえまして、啓発の実績成果を念頭に置きながら、今後、人を選んでいき、また発信方法もいろいろ工夫しながら、多くの方が見られるものと、それから、見た方がやはり感銘を受けてしっかり取り組めるものというところのバランスを取って。","id":"exchange-014"},{"speaker":"芹澤委員","kind":"意見","question":"本当に大変すばらしいなと思っていますので、ぜひ応援していきたいと思います。もしそうだとしたら、多分７００人どころではなくて、区外も含めて大変多くの申込みがあって、品川区のブランドにもなるのかなと思いますが、そこの取組を、最後お聞かせください。","respondent":"河内環境課長","answer":"こういったところでいかに発信していくかですが、先日、エコルとごしにジョージア国の農業副大臣がお見えになられて、全世界的な課題として、やはりエコルとごしのフードマイレージだとか食品ロスの取組を見て、大変参考になったということで戻っていかれましたが。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"すみません、今の議論を踏まえてですけれども、ＳＮＳですとか、あとはオンラインで見られるようにするということも、区として今後検討されていくというほかの委員のお話などもあって、そういったことを検討に含めていくのも、とても大事だとは思うのですけれども、これまでどおり品川区のスクエア荏原、武蔵小山に足を運んでいただいて、リュウジ先生に生で会って、その生の体験を感じ取るであったり。","respondent":"河内環境課長","answer":"生にこだわる大きな要因ですが、ＹｏｕＴｕｂｅで発信いたしますと、それ以降の二次側には発信がないのですが、生で体験された方というのはそこからまたさらに発信があって、その共感力が非常に効果的だという点で、エコルとごしのそういった登録をされている方も。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"広報の仕方ですとか、あと区民の方々の年齢ですとか関心ですとか、そういったものが多様化してきておりますので、これまで区でやってきていただいたような、きちんとした知見に基づいた発信というのも、すごく勉強になってきたと私は思っておりますが、ただ、さらにこれからの新しい時代に向けては、いろいろな手法ですとか技術ですとかマーケティングの考え方ですとか、また増えてきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16846,"voices":60}},{"id":"r05-20230123-9","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"文教委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"令和４年度第２回家庭教育講演会","agenda":"令和４年度第２回家庭教育講演会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それに関連して質問ですが、教育講演会の内容の検討とか決定過程の基準などがもしあれば、教えてもらいたいのが一つです。これはかなり前からやっていると思うのですけれど、いつからこういう講演会はやっていたのか、お伺いしたいのと、この講演会ではないとは思うのですけれど、旧統一教会や関連団体の講師を採用したりというようなことがあったのか。調査などはされたのか、というのを伺います。","respondent":"宮尾庶務課長","answer":"他の自治体での講演のご実績ですとか、例えばホームページなどをお持ちの方たちはそういったこともしっかり確認しますし、ある特定の考え方ですとかそういったことによらない中立で公正な方、こういったことも講師の方を選ぶ基準の一つとしています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"この内容などを検討して決めるというのは、どなたが、どういうところでやっているのかお伺いしたい。平成一桁から行っていることは確認したというお答えでしたけれど、それ以降、旧統一教会とか関連団体の講師を採用したりということはなかったということなのでしょうか。確認させていただきたい。","respondent":"宮尾庶務課長","answer":"つぶさに該当するかどうかという調査自体は行っておりませんが、過去にそういった関係の方はいないというふうに認識しております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ報道もされているところなので、その調査は、この講演会についてはぜひ行っていただきたいと思います。保護者の方も同じ様に言っていました。こうした保護者の声とかご指摘とか、そのガイドラインを策定してほしいという要望について、区教委には届いておりますでしょうか。伺います。区教委の現時点での考えとか取組、検討状況がもしあれば教えてください。","respondent":"宮尾庶務課長","answer":"こちらはしっかりつぶさに見させていただいて、毎年作るときに、例えば、この年度内にはこういうことがあったから、次はもう少しこういうところの記述を厚くしよう、こういったことも日々私どものほうでやらせていただいているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のお話ですと、年度によってガイドラインを変えているということなのか。ガイドラインを作っているということなのですけれど、先ほど言ったようなお声もあったので、現在のガイドラインというのを少し見直してほしいというようなご要望があるのです。それは、現在見直す方向に入っているのでしょうか。","respondent":"宮尾庶務課長","answer":"実際に、今まさに令和５年度に向けてガイドラインを最終的に作っている段階ですけれども、そういったご相談内容をその場限りとしないで、全体に向けて横展開をするべきだという内容に関しましては、その辺も盛り込んだ上で。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"今の家庭教育学級のガイドラインの部分で、関連して伺いたいのですけれど、そういった冊子があることは認識しています。安藤委員がおっしゃったように、家庭教育学級で、どういった会を実施したらいいのだろうと悩まれている方は確かにおられて、多分その冊子の存在が知られてないのかなということも思うので、配付の対象というか、そこら辺をお知らせいただきたいのですけれど、いかがでしょうか。","respondent":"宮尾庶務課長","answer":"ですので、ＰＴＡによっては必ずしもご担当でなく、例えばその時出席された方、あるいは会長であるとか、いろいろな方が想定としては考えられます。その事務説明会の配付用という位置づけでお作りしています。","id":"exchange-005"}]},{"id":"topic-02","title":"令和５年度品川区立学校における土曜授業の実施","agenda":"令和５年度品川区立学校における土曜授業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年度から減らしたということで、１０か月ほどたっていると思うのですけれど、現場や当事者の受け止め、主にどのような声などを聞いているのか、伺えればと思います。子どもと保護者と学校、それぞれについてもしあれば、教えてください。","respondent":"矢部教育総合支援センター長","answer":"お子さんたち、保護者からも特段、私ども具体的なお話は聞いてございませんが、学校を通して、まだ３月まではきちっとお話を聞きながら、対応してまいりたいと思います。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、量も大事かもしれないですけれど、質が大事かと思っていまして。子どもたちが自分たちで自由に、工夫して活動できる時間というのも必要だと思いますので、土曜授業を減らすことになったというのは、私としては非常にいいことではないかと思います。は限られた時間でいかに教育活動の質を上げていくかということについては、これからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"を、改めて聴取いたします。 (3)今後の児童センターの方向性","agenda":"を、改めて聴取いたします。 (3)今後の児童センターの方向性","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"児童センターの数なのですけれど、これは維持するということでよろしいのか。確認させていただきたい。3)の課題のほうに、人材育成による児童センターの強みの継承とありますけれど、これはどういうことを指しているのか、強みとは何なのか、お願いします。","respondent":"廣田子ども育成課長","answer":"その他の、それをどういかしていくかというところには、先ほどご説明したとおり、人数構成とベテランとの構成を変えることで、育成がしやすくし、今の強みを継承していくというところを話し合っております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"業務委託の拡大と書いてあるのですけれど、これはどういう意味なのか伺いたいのですが、現在、児童センター２５館、直営館１３館ということなのですが、この直営館を減らすということなのでしょうか。それと、児童センター配置の５７人、職員定数があると思うのですけれど、これは退職されたら補充しないという形で定数を減らしていくということなのでしょうか。伺います。","respondent":"廣田子ども育成課長","answer":"具体的にはこれから、もう少し大きい目で、人を減らして委託にすげ替えるということでなく、職員の人数であったり、スキルで足りない部分で委託の力を借りるという考え方で、進めていこうと考えております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。最後ですが、今後の話なのですけれど、令和５年度以降の具体的な検討とは、いつからどのように進めていくのか伺いたいと思います。検討に当たり、子どもの権利条約とか東京都こども基本条例の精神に基づいて、その具体的な検討についても、当事者の子どもたちの参加というのを求めたいのですが、いかがでしょうか。それだけ確認させてください。","respondent":"廣田子ども育成課長","answer":"今後の検討なのですけれども、１３地区あると思うのですけれど、ベテランが大分減ってきてしまうので、地区をどういうふうに見ていくか、地域とどう関わっていくかということであったり、地域の特色はどうなのかというところを、現場の声は今回も聞いたのですけれども。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ子どもの意見を取り入れて、いい方向に進んでいっていただきたいと思います。この具体的な検討は、いつから始まっていつまでに終わるかというのは、まだ今のところは明言できないのかということと、もうすぐ４月だと思いますけれど、検討メンバーというのはどのような方を考えているのか、もう一回聞かせてもらえますか。","respondent":"廣田子ども育成課長","answer":"検討に関しましては、今、方向性は示したのですけれど、保育園との合築がほとんどなので、どこから建て替えていけるか、なかなか難しいので、比較的建て替えられそうな、保育園と合築でないところで具体的に。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"伺いたいのですけれど、若者との連携のところで、南品川になった理由を伺いたいのですけど、児童センターマップを見たときにも、図書館の滝王子の場所や公園とのコラボの場所というのがちょっと偏っている、何と言ったらいいのか、若者の場所がちょっと離れている、中心からずれているというか。そこになった理由は何なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"例としてこういう状況に今ありますよと教えているだけだから、地域がどうこうでなくて。今の立地条件だとこういうふうになっていますと書いてあるだけなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。ハードだとやはり時間もかかってしまうので、各児童センターで今できること、そういうソフトの面はぜひすぐにでも進めていただきたいというのと、中高生が児童センターを利用していい、利用できる場所なのだという周知がされていないというか、認識が広がってない状況もあるので、そういったことをぜひ広げて、アピールにも力を入れていただけたらと思うのですが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"中高生につきましては、９館の児童センター、ティーンズ館で、この３年はコロナでできなくて縮少してしまったのですけれど、少しずつ取り組みができるようになっています。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"中高生になるとほかに欲求は出てきますから、そこに合致すれば、いっとき総合体育館でやっている卓球など、すごい人数の中学生が参加しているときがあったりするのを見ていると、１割ということは、でも１割といっても相当な人数だなと思っていたのですが。いわゆる１３館体制を維持するというところから入ってしまうと、話が違うのかなと思うのですけれど、その辺の考え方はどうなのですか。","respondent":"廣田子ども育成課長","answer":"地区ごとの広さとか特性もありますので、それも踏まえて、児童センターは地区とどうあるべきかを、先ほどご説明したとおり、もう４月からすぐ、１３地区と児童センターがどう関わっていくか、エリアも含めて検討をしっかりと、主任児童委員とも意見を聞きながらやっていかないと。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そういうことを全部総合的に考えて、配置とかいうのはこれからやっていくと思うのですけれど。それと人手の問題も、確かに品川区の児童センターを支えてこられた方々が、もう引退をどんどんしていっているのも事実で、昨日も館長に会いましたけれど、もう終わりだなどと言っていたぐらいですから。感想です。これは回答は結構です。これはこれからなのでしょうから。要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"江野下委員","kind":"質問","question":"公園とのコラボ、特色のある編成というところで、スケートボードですとかバスケットボール、これは音の関係でなかなか、こちらにも実現するのは難しいと書いてありますけれども、例えば期間限定とか、そういったことで運営していくことは、可能性はなきにしもあらずでしょうか。","respondent":"廣田子ども育成課長","answer":"左側の案というのは、現場で働いている児童指導の職員が、こうだったらどうだろうというところに対して、庁内の検討会の中で合築している施設がある課長たちに来てもらって、将来も含めて意見交換したのですけれども。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのが、職員の年齢分布についてです。例えば、児童センターがそういったパターンに当てはまっていて、４０代がゼロになっていたりするのか、そのあたり、例えば給与の上昇であったり、所得の部分であったりとか、４０代が０％という部分についての見解など、お聞かせください。","respondent":"廣田子ども育成課長","answer":"今の２０代、３０代が４０代、５０代になっていくときには層が厚くなるので、その分は、委託で済むものは委託の力を借りるということをして、今はなかなか採用ができない、１００人欲しいといっても１００人来ないという状況なので、引き続き。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"別の部分で伺いたいのですけれども、ちょっと基本的なことになってしまって申し訳ないのですけれども、各児童センターに対して振り分けられる予算であるとか、そこの部分というのはあくまで各事業ベースで必要な予算を、それぞれの児童センターが予算要求のような物を当初にしていって、その中で承認された分を予算として認めているのか、それとも、例えば規模とか利用人数。","respondent":"廣田子ども育成課長","answer":"その他フリーで使える予算については、児童センターの経費を、どちらかというと利用人数で案分しますけれど、足りない分は本課にこれをやりたいと、足りなかったら本課のお金で必要があれば買ったりしているので、児童センターでお金を持っていて。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問・要望","question":"本当にシンプルな話ですけれども、電池を使うおもちゃ、それが電池が入ってない状態で放置されていたり、電池が切れていたら補充して、きちんと使える状態にしてあるところ、そこというのは、あくまで予算がないから経費削減というより、電池を頻繁に交換して、切れたら交換というふうにまめにする余裕がないわけではなく、あくまで個々の館の考え方というか、どこに力を入れるかという部分によって。","respondent":"廣田子ども育成課長","answer":"電池については、職員が入れて遊ぶ、声をかけてもらってやるであるとか、お子さんの年齢に応じてというところなので、あまりこの方向性云々というよりも、お金云々とも、またちょっと違うかなというところなので。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に意見として申し上げておきますけれども、もちろん各児童センターで利用者の方々の声等は、真摯にお聞きになられていると思いますけれども、さらにもう少し利用者の方々が、こういった部分を改善してほしいとか、こういった部分をより充実させてほしい、そういった声を今以上に、気軽に声を寄せられるような目安箱というか、利用者の声をもっと気軽に拾えるというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"５ページに、改めてといいますか、文字で見るとそうだよなということなのですが、根拠法の児童福祉法が載っています。いずれにしても公園課と課長の理解、協力を得ながら、子どもの健全な遊び場として工夫できるのであれば、１か所でも多くそういう場を与えていただきたい、増やしていただきたいと、これは要望として申し上げておきたいと思います。","respondent":"廣田子ども育成課長","answer":"障害者支援課長に来ていただいたのが大原の児童センターで、インクルーシブひろばベルが１階にあるという立地だったので、今後、相談事業もお互いやっていったり、サロン的なところもあるので、ぜひインクルーシブなサロンというのがあったらいいのではないか。","id":"exchange-022"},{"speaker":"松澤副委員長","kind":"質問","question":"若林委員とかぶってしまったのですけれども、公園課との話合いというのは、児童センターの方向性について検討がなされたから話合いを始めたのか、もともと公園課とのそういう話合いというのですか、遊びの提供もあったのか、まず教えてください。","respondent":"廣田子ども育成課長","answer":"公園課とはプレイパークのことで結構お話をしたりとか、今、荏原地区にプレイパークがないので、旗の台公園で外遊び事業というのを月２回やっているのですけれども、建物が旗の台の保育園の前なので、保育園も文化センターも、利用者への支援に関して協力してもらって。","id":"exchange-023"},{"speaker":"松澤副委員長","kind":"質問","question":"児童館とはまた違って、児童センターというのは運動能力に特化しているものだと、私も思っています。何もできないというと、言い方が失礼ですね。子どもの遊びが縮小してしまっている。そういった人員配置について、考え方、方向性といいますか、そういうものというのは、区で決められるものなのか、もう決まりがあるから、なかなか動かせないものなのか、そこら辺を教えてください。","respondent":"廣田子ども育成課長","answer":"区としては採用したいのですけれど、現場の職員にも言っているのですが、採らないのでなくて採れないので、決して減らしたいというわけではなく、配置できないというのが現状です。","id":"exchange-024"},{"speaker":"松澤副委員長","kind":"意見","question":"分かりました。申込みがないと理解しました。申込みがないというのは、何か世の中の流れなのか、あまりそういうところに勤めたくないのか、難しいところだと思いますけれども、魅力のあるセンター職員、そういうことがどんどん広報できて、人員なども確保できるように、一緒に頑張っていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-04","title":"令和４年度 小中学生の生活状況調査、ひとり親家庭状況調査の結果","agenda":"令和４年度 小中学生の生活状況調査、ひとり親家庭状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、これは内容、項目についての要望なのですが、１－１の世帯の人数でありますけれど、今はこういう人数なのですが、理想の子どもの数というのも伺えると、経済的要因と出産、子育てがどのように影響しているのかというのが把握できると思うので、そういった質問項目なども追加していただきたいのですけれど、いかがか。４点目は、３ページの塾、家庭教師の利用です。","respondent":"飛田子育て応援課長","answer":"前回は平成２８年に行いましたが、今まで子ども未来応援プロジェクトでいろいろ各事業の検討はしておりまして、今回は第２期の子ども・若者計画の制定に向けて、もう一度やろうということで行ったところです。前回の調査と今回の調査を比較して行ったということになります。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それと、１枚目のＡ４の資料の概要というところに載せてありますが、これでどういう実態・ニーズを把握したと考えているのか、どのような支援策を計画されるお考えなのかというのが、これだけだと分からないので、そこについてはおいおい報告もあるのでしょうか。それは感想なのですけれど。区としてはどういう実態を把握して、どういう支援策の検討を重ねたのかというのを伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"そういうことも今回のアンケートだけではなく、通常の事業等、また区民とも接する場がありますので、そういう中から、そういう変化にいち早く気づきながら、先手を打てるように努めていこうかと考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"この詳細、調査全体の発表についてはどうなのかということと、今、識者の方のお話を聞いたのですけれど、女性の正規社員化に伴い、収入は増えたけれど、何らかの課題が出てくるのではないかというご意見を紹介されました。何らかの課題というのはもう少し具体的に、ご説明いただければと思います。","respondent":"飛田子育て応援課長","answer":"それと女性の就業率というところですが、我々としてもまだそこまで、実態というのはつかめていないのが正直なところです。ですので、そういうところはまた、何らかの機会に、保護者、またそういう現場の声とか、聞きながら、また解明していければと考えております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変貴重な調査ですので、ぜひ深めて、支援策につなげていっていただきたいと思いますし、結果については全て、主なものだけでなく、ホームページで、ぜひ進めていただきたいと思います。現在、高校生には拡大して給付型が、結構もう、５年、４年ぐらいたっているのではないですか。現在、そういう大学生の対象検討というのはしているのか、伺いたい。どのようなものがあるのでしょうか。","respondent":"飛田子育て応援課長","answer":"ですので、私のほうも、国が実施している様々な支援策とか効果とか、今後の動向などは注視していきたいと考えております。ただ区としては、現在、高校生のほうを返還免除型の給付と高校生応援事業をやっています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり今の事業ではなかなか実態に合わないというか、まだまだ足りないと思うのですね。第４回定例会の一般質問でも紹介したように、足立区では大学生も対象にした給付型の奨学金に踏み出しましたし、ぜひ、こうした区の、自ら行ったアンケート調査結果からも、大学生も給付型の奨学金の対象にしていただくよう、検討をぜひしていただきたいと改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"「知っているが利用したことはない」という方たちは、どちらの意味だったのかなということと、あとちょっと伺いたいのが、子ども食堂のマップというか冊子があるではないですか。それは学校で配布とかはされているのかどうかというところを確認させてください。この改善に向けては、どのように今、区は考えられているのかというところを伺いたいのですが、２点伺います。","respondent":"飛田子育て応援課長","answer":"養育費の取決めについては、なかなか、まだまだ難しいというか、相談件数はありますが、まだそこまで話が行ってないとか、離婚する、しないの最初の段階での相談はあるのですけれど、離婚が決定するのか、しないのか、そこのところでも大分違うので、ただ。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"子ども食堂についてです。では、マップは児童センター等には置いていても、学校では配布は特にしていないということですよね。養育費の取決めについては、やはりとても重要だと思うので、ぜひ引き続き、区としても取り組んでいって、この数値がもうちょっと上がるように、取決めをしてないというのが減るように、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"何点か伺いますけれど、最初の調査概要で、小中学生の生活状況調査というのは、２年生と９年生でとっていると書いてあるのですが、これは何かルールがあって２年生と９年生でとっているのかというのを教えてください。それで、このアンケート自体はどういう目的でとるのかというのは、安藤委員の質問でよく分かりました。中央値というのをよくとるではないですか。","respondent":"飛田子育て応援課長","answer":"それで、やはりこういう違いということがありました。今後何かしら調査があるときは、その辺もまた再度見直して、アンケートの項目等、また考えていきたいと思います。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"それがいい、悪いという話ではないのですけれど、そういうものなのですかね。全数調査をやるのだったら、逆に１年生から９年生ととってしまって、パイを大きくしてもいいのかなと思いました。これは２年生と９年生に全数調査かけているのでしょうから。そこで７年、パカッと空いて上と下をとってしまっているから、そういうところの問題があるのかなというふうに思ったので、その辺を聞かせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"新妻委員長","kind":"質問・要望","question":"ほかにいかがでしょうか。私のほうから３点、確認します。それと、このアンケートは配布となっておりますので、紙ベースだと思うのですけれども、データでの返答が可能なのか。ですので、この結果の中から、そこをどう読み取っていただいて、どういう支援につながっていくのかというところが、私は求めたいところだなと思っているのですが、そこら辺のお考えをお聞かせいただきたいと思います。","respondent":"飛田子育て応援課長","answer":"このアンケートの回答が見えない部分はどうしても、こちらとしても判断がなかなか難しいというところがありますので、今回も少しでも答えやすいような質問ということで、２０問以上にならないようにということで配慮して、前回もそうだったのですけれど。","id":"exchange-035"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"確認","question":"感染症が広がった時の利用については、もう行かなかった月にはその分利用料もかかりませんといったことでしたが、それは来年度もその形になるのかというところも、確認をさせてください。","respondent":"廣田子ども育成課長","answer":"このまま、この調子でいくのですけれども、国のほうの状況がまた変わってきたので、それを見て４月には決めようと思います。１年生は大体使っていただいているのと、使いたいですと言って断ることはないので、その辺りについて、担当指導員が丁寧にご説明しようと思っています。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39993,"voices":105}},{"id":"r05-20230123-5","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"総務委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"この陳情文の中に、実際にオープンハウス型説明会に行ったところ、質問をしたら、「職員は資料がないからと基本的な質問に答えず」というような記述があるのですけれども、その場で必ずしも全員が説明できるというのは難しいこともあるかなと思うのですが、例えば、今は手元に資料がないので答えられないけれども、後日、別の形で答えるとか、そういうこともされていないということなのでしょうか。","respondent":"佐藤（聡）計画担当課長","answer":"説明者に対して参加いただいた方から直接伝えていただくこともできますし、また、アンケート用紙を用意しておりまして、そこにご意見を書いていただいて、ご意見をいただくということも可能というふうにご案内いたしまして、そのような形で開催させていただいたと聞いております。","id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"その辺についてさっき伺ったのですが、必ずしもそのときに全員の質問に答えられるとは限らないというのは十分理解できます。このケースについてはどうだったか、個別のこの方のケースとは限らないと思いますが、その場で答えられなかったときに、最終的には区としての答えがきちんと行ったと理解していいのでしょうかということを確認させてください。","respondent":"佐藤（聡）計画担当課長","answer":"この方についてということで間違いないと思うのですけれども、別途、メールで所管課に質問みたいな形で受けておりまして、個別に対応していると聞いておりますので、質問された方に対しては真摯に、個別に対応していると聞いております。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと突っつくようで申し訳ありませんが、今のお答えだと、改めてメールで問合せが来たから答えたという感じですよね。本来であれば、その場で答えられなかったら、後ほどこういう形でお答えしますというふうにすべきと考えるのですけれども、その点について、品川区としての基本的な考え方を改めて伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"時系列でメールが後か先かというところはあるかと思いますけれども、所管課では、個別に、お答えを求められれば対応していると聞いておりますし、１００％全部、個々、別々の質問に答えたかと言われますと、まだそこまでは確認しておりませんが、ただ、答えが欲しいと言われれば。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"この方については、後か先か分からないけれども、メールでもお問合せがあったということなので、答えられたのだと思いますが、この陳情者の方以外でも、ぜひそのような対応を今後もしていただきたいし、この陳情の中で求められていますけれども、やはり教室型の説明会というのも必要ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"まちづくりマスタープランのほうなのですけれども、オープンハウス型説明会を４回やって、来場者が３５９人ということなのですが、教室型説明会をやらなかった理由というのは、区としてはどう考えられているのか、その点を伺いたいと思います。それがなぜ基本構想ではされなかったのか、それがなぜ基本計画になったときにされることになったのか、そこの考え方についても伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"まちづくりマスタープランのほうですけれども、委員ご指摘のとおり、今回についてはオープンハウス型の説明会を４回実施しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"教室型の説明会を、これまでも様々な計画のところで求め続けてきているのですけれども、品川区の考え方として、教室型の説明会をやるという方針にならないのですよね。本当に様々なところで、ほかの区は、計画の説明会は教室型の説明会を様々されているのです。これは区全体のところでの考え方というのが、そこがあるのではないかなと思うのですけれども、その点はいかがでしょうか。","respondent":"佐藤（聡）計画担当課長","answer":"オープンハウス方式でありますと、冒頭申し上げたとおり、お一人の方にできるだけ時間をとって説明をするということもやっておりますので、あまり方式にこだわらずに、内容についてきちんと伝わるような形で開催していくことが大事かと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、区全体として、区民にどれだけ区の計画を理解してもらいたいのか、理解してもらって、そして区としてもしっかりと意見を受け止めると。そういうところでの教室型説明会というのは、区としても、区民に計画を理解してもらう、区民の意見を出してもらう、そういうところで教室型説明会というのはしっかりと位置づけるというふうにすべきだと思うのですけれども、その点はいかがでしょうか。","respondent":"佐藤（聡）計画担当課長","answer":"ほかの方のご意見を聞くという場もということですけれども、全体の審議会等も、議事録を含めて公開しておりますので、そういったところで、ご自分のご意見と比較しながら、パブリックコメント等も含めて、ご意見を出していただいて、それを受けて。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点は一つ伺っておきたいと思います。ただ、それだけでは足りない。それだけではなくて、区民が求めているのは、教室型の説明会で、ほかの人の意見も聞きながら、自分の意見もその中で述べていくこと。あらゆる計画の基本的なところに関しては、区民に対して理解してもらうために、教室型説明会を位置づけるというふうにぜひしていただきたいと思うのですけれども、その点、いかがでしょうか。","respondent":"佐藤（聡）計画担当課長","answer":"そうした中で、どういった説明をしていくかというところですとか、どういった形で意見をいただくかというところにつきましては、現在のところも、今回ご説明した２例以外にも、十分果たしていると考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民が求めているのです。それは、区民が理解するためにも、それから自分たちの意見をしっかりと聞いていただくためにも、教室型説明会という形でやっていただきたいというのは、区民が求めていることなので、そこのところはしっかりと品川区としても受け止めていただいて、あらゆる基本的な計画に対して教室型の説明会というのをしっかりと位置づけていただきたいと思います。それが１つです。","respondent":"佐藤（聡）計画担当課長","answer":"説明会の方式につきましては、先ほど来、申し上げたとおりで、それぞれの計画に沿って工夫をしていきたいと考えております。説明会への参加者が少ないのではないかというご指摘についてです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"初めはやはり参加者が少なかったのです。それから庁舎の問題でいえば、「区民による区役所跡地活用検討委員会を設置し、区民ニーズを叶える街づくりを推進」というのが森澤区長の公約にも掲げられましたけれども、区民による検討委員会を設置するという、この公約というのはこれからどういうふうになっていくのか、具体的な中身についても伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"区民とともにつくっていくというところでいきますと、説明会等も含めた手法については、先ほどパブリックコメントの例も出しましたけれども、手法については今後も研究していきたいと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会をしっかりとやって、区民が意見を聞き合う場、意見交換の場、そういう場をぜひともつくるという方向で、これまでの方針をぜひとも変えていただきたいと強く、ずっとそういうことを要望し続けていますけれども、改めてこの陳情を見せていただいて、新区長になったところで、ぜひともここのところは変えていただきたいということを強く要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"パブリックコメントもこれだけいただいて、これは実際、審議会の委員にもそれは伝わるわけですから、皆さんの声は、疑問点なんかは伝わっているのではないかなと私は思います。これは品川区として区民に真摯に説明しているということで、おおむねよろしいのではないかと私は思います。これだけやっているということは、計画担当課長もそれなりのことをやったのではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"区民アンケートをとりながら、改定委員会や策定委員会などでも、公募区民に委員として入っていただいて、区民ニーズと行政機能が反映されるような検討が進んでいると思っているのですけれども、区民ニーズをどのような形で取り入れていく、そういった努力をされているのかというのを改めて確認させていただいてよろしいですか。","respondent":"佐藤（聡）計画担当課長","answer":"あるいは、国等の法律に基づいてつくる計画においては、国等の審議会ですとか、そういった場で国全体としての課題というのが出されていることが多くありますので、そういったところでニーズを捉えて、その解決といいますか。","id":"exchange-013"},{"speaker":"湯澤委員","kind":"質問・要望","question":"この陳情者の方は、意見交換の場が全くないとか、区から丁寧な説明がないとのことでありますので、今ご説明があったように、区としては区民ニーズを活かす努力をされていることは十分理解できますので、さらなる研究を進めながら、より区民ニーズを取り入れていただきたいなと考えています。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"大倉委員","kind":"確認","question":"今、いろいろと皆さんのお話も聞いていて、区のほうでも時間をとって丁寧に、個別にも対応して、ご説明をして、質疑の時間もとりながらやっているというお話を伺いました。そういった発信を今もされながらやっているのだと思うのですが、その辺の発信について、どのような状況なのか、改めて教えてください。","respondent":"佐藤（聡）計画担当課長","answer":"パブリックコメントに関しては、ホームページのほか、それぞれの所管の窓口等に案を置いて、見られるようにするということもやっておりますし、始まるときには、広報しながわでも概要についてご説明する記事を載せたりという形で。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"ホームページ、窓口、広報しながわ等で、できるだけ区民の方の目に入るようにということで、工夫をされてやっているのだと思うので、これ、どこまでどうやったらいいかというのがすごく難しいところかなと思っていまして、いろいろな手法を使ってもなかなか周知ができないというところは、いろいろなところで課題なのだろうなというところで、でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。私は、品川区ほど基本的な計画について区民への教室型説明会を行わない区があるだろうかと前々から思っていました。区として、区民に説明をして、理解をしてもらい、意見を聞くと。品川区としても積極的に発信していただきたいと思いますし、教室型説明会を積極的に行う方針への転換を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほどもちょっとお話ししましたが、区のほうも様々工夫をしながら周知をして、意見も様々対応しながら行っているというところで、ぜひ丁寧に対応していただきたいと考えていますし、手法についても、陳情に書いてあるようなところも含めて、様々な手法を効率的・効果的に行うことが必要だろうと考えていますので、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"つい、先ほどは説明会だったのですけれども、やはり区民参画の場を保障する形での、その一つの入り口としての教室型の説明会というのをぜひ進めていただきたいと思いますし、区民の参画というのを、今の理事者側の方たちで求めておられない方は１人もいらっしゃらないと思います。ぜひそういう形の第一歩として、やはりこういう協働で策定するということを求める陳情には、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、不採択でお願いします。きちんと回答もしている。その中で、我々区議会議員ですけれども、区議会議員もやはり区民の代表として、皆さんの意見を集約してお聞きして、そして区議会でも新庁舎整備基本計画とかそういうものも議論して、意見も述べています。代弁者としての役割もきちんと、こういうことは直してほしい、改善してほしい、こうやってほしいという要望も出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由としては、先ほども出ていたように、区民アンケートで区民のニーズを拾っているということと、説明会はしっかり行われて、不安のある区民の方にはしっかり時間をとって説明をしていただいているということなので、今回、討論会や地域別のワークショップなどをされたい方もいらっしゃると思うのですが、満遍なく区民の意見を聞く場が望ましいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"第25回品川区世論調査","agenda":"第25回品川区世論調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この世論調査は２年に一遍やっているということなのですけれども、この結果を区としてはどういうふうに評価して、これからの区政運営にどう活かしていくかというものが何かあるのであれば、教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"世論調査の質問の項目につきましては、各所管から希望調査をいたしまして、広報広聴課のほうでヒアリングを行い、調整して項目を決めておりますので、このような調査がしたいという希望をした所管にこの調査結果を戻して、今後の施策の参考にするというのが基本的なスタンスです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう施策のところに対しての評価がそれほどないということに対しては、どういうふうに考えられているか。それは広報広聴課の所管ではないのかもしれないのですけれども、全体としてもそういうところをどう考えられるのかということを、世論調査の中からどう検討課題にしていくのかというところがあるのか、その点についても伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"例えばリサイクルとか、みどり、防災というのは比較的新しい項目ですが、それでもやはり１０年以上継続して聞いている、調査している項目ですので、このような近年になって課題となってきたことについても、区民の方のご意向を調査して、活かしていくという姿勢は同じです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、私はやはりこの世論調査を受けて、各所管に戻すということなのですけれども、各所管からもこれを充実してほしいというのは多分出されているのではないかなと思うので、企画部門になるのかもしれないのですが、こういう世論調査を受けて、評価が下がっているというところも鑑みて、ここのところの充実にぜひ持っていっていただきたいなと思うのですけれども、そういうところではいかがでしょうか。","respondent":"大澤広報広聴課長、佐藤（憲）企画調整課長","answer":"経年でずっとやっている調査の傾向というのは、やはり区民の方の意向ということで重要なものだと思いますので、その点に関しては、経年でやっていることの意味というのは、区全体で検討していくべきことだと認識しています。広報広聴課長からご説明があったように、大きな経年の変化を見るために、基本的に大きなところを聞いているというところでございまして、当然この個別の内容に関しましては、所管にも戻しますし、あと。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者の施設にしても、障害者の施設などにしても、本当にまだまだ足りなくて、実際、品川区のそういう施設の整備率というのは本当に低い状況だというところが、こういうところに出ている部分もあるのかなという思いが私はしています。そういう点では、こういう世論調査も受けて、ぜひ充実をさせていただきたいということで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"確認","question":"それで、４ページの重点施策について、災害対策、生活安全、防犯対策、やはりこれは区民の不安の表れが出ていると思うのです。やはり我々もよく聞くのですが、９ページで、週に１日以上、健康・体力づくりのために頑張っていますと。このような世論調査あらましをこうやって出していただけると、その状況がすごく分かるので、今回、調査結果の概要を見せていただいて、再確認できてよかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"すみません、私、前にも同じようなことを伺ったかもしれないのですけれども、こういう調査は、例えばクロスチェックみたいなものはされているのでしたか。もっと言えば、今後また調査をするときに、ある程度クロスチェックできるような項目を増やすことによって、その後の施策に活かすということも検討したらいいかなと思うのですが、その辺についてはいかがでしょうか。","respondent":"大澤広報広聴課長","answer":"それで、ご質問にありましたクロスチェックですけれども、報告書の後ろのほうに、全て、地域や年代、職業やライフステージ別にクロスチェックを行っておりまして、町会・自治会に期待することにつきましても。","id":"exchange-027"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。では、報告書のほうでもう少し詳しく見せていただいて、私たちとしての今後の政策提案にも活かせるところがあったら、そういうふうに活用させていただきたいと思いますので、また何か伺うことがあったらよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2258#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":23913,"voices":71}},{"id":"r05-20230124-14","meetingId":"r05-cm01","date":"2023年1月24日","dateIso":"2023-01-24","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"新庁舎に関すること","agenda":"新庁舎に関すること","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これで基本計画が策定できたということで、進んでいくことを期待しています。なるべく早く進めていただきたいと思うのですが、その中で何点か確認させてください。今日のこの変更の中で、まず以前にやっていた品川区新庁舎整備基本構想・基本計画策定委員会等に対して、委員長または委員の方にどのような形で変更があったということを伝えていくのでしょうか。その点について聞きたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回につきましても、策定に至る段階で答申からの変更点はこういったところがあるということは、別表をおつけする形で丁寧な説明に臨んでまいりたいと考えています。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"特に建設予定地とかで出てくる第二庁舎が、私は取り壊したほうがいいと言っていたのですが、基本的に残した形で進めていくということでスタートしている中で、今回方向性が変わってきたということになると、その辺は丁寧な説明が必要だと考えています。これから今までのような検討委員会のようなものを作っていくのか、その点についても教えてください。","respondent":"山下新庁舎整備課長","answer":"その後のいわゆる委員会の設置といった部分につきましては、今、第４回定例会等でのご議論の中でも一部言及されているところがありますので、そういったところを踏まえて検討を進めていく必要があると認識しています。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"建物の本体についてちょっと確認させてください。今までちょっと確認し損なっているのですが、今この区の総合庁舎は、国の法務局の品川出張所、それから東京都建設局の第二建設事務所が入っています。鵜の木のほうに移るということになっているのですけど。区の中に法務局、どうしても五反田に法務局が欲しいと私は思いますので、その辺はどうなっているのか、状況を説明できればお願いいたします。","respondent":"大友新庁舎建設担当課長","answer":"入居につきましては、現在どれだけの面積が必要かということで調整をしているところでございまして、基本的にはそこまで大きく現在の庁舎と変わるような面積変更はないかと考えています。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全体的な話になりますけれども、うまく進めていただいて、殊に今回は経費の件も出てきていますので、効率的な建物、そして全体的な開発に含めてやっていっていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"今の鈴木真澄委員の質問に関連するのですけれども、今回の変更、私も品川区新庁舎整備基本構想・基本計画策定委員として答申案については関わらせていただいたのですけれども、「第二庁舎は建物を残して」という表記が全て消えている中で、ここに書いてあるとおり、第二庁舎を残さないという考えで一体的にもう一回考え直すという大きな変更を示しているのかということが１つ。この３点伺います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"私から第二庁舎に対する考え方の部分について１つお答えいたしますと、今回記載がこれまでと異なっている部分につきましては、実際、第二庁舎を残すという観点から書かれていたものが。この２か月、３か月のずれが全てのスケジュールに影響してきているというところで、発注準備、当初４月１日から設計に入れるようにという形で、プロポーザルは年度内に行う予定で考えておりました。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"先ほど、１番目の質問の第二庁舎のことについては、第二庁舎のあるなしに関係ないというか、あるなしということではないというようなお話がありましたが、在り方についても改めて検討するという意味なのか、もう一回確認させてください。区有財産という表現は、改めて、あえてこういう表現を何でここでしてきたのかなと、先ほどのご説明なのでしょうけれども、わかりました。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"私から第二庁舎の件についてですけれども、今回、現庁舎跡地および周辺のまちづくりを一体的に行うというような方針を少しお出ししながら、この基本計画の策定というところに至っている部分がありますので。２点目の件ですけれども、ＣＭのほうのプロポーザルの進みですけれども、開始時期は基本設計の業者選定と同時期に開始を考えてあります。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"最後にします。ということは、設計業務、まず設計業者を選ぶのにはＣＭ、コンストラクション・マネジャーは、今回は関わらないと、関われないと。いわゆる世田谷区なんかでは、そこから入っていたと思うのですけれども、関われない。設計段階ではどういったことをＣＭに、設計段階ではどのような関わりがあるのか、また、そのあたりについて最後に教えてください。","respondent":"大友新庁舎建設担当課長","answer":"続いて２点目ですけれども、どのような業務で関わっていくかというところにつきましては、基本的にコスト管理であったり、スケジュール管理、またそういうところに伴いました技術的な視点に対して、区に対して参考意見であったり、アドバイスをいただく形になってあります。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"第二庁舎は確かに残すことありきでいろいろ計画が進んでいたのが、今回その文言が削除されて、今のあくつ委員からの質疑の中でも、壊す、壊さないとかではなくて、まちづくりを考えていく中でというようなところがあるから、それが削除されたという認識は、それはそれでいいのですけれども、そうすると、まだ当然第二庁舎は建って日が浅かったりする中で、まちづくりの将来的なものを考えるとなると。","respondent":"山下新庁舎整備課長","answer":"今回、第４回定例会で差し上げているご答弁の中では、現庁舎跡地および周辺のまちづくりを一体的に行うという方針を大きく打ち出しているところがありますので、今具体の例示がございましたけれども、そういったところも含めて。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も今回の答申からの変更点というところです。そして、それはどこでどんな検討がされたのか、この点についてまず伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、第４回定例会の中で、既に一体的なまちづくりということが打ち出されている中で、必ずしも現庁舎跡地だけではないというような議論が一定ございましたので、今回そういった内容をこの整備計画策定の段で反映されたものと認識しています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この庁舎跡地周辺の一体的なまちづくりというのは、今回、答申を受けた後に初めて出てきた考え方なのでしょうか。なぜ今の段階で突然それが出てきて、そして、品川区の担当部署だけでこういうことが決定されたということなのか、その確認をお願いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"これまで中長期的に総合的な検討をしていくということで記載をしていたわけですけれども、やはりそれを一歩進めていくという姿勢から、今回、より具体的な記載に改まったものと認識しています。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それで、残すか残さないかも含めて今後検討する方向なのか、その点の確認をお願いしたい。そしてまた、「区民負担軽減」というところは官民連携のＰＰＰという手法ですか、そういうことを検討するという意味合いも含めた形で、今回のこういう変更点になったのか、その点についても伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"実際に区民負担を軽減し、生み出した財源を福祉の向上や災害対策、次世代の投資に振り向けていくというようなことは、先般の区長答弁でも出ているところがございまして、今回、新庁舎整備の基本計画に当たりましては。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほど鈴木真澄委員からもありましたけれども、策定委員の方々に対しては、きちんと説明する場を作るとか、そういうことも必要なのではないかなと思うのですけれども、その点も伺いたいと思います。そして、公表してこれから学識経験者の意見も伺って、契約をする時期というのが何月ごろなのかというところのスケジュールについても伺いたいと思います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"１点目の策定委員の皆様への説明のところについて私のほうからお答えいたします。しかしながら、６月の契約に向けて今準備を進めているところです。ですので、できるだけ早くプロポーザルの実施要領の公開に向けて準備を進めてまいりたいと考えているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いつごろというのは、逆算して大体いつごろに実施要領をホームページでも公表して、いつごろに審査してというのは、おおよそのスケジュールというのは決まっているではないですか。それなのに募集要項がいつごろ出されるか、公表されるかということもお答えいただけないのか、その点を伺いたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"現在、おおよそのスケジュールは当然のことながら組んでいるところです。しかしながら、まだそのスケジュールの決定が取れているところではございません。今現在、６月中に契約をするとなりますと、２月中には実施要領の公開をしなくてはならないと考えているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。そうすると、第二庁舎も含めた形で現在の庁舎跡地の検討というところに移っていくと思うのですけれども、そこのところでは、森澤区長は、区民による検討会を設置するということも公約に掲げられていると思うのですけれども、そういう方向でも準備をされているのか、その点について伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今ご質問いただきました、この後の跡地のほうの委員会につきましては、区長のほうでそのようなお話をされてありますので、今後どのような形で進めていくかというのは、内部でも検討が必要だろうと考えています。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"今、第二庁舎の話も出ているのですけれども、第二庁舎は新庁舎ではないということで、もともとのところから言うと、諮問とか設置の関係で言ったら、必ずしも残っている今の本庁舎と第二庁舎について、品川区新庁舎整備基本構想・基本計画策定委員会が検討しなければいけないということはないのかなと思ったのですけれども、このあたりの事実関係はどういうふうに整理すればいいのでしょうか、お願いします。","respondent":"山下新庁舎整備課長","answer":"ご質問のあった設置要綱と実際に品川区新庁舎整備基本構想・基本計画策定委員会の審議すべき内容、諮問いただく内容の整理です。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"今、鈴木ひろ子委員からもお話があったので、ちょっと重複してしまうのですけれども、森澤区長が公約で区民のご意見を伺いながらということを政策で掲げておりましたので、今後そういう方向でいくのだと思うのですが、その場合というのは、例えばまた新たに要綱を作って、こういうことを諮問していくのですという形で進めていくという理解でよろしいでしょうか。お願いします。","respondent":"山下新庁舎整備課長","answer":"今、ご質問の次の段階の進め方ということについてですけれども、まだこれから検討という中で、同じような形で、いわゆる品川区新庁舎整備基本構想・基本計画策定委員会のような形態を用いるのであれば、やはり新たに要綱を制定して。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"本当に先のことになるので未定の部分が多いと思うのですけれども、大体方向性というか、どういうふうに跡地を検討していくのかということを、いつまでに検討しますというのは難しいと思うのですけれども、検討の方向性というか、こういう方針でいきますよというところは、大体いつごろに示される可能性がありそうでしょうか。お願いします。","respondent":"山下新庁舎整備課長","answer":"可能性という部分でのお答えですので、少し実態と離れる場合が出てくるかもしれないですけれども、今、令和４年度、これから令和５年度を迎えていく中にありまして、やはり予算の計上というような作業が実態として進んでいるところがございまして。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問・要望","question":"別紙３の５５ページの財源計画のところを質問させていただきたいのですけれども、先ほどからずっと出ています「庁舎跡地の一体的なまちづくりによる区民負担軽減の方策」ということで、「区民負担軽減の方策」というところの一応確認ですが、いわゆる新庁舎にかかる費用、４００億円とかと言われていますけれども、これの一部を一体的なまちづくりによって捻出していこうということで。","respondent":"山下新庁舎整備課長","answer":"実態としましては、４００億円以上となっている基本計画の上での建設に当たる費用負担を減らしていくというところからの発露かと思いますけれども、区全体のお財布から見ますと、使った、生み出されたお金をどこに充てていくかというところの発想につながる部分がございまして。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"よくわかりました。その上で、ちょっとこれは意見というか、何か答弁があればお願いしたいのですけれども、一応公会計的な見方をすると、例えば第二庁舎を一体的活用のためにまだ使えるけれども、１回壊してしまいましょうというような話になったとすると、使える建物を壊してしまうということは、多分減価償却というところでの損失みたいなものが出てくる。","respondent":"山下新庁舎整備課長","answer":"今の現総合庁舎につきましては、昭和４３年で、今年で築５５年を迎えるといったところから、新庁舎の必要性ということで区民の皆様にもこの間ご説明を申し上げてまいりました。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、さまざま議論がありましたけれども、周辺のまちづくり、庁舎一体のまちづくりということで、また新たに入れられたと思うのですけれども、その周辺というのは、先ほど中央公園や中小企業センター、その先の防災広場までみたいなお話もあったのですけれども、その周辺というのはどこまでのことを言うのかなというのと、あと、森澤区長が公約のところで、現庁舎跡地の活用については港区の竹芝でしたか。","respondent":"山下新庁舎整備課長","answer":"今、ご質問の２点目にございました竹芝地区のものが、東京都の事業の一部ではないかということですが、東京都のほうが実施されているものですので、もちろん都の事業であったのだろうと思いますけれども、私どもといたしまして、今、都の事業に何か参画するとか。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"周辺と言われると、本当にどこまでかなと。そうすると、周辺というのは、大井町側もですか、ということですよね。そして、それが今回の第二庁舎の活用の変更と関わって、さらに広がっていくものなのかなとちょっと不安だったり、疑問だったりがあるので、そこら辺はイメージできるようにしていただけたらなと思うのですが、今の段階では全くないということでしょうか、伺います。","respondent":"山下新庁舎整備課長","answer":"実際にまだ具体の検討が何かできているところはございませんで、これから基本計画として策定していく中で、この文言の修正をしているところについて、これから検討を深めていくところですので、現状お答えできるところとしてはこのようなところです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"確認","question":"すみません、もう一回確認させてください。資料１、別紙１の裏面の７番です。新庁舎の規模の整理ということで出ているのですが、もう一度この確認ですが、右側の「新庁舎建設想定規模」の「行政・防災・議会機能など」が約３万５,０００m2、「保健所／保健センター」が約２,０００m2ですが、この中に第二庁舎は入っているのですか。その確認をさせてください。","respondent":"大友新庁舎建設担当課長","answer":"新庁舎の建設想定規模の中に、第二庁舎は入っております。今、第二庁舎に入っていて、新庁舎に入ってくる課とか、組織とかの想定面積は入ってあります。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"確認","question":"建物自体、第二庁舎の建物は、当初は残す形ですよね。総体、約６万m2の中に第二庁舎の部分は入っているのか、それともこれは最初から計算していなかったのか、そこをちょっと確認したい。","respondent":"大友新庁舎建設担当課長","answer":"この新庁舎の６万m2の中に、第二庁舎の約１万２,０００m2は入っておりません。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。要するに壊しても影響、新庁舎を建てれば当初の計画どおりで、第二庁舎を壊しても面積的にこの６万m2で足りるということでよろしいですね。その確認だったのです。","respondent":"大友新庁舎建設担当課長","answer":"基本的に第二庁舎にある機能で新庁舎に持ってこられるものは持ってくるという想定をしていますが、第二庁舎にも一部機能が、どういうものが必要だろうということで、今回の基本計画の中でも一部検討していくというところで、今回締めくくっているところがありますので。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"たしか自分の記憶では、第二庁舎に例えば会議室を残すとかというお話があったと思うのですけれども、この辺が、新庁舎だけになって、これから検討して、第二庁舎をもし壊すというときには、新庁舎だけでは足りなくなってしまうのではないかというところが出てくるような気がするのですけれども、その辺はどう考えたらいいのですか。","respondent":"榎本新庁舎整備担当部長","answer":"特に、資料別紙３の１８ページの図を見ていただきたいのですけれども、これは「新庁舎および周辺施設の災害時の役割」ということで図が入っていまして、修正前までは第二庁舎が担う機能として、「別途検討」の四角の枠の中、「帰宅困難者一時滞在施設」。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"確認","question":"言っていることはわかりました。前も確認したのですけれども、防災の駐車場がないというお話もあったと思うのですが、確かにその辺は必要な部分があると思うのです。そこは大丈夫なのでしょうねという確認をしたい。","respondent":"大友新庁舎建設担当課長","answer":"こちらの検討機能というところがまだ課題として残っているところではありますけれども、こちらは約６万m2とさせていただいているところです。こちらのほうに盛り込むことで、問題なく検討は進められるかと思ってあります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"最後に。これから設計、プロポーザルを受けていく段階で、６万m2ということで設計してくるのだと思うのですよね。だけど、後になって全く別の設計になるのかどうかはわからないけれども、何か約６万m2で足りなくなってくるのは、設計業者にしても大変ではないのかなという気がするのですけれども、最後にもう一回そこの確認をさせてください。","respondent":"大友新庁舎建設担当課長","answer":"基本計画に沿った中身の必要な機能を盛り込んで設計をしていく形になりますので、基本的にはこの設計発注で問題ないかと考えています。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"結局、第二庁舎があれば、それだけ箱が残って、何かしら、それこそ会議室であったり、ほかの一部施設はそちらに残してということが可能だったのでしょうけれども、結果、それが検討の上になくなるとなったときに、全くそこが使えない状況で、では本庁舎の６万m2というパイの中で全てが収まるのですか、大丈夫ですよねという確認です。","respondent":"榎本新庁舎整備担当部長","answer":"それについては、これから設計をしながら都市計画を定める段階で、一番は容積率がどれぐらいかというのを調整しながら、全部入れ込む形できちんと機能できるのかどうか、そういうのを確認しながら進めていく予定です。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"世田谷区役所の視察を組んでいただいて、ありがとうございました。私は改めて世田谷区の庁舎の建て替えに当たってのご説明を、本当に丁寧にしていただいて、世田谷区は区民の住民自治と交流というところをしっかりと位置づけて、あらゆるところで区民参加というのをしっかり位置づけているというところが、本当にすばらしいと思って、伺ってきました。感想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと、やはり区民参加というところでは、今回大きな変更が、第二庁舎の問題であったりする中で、さらに区民にお知らせしていく必要があるし、今、鈴木ひろ子委員が言ったようにあらゆる場で区民参加、区民への説明というのを繰り返しやっている、それでもまだ足りないというのが世田谷区の姿勢だったので、品川区としてはやはりそこをぜひ参考に学んでいただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"２つ目の丸の、裏のページの行政の視点についてというところの(4)ですけれども、「品川区ＤＸ推進基本方針において定めている重点取組項目の目標については、可能なものについては前倒しで進めていくこと」ということですけれども、この基本方針の中で、重点取組項目というのが９項目あるのですけれども、この中に推進方針の工程表というのがありまして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"表現を。マイナンバーを除くものであればいいのですけれども、そういうことでできるのか、それとも、そこのところが入らない形の文言にできるのであれば、そういうふうにしていただければと思うのですけれども、それが入っているとなると削除していただきたいという意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"丸の「行政の視点について」のところについては、表記として「可能なものについては前倒しで進めていくこと」と、「可能なものについては」という条件がついているので、今のものも含めて、このままの表現でいいのではないですか。それはいろいろな捉え方ができるでしょうから。そんなことを言っていたら、全部削除しないと無理になってしまうので、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"意見","question":"途中まで手を挙げかけたら、あくつ委員から手が挙がったのですが、全く同感でございまして、あくまでも全てを前倒しだとか何だとかというのではなくて、「可能なもの」というような注意記載が入っていますので、そこで十分理解した上での配慮かと思われますので、この記載でよろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「可能なもの」というのは、何て言うのですかね、誰が可能だというふうに判断するか。可能か可能ではないかというのは、共産党が反対しているから、可能でないということになるものではないので、「可能なものについては」ということでは、私たちの思いは反映されないのではないかなと思うのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"だから、今まとまるように正副で調整してこのような形にしていただいたと思うのですけれども、配慮に気づかれたのかどうかわかりませんが、そういう形で配慮した表現になっていると思うのですけれども、先ほど申し上げたとおりですが、まだそれでもご主張されるということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは全ての委員が一致できるところで出していくというのが基本だと思うのですね。そういうところで、これではちょっと一致できないというところです。なので、「マイナンバーを除いて」とかということになるのであれば、私たちとしても賛成なのですが、「可能なもの」というところだと、マイナンバーが除かれるという表現には捉えられないと思いますので、それはご検討いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"渡部委員","kind":"質問","question":"それは全く違うと思います。ですから、マイナンバーに対して配慮するのであれば、「可能な限り」。繰り返しになりますが、何も私たちはマイナンバーがどうこうと言っている話では全くありません。正副で意見が出ている時点で、私たちがあえて何も言う話ではございません。正副がいらっしゃいますから。今、主張されているところの副委員長もいらっしゃいますので、そこはお任せいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"共産党としても今の委員長の提案どおりで、まとめはしないという方向でいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/994750?Template=document&Id=6144#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24514,"voices":90}},{"id":"r05-20230125-19","meetingId":"r05-cm01","date":"2023年1月25日","dateIso":"2023-01-25","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時４３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"防災に関すること","agenda":"防災に関すること","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"でも、これは本当に命に関わる大事なことですから、こういう情報に通じた地域でリーダーになるような方を意識的に育成していくというようなことを考えてもいいのかなというふうに思います。そうすると、防災訓練において、幅広い世代で訓練参加率が向上していくことにもつながるというふうに私は思ったのですけれども、そこら辺はいかがでしょうか。","respondent":"平原防災課長","answer":"同じように、防災教室というお話でございましたが、このしながわ防災学校の取組で、一般の方々も受け入れるコースがありますので、そういったところを活用しながら、広くこういった。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"大分分かりました。既にいろいろやられているということで、本当に必要なことだと思いますので、防災リーダーの育成、それから、防災学校あるいは防災教室、なかなか地味で根気の要る仕事になるとは思うのですけれども、そうやって伝えていかないと、やはり実際になったときに慌ててしまいますので、ぜひよろしくお願いいたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"防災に関することということで、要配慮者支援の取組について伺いたいと思います。質問なのですけれども、資料に「「避難行動要支援者の避難行動支援に関する取組指針」の改定を受け」とありますけれども、この改定の中身は何かと伺いたいと思います。先ほど、段階的な避難から直接避難の話がありましたけれども、改定の趣旨は何かを改めて伺いたいと思います。","respondent":"平原防災課長","answer":"いただきましたご質問のうち、国の取組指針の改正内容ですが、先ほど資料のご説明の中で触れさせていただきましたとおり、大本となるのは令和３年度に行われました国の災害対策基本法の改正でございまして。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"支援者を確保するために、どういう仕組みが必要かということなのですけれども、やはりまず幅広くこういう支援者を確保することが必要なのですよという共通理解を区民の皆さんと深めていくことが必要だと思いますので、例えば講演会だとか、各地域での説明会だとか、事業は違うけれども、認知症サポートで、よく荏原文化センターとかでやっていますけれども。","respondent":"平原防災課長","answer":"それからもう１点、個別避難計画のところですけれども、避難所であるとか在宅避難、こういったところの避難生活支援ですが、これは個別避難計画そのものだけではなくて、そもそも全体的な避難所における、例えば物資の支援でありますとか、様々な情報の支援。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"いざ災害が起きたときには何か協力したいという気持ちもあるのです。いずれにしても、高齢者および障害者の声を聞いて、個別避難計画を着実に進めていただきたいと思いますので、要望しておきたいと思います。準備が整うまでちょっと待ってくださいだけではなくて、もう一歩、準備自体をしっかり位置づけて、当事者が参加できるようにしていただきたいと思うのですけれども、その点、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"障害のある方の訓練参加の仕組みづくりと訓練参加の急務についてのお伺いなのですけれども、一応、仕組みづくりをしつつ訓練参加を促したいと考えています。そのスタートとして、この９月に始まる地区総合防災訓練を目途に進めているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思うのですけれども、改めて、個別避難計画をつくるに当たっても、防災訓練に障害がある方の参加を位置づけるにしても、視覚、聴覚、精神、知的、身体、内部障害、様々な障害がある方の団体の方々に、まずはヒアリングをして、状況や、不安に思うことや、実態や要望を受け取る、これは所管である障害者支援課と高齢者福祉課はもちろんのこと。","respondent":"平原防災課長","answer":"それ以外の、今、訓練というお話が出ましたけれども、訓練に関わらず、今後の防災全般の定めをしていく上では、様々な方々のご意見は聞いていくべきというふうに考えてありますので、今後、例えば、地域防災計画の大規模修正なども考えてありますが、そういった際には。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"避難の考え方で、在宅避難の定義といいますか、見極め、要は、在宅中に地震がありました。私はこの家にいていいのか、いけないのか、その見極めの判断は家主がやるのでしょうけれども、それはなかなか難しいことなのかと思って、それは行政のほうで何か見極めを指示していただけるのか、あくまでも自己判断なのか、まず、そこら辺を教えてください。","respondent":"平原防災課長","answer":"例えば、よく分からないから不安だというような場合には、自宅は無事かもしれないけれども不安だという方は避難所ということもありますので、そういったところで幅広に考えていただいて避難していただくものと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"今、応急危険度判定というお話がありましたけれども、確かに応急危険度判定士という方がいらっしゃって、どこの自治体か分からないですけれども、自治体によってはそういう人たちが、色を分けてペタペタと玄関に張って、この家は赤だから避難してくださいとか、多分そういうものもあるのかなと思っているのですけれども、品川区は応急危険度判定士を、何か災害があったときに入れて、在宅か。","respondent":"平原防災課長","answer":"応急危険度判定の流れですけれども、応急危険度判定は、大きな災害が起こったときに直ちに全ての建物を速やかにということが難しいので、優先順位をつけて、例えば避難所でありますとか、病院であるとか、大勢の方々が公的に集まるようなところを優先して行っていく形になります。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"公明党のあくつ議員の議事録を見たら、令和元年辺りに、防災士の方が３５０人ぐらい品川にいらっしゃって、公明党の先生方も取られていて、私も取りにいったのですけれども、防災区民組織の高齢化にもつながっていて、防災士の方がいらっしゃって、その方たちの活用というのですか、例えば、防災士の資格を取るのに助成している区もあるので、そういうところにもっと助成金を出していくとか、今。","respondent":"鈴木都市計画課長","answer":"それとともに、区内の建築士協会と設計士の方々の協力をいただきながら、そうした方々にも登録をいただいて、年１回、研修ですとか、連絡体制の構築ですとか、そうした、いざ発生した場合の機敏に動ける体制構築を毎年整えているというような状況です。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"ということは、多分、それから周知はすごくしていただいていると思うのですけれども、やっぱり周知は本当に丁寧にやっていかないと、助けてほしい人たちは、やっぱり分からなくて、また同じような繰り返しになってしまうのかなという部分で、より一層のそういう本当に必要な方の周知というのですか、こういう風水害が分かりづらいので、本当に今まで以上に頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"個別避難計画のところなのですけれども、先ほど、高齢者が４,７００件強、障害者が１４５件終わっているというお話ですが、これは、ほとんどが施設入所の方のものが終わっているということなのか、それとも、そうではないのかということと、それから、福祉避難所に優先的に行きたいというような方が意外と少ないというふうに聞いたのですけれども、意向調査をやっていく中で。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"その方の原案の作成ということで、ケアマネジャーがいらっしゃいますので、ケアマネジャーが持つ情報を基に、まずモデルで原案を作成してもらっているのが約４,７００件ということで、本人の同意や避難場所。障害者の方の個別避難計画についてです。障害者の方につきましても、入所の方は除いて在宅の障害者の方を対象としております。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"在宅ということで分かりました。それで、よく障害者の団体の方にお話を聞くと、やっぱり福祉避難所に行きたいという方が結構いらっしゃるというお話を聞いていたので、聞き取りの中でそういうご希望をされる方がどれくらいいらっしゃるかということが分かればと思ったので、もし分かれば教えてください。","respondent":"松山障害者支援課長","answer":"現在、１４５人の障害者の方に同意を得て進めております。そのうち９割の方が在宅避難ということで、福祉避難所というよりは、ご自分の家で安心して過ごせるというふうに思われている方が多いです。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"そのときに、では、まず区民避難所なのか、福祉避難所なのかという選択が出てくると思うのですけれども、その辺まできめ細かくはなかなかすぐはできないのかなと思うのですけれども、そこも大事かなと思うのですが、その辺はどのような感じなのですか。","respondent":"松山障害者支援課長","answer":"相談支援員が関わっているものですから、ケアプランを見直す、例えば、モニタリングの機会に、１回つくって終わりではなくて、気にかかるようなことは、必ずご本人、ご家族とご相談しながら進めているものですので、住宅に不安があるということでしたら、恐らく相談員が。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。では、今はもう、自宅ではなくて、福祉避難所もしくは区民避難所のほうに行きたいという方については、支援する方といいますか、家族だけではなくて、例えばもう一人ぐらい付添いがいるのだとか、そういうところまで、もう計画の中で、人数、マンパワーですか、人の名前というか、立場とか、それはもう決まっているということでよろしいですか。","respondent":"松山障害者支援課長","answer":"できるだけ家族以外の方も記載していただくように努めているところではありますが、現実的にはなかなか、空欄になってしまったり、お知り合いの方も少し遠方に住まわれていたり、あるいは、書かれていたとしても、その方がご高齢であったりというような、現実的に、では。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"防災に関することからまずお伺いいたします。避難の考え方、地震編、風水害編とありますけれども、私はここにもう１つ、在宅というところ、在宅も避難の考え方なのだということで、こういうご提示をいただくときに、どこかに避難をすることだけではなくて、在宅の避難もあるということをしっかり位置づけていくべきではないかと思います。それに関しての見解をお伺いいたします。そのことをまずお伺いします。","respondent":"平原防災課長","answer":"今回これはあくまでも全体的な避難計画ということで、代表例で計画させていただいたもので、大変申し訳ございません、この中にはペットという形で個別には入れてございませんけれども、これまでもお答えさせていただきましたとおり、私どもは全地域で進められるように。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。もう１つ、防災訓練についてお伺いいたします。防災訓練ですけれども、１２月に区内一斉防災訓練が行われております。そのための区内一斉防災訓練でありますから、そういうことは訓練の場で出てきて当然かと思うのですけれども、そういうところの取組に対して、区の助言といいますか、何かアドバイス的なところをいただきたいと思いますが、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"１つの区民避難所で複数の町会が連携して訓練を実施しているところのリーダーシップ性についてのお話なのですけれども、実は、この後、報告事項で、区内一斉防災訓練の実施結果の話をする中で、先ほど、おくの委員からもありましたとおり。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問","question":"すみません、それではまた後ほど報告をいただいて、お聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"私の探し方が悪いのかもしれないのですけれども、今その個別避難計画で探したときに出てくるのが、避難行動要支援者の支援体制づくりの手引きだったりするので、それではなくて、個別避難計画があって、今はこういう状況ですと、現状これほど計画作成に向けて進んでいますが、来年度はこれぐらいやっていきますといったようなお知らせがあると、当事者の方たちも安心するのかなと思うので。","respondent":"平原防災課長","answer":"ただ、作成に当たりましては、こちらは先ほどの内閣府の取組指針で、優先順位の高い人から順にというようなところが示されているところでございまして、何分数が多いものですから一気にというのは難しい状況ですので、まずは優先順位の高い方から進めているといったところです。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"ペット避難について、全体で進めてからといったご答弁だったと思うのですけれども、例えば、当該地域のことだけとかではなく、そもそもペット避難ができる、ペット防災とはとか、そういったページがあるだけでも飼い主の方たちは安心できると思うので、そういった説明とかだけでもいいので、ぜひ関心があるよということを示せるような周知はしていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"要配慮者利用施設における訓練の実施ですけれども、こちらにつきましても、１７１施設全てで行われているということで私ども把握しています。法人から、それぞれ施設から報告が上がっているところです。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"課題として挙げられている防災区民組織の高齢化に関連してなのですが、各区民組織で、消火隊を結成いただいているかと思うのですが、消火隊のポンプの口径というのですか、それから、ノズル、管槍、筒先、これの口径を改めて教えていただきたいのと、これは区から支給していただいているものかどうかも改めて教えてください。","respondent":"五十嵐災害対策担当課長","answer":"ただ、一部の外国製の商品で、Ｃ級の後継的なものを開発しているというような話は聞いていますけれども、それは正式に採用されているものではございませんので、まだ決まっていないというのが実情です。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問","question":"今ご答弁いただいた中で、私が質問した口径と今ご答弁いただいた後継、その意味がちょっと違うのかなと思うのです。私は、大きさというのですか、口の径です。そのことなのですが。それと、今ご答弁いただいた後継というのはどういう意味か、改めて、不勉強なので教えてください。","respondent":"五十嵐災害対策担当課長","answer":"すみません。Ｃ級可搬ポンプの口径につきましては、個別に回答させていただきたいと思います。後継というのは、失礼しました、私が勘違いしておりました。Ｄ級可搬ポンプの後継が、今、なくなっているので、Ｃ級可搬ポンプは現在も継続して生産されてあります。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"これは消防署のほうで署員の方が主に使われている筒先かと思うのですけれども、例えば、横浜のある消防団などでは、既にこのガンタイプノズルを配備をして、なかなか力が入らない方でも放水を容易にできるように、そういうものを配備をして、地域の防災力向上に資していただいているということを伺う中で、防災区民組織の方への配備の中で、このガンタイプノズルの配備というのも、１つ。","respondent":"五十嵐災害対策担当課長","answer":"区民消火隊の高齢化に伴う筒先、ガンタイプノズルへの変換ではどうかというようなお尋ねなのですけれども、ガンタイプノズルについてなのですが、いわゆる今現在使っている２１型といわれる筒先と比べて、放水反動力は若干軽減されますけれども。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、ぜひ今言っていただいたとおり、消防団の方へのガンタイプノズルの配備の支援、これをぜひ品川区としてもやっていただきたいということと、改めてそういうことも踏まえて、防災区民組織の方へのガンタイプノズルの支給の検討についても併せてやっていただきたいと思います。改めてご答弁いただきたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"改めてガンタイプノズルの区としての支援を検討していただきたいというようなお話のお答えなのですけれども、もちろん消防団のほうで、この資機材が必要だということであれば、毎年消防団に補助金を出していますので、その中でご購入いただくというふうに考えています。","id":"exchange-023"},{"speaker":"須貝委員","kind":"確認","question":"今までお話を聞いていたのですが、品川区で世論調査を２年に一度やっています。これ、避難の考え方と出ているのですが、やはり最初に出てくるのは、運営主体が防災区民組織、区、施設管理者、一時集合場所、区民避難所５２か所、補完避難所、広域避難場所、これが出されたら、皆さんこっちに目がいってしまうではないですか。帰宅困難者の皆さんもいたら、もうどうしようもないのです。教えてください。","respondent":"平原防災課長","answer":"さらに災害時に家を確認して、それで大丈夫であれば在宅避難、そういったところについては、位置づけといたしましても、私どもも最上位に置いているところですので、今回の資料ではちょっと小さくなって分かりづらかったかもしれませんけれども。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"本来なら、避難の考え方、上のほうにありますけれども、地震編とあるならば、ここの右側に大きく明記して、区民の皆さんに協力してもらうということがやはり第一だと思うのですが、どうなのですか。これではちょっと分かりづらい。実際、区で対応できないところはしようがないではないですか。在宅の方は、例えば、避難するときに移動できるように、車椅子は全員お持ちなのですか。","respondent":"平原防災課長","answer":"こちらの資料中の在宅避難のところについては、先ほど来、ご説明のとおり、ちょっと分かりづらかったところなのですけれども、区のホームページでありますとか、「しながわ防災ハンドブック」とか、そういったところにつきましては、自助。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"町会でも車椅子とかは用意しています。ベッドも簡易式なものを、運べるものを用意していますが、現実論、やはり車椅子は、町会でも、あるのがほんの四、五台なのです。その中でもちろん常時使われている方もいらっしゃるから、実質在庫としては２台か３台というような状況です。その辺について、もし何かありましたら教えてください。","respondent":"平原防災課長","answer":"避難支援を行う際の資機材ですけれども、なかなか資機材全てを用意することが難しい現状の中で、どういったものを工夫すればといったところ、例えば、今までの防災訓練などでもありましたけれども、物干し竿を利用した毛布担架。","id":"exchange-026"},{"speaker":"つる委員","kind":"意見","question":"せっかくご答弁いただいたので。であればこそ、積極的に、先ほどご答弁いただいたような形で、防災区民組織の配備も、段階を踏んでという形になろうかと思いますけれども、ぜひ積極的な検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"それについても、開設しなかったのは、どういう基準でそうなったのかという部分を伺いたいのと、例えば風水害が発生するときに、強い台風が来るとか、そういうときに、朝の７時の時点で警報が出ていたときに、学校がお休みになるかどうかを区のホームページでお知らせするとなっているのですけれども、区のホームページからは、また今度、品川区内の天気図、天気予報みたいなところに飛んで。","respondent":"平原防災課長","answer":"こちらの自主避難施設ですけれども、基本は台風接近時ということを考えてございまして、さらにその中でも令和元年の台風１９号、あのときのような強い台風が、勢力を落とさずに東京地方に上陸または接近というようなことを前提としていますので、昨日。","id":"exchange-028"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それと、防災訓練のほうで、区職員向けの訓練の課題のところに、発災後１週間までの初動体制の確立ということで書かれているのですが、これをパッと見ると、この１週間の体制ができていないという感じに聞こえてしまうのですが、最初の説明のところでも中身の説明がなかったので、ちょっとよく分からなかったのですけれども、これがどういうことかということと、本当にこの１週間の間の体制ができていない。","respondent":"菅野高齢者福祉課長、平原防災課長、松山障害者支援課長","answer":"作成をするに当たっての苦労というか、課題などについてなのですけれども、やはり在宅避難の考え方や避難する時期、避難するときの支援者や避難方法。区の初動対応体制のところについてですけれども、まず、先ほどございました訓練での課題の１週間といったところですけれども、計画自体は。ただ、地域の方にお願いをするというよりも、ご本人との、やはり一定程度の関係性がないと。","id":"exchange-029"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"防災訓練については、分かりました。これから初期の１週間のところで、やはりそこのところがいろいろな１日たつごとに恐らく状況は変わってくると思いますので、これが実際の支援していく、区としての取組をやっていく上ではとても重要になってくると、地域の区民の支援をしていくためにも重要になってくるというふうに思いますので、ぜひそういったところでしっかり進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-02","title":"令和４年度品川区地域防災計画の修正","agenda":"令和４年度品川区地域防災計画の修正","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"地域防災計画の修正の説明を伺いました。そこについて区の見解を伺いたいと思います。","respondent":"平原防災課長","answer":"広域避難場所での避難生活というお話ですけれども、まず、広域避難場所については、東京都が東京都の条例に基づき指定しているものですけれども、考え方といたしましては、ちょうど１００年前の関東大震災の地震火災で多くの方がお亡くなりになったということを契機に。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、広域避難場所での１か月後、２か月後、３か月後、そういう中でいろいろ考えていくことは当然ですけれども、仮設住宅を広域避難場所に設置することもあらかじめ検討したり、やっぱり特に都市部は、それでも足りなくなってきますので、自宅での仮設住宅の設置、建設を計画上に位置づけたり、こうした工夫も品川区地域防災計画の修正の中で検討を進めていくべきだと思うのですけれども。","respondent":"平原防災課長","answer":"生活場所といいましょうか、そういったところのお話かと思いますけれども、まず、今言ったように、昨年５月に発表されました東京都の被害想定を受けまして、こちらの今回ご報告しています令和４年度の地域防災計画の修正とは別に。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"仮設住宅のことですけれども、繰り返しになりますが、やっぱり都市部では、自宅に仮設住宅を建てて、そこで生活してもらうということは、スペースの確保にもつながるし、また、ご近所の関係も続くので、震災関連死であったり、孤立だったり、支援が行き届かなかったり、様々な問題を解決する１つの考え方かというふうに思って述べさせていただきました。検討していただけたらと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"２０２０年に私が一般質問をしたときには、東京都などの改正の中にそういったことがなかったからということだったのですけれども、品川区の地域防災計画なので、そういった具体的な航空機が街中で墜落したときの、そういった想定を防災計画に加えるべきではないかと思うのですけれども、そこのところについて伺いたいと思います。","respondent":"平原防災課長","answer":"地域防災計画上の航空機事故のお話ですけれども、私ども、地域防災計画に大規模事故対策というような形で位置づけさせていただいているところでございまして、様々な事故が考えられると思いますが、それが災害の事象に至るようなものについては、実際の動きについては、震災時。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"大規模事故のところに記載があることは分かっているのですけれども、全く具体的ではなくて、さらっと書かれているぐらいなのですよね。だから、もうちょっと品川区地域防災計画、地域の防災計画なので、具体的にそういう危険が今、残念ながらある状況なので、具体的に修正をしていただきたいと、加筆してほしいと思います。強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"（２）番から（４）番のところで、高潮浸水と多摩川氾濫、土砂災害というところなのですが、この文章を読むだけでは、何がどう変わったのかということがとても分かりづらいというところで、これはやはり地図などがないと、よく分からないという状況になっておりますので、これを分かりやすいように地図などをぜひつけていただきたい、改善を求めたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"今回の見直しのところ、すみません、資料上分かりづらいということでございましたけれども、今後いろいろ広めていく上では、ハザードマップに既にいわゆるハザードエリアという形で塗ってあるところ、そこを対象としていくものですので、ハザードマップと併せまして。","id":"exchange-036"}]},{"id":"topic-03","title":"防災地図の改定及び全戸配布","agenda":"防災地図の改定及び全戸配布","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"そういう意味では、説明会も１つの手法だと思いますし、防災地図そのものに工夫をすることも必要だし、また、全部の人に配る必要はないわけですから、障害別に理解ができる情報提供の仕方を行っていくということが必要だと思うのですけれども、防災地図の全戸配布について、取りわけ障害がある方への情報提供について、どのように考えていらっしゃるのか伺いたいと思います。","respondent":"平原防災課長","answer":"こちらを作成した後の周知というようなことですけれども、まず、私ども、こういったものをつくらせていただいたときには、地域の防災の中核となります防災区民組織本部長に地域別にご説明させていただきたいと考えていますので、１３地域に関しては。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"防災地図、前回もポストにぽんと入っていましたけれども、それだけでは、ある意味、もったいないなと思って、それに関心を示してくれる人に集まっていただいて、話も聞いてくれて、質疑もできて、一緒に来た方が多少交流もあれば、ご近所の方であれば、関心が共通だとすれば、そこで１つの輪もできるし、そういう意味では、説明会は、私は力になると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"スケジュールのことについて確認をします。作成をして全戸配布をしていただくに当たっては、これはシルバー人材センターの方にお願いをするものでしょうか。それともう１点が、広報しながわ等で周知をしていただけるということなのですけれども、配布の前に、こういう配布をしますよということの周知がされるのか、そのことを教えてください。","respondent":"平原防災課長","answer":"配布の前段階での説明ですが、配布前に地域の防災区民組織の本部長にはご説明してまいりたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"町会長の方たちには行うけれども、やらないといったことだったと思うのですが、ぜひやっていただきたいと、ＹｏｕＴｕｂｅでの公開というのは確認したのですけれども、そこにたどり着けない方もいらっしゃるので、せっかくいいものをつくっているので、地域の方々が深く防災について意識ができるように、ぜひ説明会は実施していただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"説明会についてですけれども、まずは、各地区の本部長から、防災の中核になっていただく方なので、ご理解いただくというところから進めさせていただきまして、防災学校であるとか、動画といったところを１つの考え方、さらには、私ども、年に１回。","id":"exchange-040"}]},{"id":"topic-04","title":"令和４年度区内一斉防災訓練等の実施結果","agenda":"令和４年度区内一斉防災訓練等の実施結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ご報告ありがとうあります。やはり訓練を実りあるものにするためには、できるだけその地域の方がたくさん参加してくれなければならないわけで、実りある訓練にしていくために、どのようなことが課題だと考えていらっしゃるのか、その点、１つ伺いたいと思います。それからもう１つは、私、先ほども言いましたように、第一日野小学校なのですけれども、防災関連動画の視聴をしました。","respondent":"五十嵐災害対策担当課長","answer":"実は東京都と品川区の合同総合防災訓練の動画でもそこの部分を扱っておりましたので、そちらを使っていただけばよかったかなと、今、反省しています。引き続き、ＳＮＳやデジタル動画等を通じて、訓練参加と訓練啓発を進めていきたいと考えておりますので、よろしくお願いします。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"別紙１の区内一斉防災訓練参加避難所の参加者欄のところで気になったのが、児童・生徒数のところが、２校だけしか数がなくて、保護者の数は０、あと、２番目の区内一斉防災訓練以外の避難所訓練では、１校が児童・生徒がたくさん参加をしていて、保護者数が０ということで、特にこの２番の避難所訓練を行った学校、児童・生徒数が高いところに関しては。","respondent":"五十嵐災害対策担当課長","answer":"加えて、隔年で児童・生徒が加わる年と、加わらない年という形で訓練を進めております。ですので、昨年は加わらなかったので、今年の１２月には、学校と連携して多くの児童・生徒が参加する訓練を実施していく予定です。","id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"私は、この一覧を見て、町会・自治会参加者数の中に、児童・生徒とか保護者も含まれているのかと思ったのですけれども、そうではないということですか。そこの部分も確認させていただければと思います。","respondent":"五十嵐災害対策担当課長","answer":"町会・自治会参加者数のところは、純粋に町会・自治会の方、今回は人数制限の中でやっていますので、基本的には役員系の役付きの方が多かったかなと思われます。","id":"exchange-043"},{"speaker":"田中委員","kind":"確認","question":"１年ごとに子どもたちが参加したり、しなかったりということがあるというのは確認できました。保護者の数が０なのは、毎年なのですか。","respondent":"五十嵐災害対策担当課長","answer":"保護者の欄が０なのは、全部町会・自治会員としてカウントしています。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"継続は力なりと思いますので、ぜひ引き続き区も支援していただきたいと思います。質問なのですけれども、この訓練内容について、町会の役員の方々が話し合ったものが基本になっているかと思うのですけれども、この内容について、品川区が確認をしたり、助言をしたり、援助をしたり、一斉防災訓練の訓練内容について、品川区はどういう関わりを持っているのか、その点を確認させていただきたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"１点目、避難所訓練で区の助言等についてのご質問なのですけれども、区としては、基本的には、避難所連絡会議の意向を尊重するわけなのですけれども、今回に関しては、４５年ぶりに開催した東京都と品川区の合同総合防災訓練。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"一方で、その中身自体も、いろいろ双方向でアイデアを出し合いながら充実したものにしていく、品川区では、それぞれの訓練内容や感想や状況を把握しているわけですから、今回は４０年ぶりの区と都の一斉訓練を参考にということですけれども、何か１つテーマを示してあげるということも、やっている側からすると、やりやすいのかなと思いますので、それぞれの訓練状況をよく把握していただいて。","respondent":"五十嵐災害対策担当課長","answer":"今後の区民避難所の訓練のテーマについてお話があったのですけれども、それについても今までコロナ対応の避難所運営ということでやってきたのですけれども、また今度は、新たに別な切り口で、別なテーマを入れてきてもいいのかなと、では。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問・要望","question":"そこで、今いろいろな委員からお話がありましたけれども、いろいろな訓練のパターンがあって、そういうものは町場の協議会でやるわけではないですか、そうすると、なかなか行政は入り込めないですけれども、ここら辺で１回ぐっと入り込んで、こういう訓練の仕方があるのですよ、実はこういう好事例がありますよとかと、ある程度、方向性を示してあげたほうが。","respondent":"五十嵐災害対策担当課長","answer":"そうでなくて、訓練の進め方が悪かったと、先ほどお話を出しましたけれども、区民避難所のアンケート総数の半数が、訓練の進め方が悪かったという学校が２校ございまして、一体そこでは何があったのかということを、ヒアリングとか、実情を把握した上で。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"訓練のほうですけれども、２校ありましたというお話の中で、おろすではないですか、その後に、その２校に対して、行政のほうで、こういう訓練の指示を出したときに、どう変わったのかとか、その後を追いかけて、いろいろご報告をいただけるとありがたいと思っています。それと、情報システム訓練なのですけれども、皆さんが一緒にやれるようになるとやっぱりすばらしいシステムになると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"田中委員","kind":"意見","question":"大体はこれでいいのかなと思ったのですけれども、（２）の障害者等への情報発信についてのところで、この「等」の中に、区外の来訪者の方たちも含まれているとは思うのですけれども、そういったことも書いてあったほうが、よりいいかなと、特に海外の方たちへの発災時の情報発信はとても重要だという議論が多分あったと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"文章の中で、６行目のところに、ごみの発生抑制を推進するためのという文言は書いてあるのですけれども、この項目の中で、やっぱりリサイクルばかりになってしまって、リデュースの考え方も結構議論されていたと思いますし、区民の方たちも、この発生抑制についての意識啓発ということに対して、意識もすごく高まっているところですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/556800?Template=document&Id=6630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":55095,"voices":145}},{"id":"r05-20230126-10","meetingId":"r05-cm01","date":"2023年1月26日","dateIso":"2023-01-26","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":4398,"voices":21}},{"id":"r05-20230220-10","meetingId":"r05-cm02","date":"2023年2月20日","dateIso":"2023-02-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"議事日程(1)(2)(3)および追加議事日程","agenda":"議事日程(1)(2)(3)および追加議事日程","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"意見なのですけれども、請願・陳情の付託についてですが、総務委員会に付託予定の請願で、「消費税インボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願が出されていると思うのです。ですので、総務委員会の委員長もいらっしゃるのですけれども、議長からも委員長へ伝えていただきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委員長へというご発言がありましたので、そのまま言われたままというのは、議会運営委員会の場ではまずいと思うので、前回の委員会でも、私ども委員長判断で商業・ものづくり課長をお呼びしませんでした。今回の段階は、まだ正式に詰めておりませんけれども、前回と同じ内容で進めさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"質問通告の前から、会派として、幹事長としてくにば議員と連絡を取りながら、質問の状況や通告期限の日程の確認、また、質問提出日の期限の確認等を行ってきたところです。その際に、また質問提出の期限についても確認をし、翌週の月曜日、質問提出期限の朝にも、今日が提出期限ですということでご連絡をさせていただきました。その際に、質問の取り下げについても、確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"くにば議員は取り下げが２回目ということで、体調不良というのは本当にすごく分かります。先般あった、立候補予定者説明会にも、くにば議員はいらしていたという話も伺っております。議長が電話をしても出ない。１点だけ、事務局長にお伺いしたいのですけれども、その辺に関しては私は可能だと思っているのですが、どのようにお考えになっているのかということをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大倉委員","kind":"確認","question":"謝罪についてですが、説明も含めて、本人も連絡が取れて、今後、医者に行って、診断書等を持って、しっかりと説明をしますということで、確認はしているところであります。その際に、本人からもしっかりと皆様を含めて、お話ができるようにしていかなければいけないと考えていますので、そのように対応していければなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問も変わっている中で、やはり、載せておいてもいいのではないかなと私は思います。これは、皆様の見解で、皆様がどうするのかにもよりますけれども、別にその辺は難しくはないですよねということで、答えにくいと思うけれども、話として載せるべきだと自民党としては考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"くにば議員が、もしも話せる機会があれば、議会に対して聞かせてほしいかなと思います。今、区議会のホームページで定例会本会議の代表質問・一般質問者、発言事項として、質問の発言事項が載っています。くにば議員も通告はされているということで出ているので、そこの部分は、これから削除か何かをされるのかなというところだけ確認させていただければと思います。","respondent":"工藤区議会事務局長","answer":"そうしますと、取り下げ行為が正式に受理されたということになりますので、そういった事実に対しての対応をホームページで修正をしてまいるです。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"議長への通告は上がったけれども、質問自体が上がってこなかったことについて、議長と区との調整などはされたのですかというところを確認したいです。","respondent":"本多議長","answer":"前回も謝罪しましたが、今回も２度目で本当に申し訳ありません。ご迷惑をかけたということで、謝罪はさせていただきました。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"意見ですけれども、くにば議員が質問を取り下げられるのは２度目ということです。前回も言ったのですけれども、会派として、再発防止に取り組んでほしいということも述べました。先ほどの大倉幹事長からのお話で、当日も含めて確認をされながら、今後はさらに工夫して、丁寧に対応したいとおっしゃっておりましたので、そのように対応していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そこまで元気かどうかは分からないけれども、翌日から質問にかかる段階で急に具合が悪くなってしまったのか分からないけれども、そのような事実関係を見ていくと、前回のときはずっと体調が悪くて、前回は須貝幹事長も連絡を取ったというけれども、今回、そのような動きを見ている限り、どうしても書けなかったのだということがあるのかもしれないけれども、質問ということに対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"ごめんなさい。当日の早朝もご連絡を取られたということで、確認を取ったというお話でしたけれども、そこまでやった上で、今回の話になっているのですが、その上でどのような具体策をとられるのか。当時は須貝幹事長でしたけれども、再発防止のために、どのようなことをされるのですかというお話を聞きました。もし会派として責任を感じておられるのであれば、そこのところのお考えをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"再々発防止に向けてですが、この間も会派としては丁寧にやってきたつもりであります。これからは、前もって事前の質問の内容も含めて、丁寧に確認をしながらやっていかなければいけないと考えていますので、事前の確認をさらに丁寧にしながら、連絡を取りながらやっていくつもりであります。それ以外の方法についても、様々検討しながら取り組んでいきたいなと思っているところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどのご説明の経緯の中で、丁寧にやられているなということは感じたのですけれども、当日確認して、そこから連絡が取れなくなってしまうという今回の件。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"財政調整のところなのですけれども、都の法的責任が発生した部分で、資料などはありますかという確認と、例えば、法的にどのような部分か。どの法律の何条にかかってしまったなどの具体的な部分を、もし分かればお知らせいただきたい。","respondent":"本多議長","answer":"毎回、都区協議をして、大体１月末ぐらいには協議が成立するのですが、今年は成立しないので、都の条例上、前年度と同様の金額で、各２３区は予算の歳入は５５.１％を想定して予算計上していると、品川区から伺いました。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":18243,"voices":74}},{"id":"r05-20230224-3","meetingId":"r05-c-budget","date":"2023年2月24日","dateIso":"2023-02-24","committee":"予算特別委員会","time":"午前１１時４５分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1994,"voices":18}},{"id":"r05-20230227-6","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"区民委員会","time":"午前１０時００分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","topics":[{"id":"topic-01","title":"第１１号議案、品川区印鑑条例の一部を改正する条例","agenda":"第１１号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"単純な確認ですけれども、マイナンバーカードの電子証明書の機能をマイナポータル経由でスマートフォンに入れられるようにするということだと思いますけれども、ということはマイナンバーカードの取得が前提になっているという理解でよろしいでしょうかというのが第１点です。一応、確認という意味でお伺いしておきます。この点、区としてどうお考えなのかということを伺いたいと思います。これが３点目です。","respondent":"吉野戸籍住民課長","answer":"今回のスマートフォンですけれども、マイナンバーカードの取得が前提条件になります。それから、２つ目の安全性ですけれども、今回のスマートフォンの部分というところでよろしいでしょうか。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"サービスの低下はないと、作らないというお考えだと思います。特に健康保険証ということですので、物すごい不安の声はいろんな方から伺います。その点、心強いご答弁でしたので、ぜひその姿勢で進めていただきたいと思います。ですから、教育とか管理というか、データの管理、その点、念には念を入れてということは心がけとしてやっていただきたいと思います。要望として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"松本委員","kind":"意見","question":"今回は、移動端末設備と書かれていると思うのですけれども、電子通信事業法の定義を見ると、スマートフォンだけでなくてタブレットなんかも当てはまりそうな気がするんですけど、その点はいかがでしょう。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、そういった移動端末というところの全般になります。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"では今はアンドロイドというお話なので、ｉＰｈｏｎｅについてはまだ使えないという認識でよろしいでしょうか。","respondent":"吉野戸籍住民課長","answer":"去年、デジタル大臣からの答弁にもありましたとおり、最初にアンドロイドをやりまして、実際にｉＰｈｏｎｅに関しましては、遅れながら開発するということで、今アップルと国とでやりとりをやっている最中です。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問・要望","question":"今はアンドロイドからで、次、恐らくｉＰｈｏｎｅで、ｉＰｈｏｎｅがなると多分その後アップルの製品も可能になってくるのかと思いますし、ほかのタブレットも使えるようなってくると思いますので、可能な端末が広がった場合には周知をしていただければと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":4721,"voices":29}},{"id":"r05-20230227-7","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"第１７号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第１７号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問","question":"ご寄附いただいた方の意向に沿ってという形で、社会福祉基金と新たに高齢者福祉基金ということで基金が形成されたということで、これは何人の方からとか、特定の方からなのか、複数人の方からなのかを伺いたいのと、この新旧対照表のところにもありますけれども、お名前をつけられてそういう福祉基金にするという場合も以前にはあったと思うのですけれども。","respondent":"寺嶋福祉計画課長","answer":"残りの１００万円につきましては、同じく既にお亡くなりになりました故人の方の遺言によるものです。２名とも、故人の方につきましては匿名希望、非公開ということでお受けしておりますので、お名前の記載はございません。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"意見","question":"補正予算のところに８,０００万円ぐらいの社会福祉基金積立金があるのですけれども、それと、今のこの７,８００万円余との関係。補正予算で、指定寄附金のところで社会福祉指定寄附金とあるのですけれども、それが８,１００万円ぐらいあるのですけれども、それはこの７,８００万円余との関係はどうなりますか。","respondent":"寺嶋福祉計画課長","answer":"補正予算のほうの記載は３００万円を合わせた形での合計金額となっておりますので、８１００万余という形になってあります。基金としては別々に積み立てるということです。","id":"exchange-002"},{"speaker":"いながき委員","kind":"確認","question":"確認と質問なのですが、この２個目の設置する基金というのは新しく設置する基金で、高齢者福祉に特化したものという理解でいいのかというのが１つと、今拝見していて、確かにお名前のついている基金があるのですが、これはほかの社会福祉基金と何か違いというか、使途が決まっているとか、何かほかのとの違いはあるのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"要するに基金はそのまま残しておいて、そこから生じる利息等を使って、それを充てていくということが主流だった時期があったのですけれども、そうするとおのずと基金の設置期間が長くなりますので。","id":"exchange-003"},{"speaker":"いながき委員","kind":"質問","question":"そうすると、例えばお名前付きの基金で頂戴した金額を使い切ってしまったらば、その基金はなくなるという理解でいいでしょうか。","respondent":"寺嶋福祉計画課長","answer":"おっしゃるとおりです。使う場合には歳入、歳出、補正予算等々を組ませていただきまして、基金の金額を全て事業に充当することになった場合には、基金はその時点で終了するということなります。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"質問","question":"素朴な疑問として伺います。資料の２ページ目の新旧対照表のちょうど中段ぐらいに、お名前の後に「高齢者用社会福祉基金」ということで、高齢者に特化したような名称がついている基金があります。しかも名前はつけなくて結構ですと、匿名でお願いしますという、企業と１人の方からはたまたまそういう申出があったので、こういう汎用的というか受皿を特化して作ったという理解でよろしいのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"副委員長のご認識のとおりです。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"確認","question":"分かりました。ということで確認ですけれども、今までもこのお名前の後に「高齢者用社会福祉基金」というもので、これは運用益としては高齢者に特化した形で使っていた、もしくは使う目的であるということで、これは変わらずということでよろしいのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"運用益が生じれば、基本的にはそういう考え方ですけれども、今の金利から考えますと、これだけの基金に対しても運用益で何か事業に充てられるかどうかと言われると大変難しいので、恐らく基金を直接崩して活用するときには基本的にはそういう形になろうかと。","id":"exchange-006"},{"speaker":"石田委員","kind":"確認","question":"東京都のパートナーシップ宣誓制度の活用ということでの入居要件の改正ということで、歓迎したいと思っていますけれども、この高齢者住宅というのは結構単身世帯が入るところが多いかと思うのですけれども、家族、また２人以上で入れる高齢者住宅というのは何戸ぐらいあるのか伺いたいのと、証明書があればこうした区立の住宅を利用できるのかなと思っていたのですけれども。","respondent":"川原高齢者地域支援課長","answer":"２つ目の質問です。条例改正がいずれも必要かということにつきましては、品川区に関しましては条例に入居の要件を設けてありますので、今回、パートナーシップ条例の認定の要件を追加することで、条例改正に伴って４月１日より施行するという流れです。","id":"exchange-007"},{"speaker":"石田委員","kind":"確認","question":"そのうち全部埋まっているというか、空いているところはないということですか。その確認と、条例改正を品川区の場合はということなのでしょうか。この東京都パートナーシップ宣誓制度を活用しているほかの２３区の自治体もあると思うのですけれども、ほかの自治体は、品川区と同様の条例改正をしているわけではないところもあるということなのでしょうか。確認をお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"質問の２つ目のパートナーシップの条例に関しましては、すみません、人権関係の所管になりまして、他区の自治体の条例改正のところまでは、こちらで手持ちの資料としてはございませんが、既にパートナーシップ制度を導入している都内の自治体は１９区市あると伺ってあります。","id":"exchange-008"},{"speaker":"石田委員","kind":"意見","question":"やはり証明書があれば入れるという気軽なものというか、あれば入居できる対象になるということではなく、条例改正をしなければ結局入れないということになってくると、証明書を取っただけでは駄目なのだなという感じがあったもので、それがもしほかの自治体もそうではなく、条例改正をしていないような区があった場合はなぜなのだろうなと疑問に思ったので、私のほうで調べてみたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"いながき委員","kind":"意見","question":"これは意見ですが、やはり私の知る限り、２３区中では１０区が既にパートナーシップ制度を入れています。なので心配なく入れるようにするためには、やはりパートナーシップ制度を品川区でも導入していただければ、多分よりスムーズに皆が安心して入れるのではないかと思うので、ぜひとも品川区もほかの区に続いて、パートナーシップ制度を導入していただければという意見というか思いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"非常に歓迎をしたい制度だと私どもも考えておりますけれども、すごく素朴な質問なのですが、東京都のパートナーシップ宣誓制度を見ると、パートナーシップ関係を解消した場合は届出が必要と書いてあるのですが、パートナーシップ関係が解消された場合は、退去、いわゆる配偶者と同等にみなすということなので、これはそういうことになるのかという、その辺りの考え方を教えてください。","respondent":"川原高齢者地域支援課長","answer":"この辺りのパートナーシップ宣誓制度そのものにつきましては、所管の課長から聞いている部分での範囲のお答えになってしまいますが、やはり解消をした場合に、ご自身が都にその解消を申し出るような形になってありますので、それに附属する区の制度につきましては。","id":"exchange-011"}]},{"id":"topic-02","title":"令和５年陳情第２号、重度障害者を差別しないグループホーム入居選考を求める陳情","agenda":"令和５年陳情第２号、重度障害者を差別しないグループホーム入居選考を求める陳情","exchanges":[{"speaker":"石田委員","kind":"質問","question":"グループホームに重度障害者も入れるようにということで、今重度障害者というのは、区が把握しているところでは何人いらっしゃるのか。そして、この重度の方が入れるグループホームは区内に何人分あるのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"グループホームにつきましては、区立、民間等もあります。それぞれのグループホームによって開設年月日、あるいはグループホームの支援者の体制、あるいは施設の構造等々異なりますので、一概に重度障害者の方が入れるグループホームは何か所ですというのはお答えはしかねます。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問","question":"そうすると、重度障害者というとどこまでかということもあるので、重度の知的障害者、要は身体のところでの重度の方というふうに分けると、数は分かるのでしょうか。そこを伺いたいのと、何人分になるのかというとなかなか言えないということですけれども、重度障害者も対象としているグループホームは、区内には何か所あるのでしょうか。","respondent":"松山障害者支援課長","answer":"重度障害者という言葉を使っているグループホームにつきましては、今後整備していく出石つばさの家等になります。","id":"exchange-013"},{"speaker":"石田委員","kind":"確認","question":"この陳情のところには、金子山グループホームが重度の知的障害者を得意としているということで、重度障害者を対象とすると説明されてきていると思うのですけれども、金子山グループホームは少なくとも重度障害者を対象としているということでいいのですねという確認と、重度障害者を受入れ対象としているグループホームは区内にどれぐらいあるのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"グループホームに関しましても、先ほど説明しましたように障害の程度だけではなくて、緊急性やご家族の状況、また医療情報、あとは生活上のご本人のこだわり、もちろんご本人やご家族の希望を踏まえて総合的に判断しているものです。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問","question":"なので、誰が対象ですよということではなく、障害者グループホームというのは軽度から重度まで対象になっているというふうに考えているということでいいのでしょうか。","respondent":"松山障害者支援課長","answer":"平成３０年の４月に制度改正が行われまして、重度化・高齢化に対応できるグループホームの新たな類型として、日中サービス支援型グループホームが創設されたということで、この間本当にグループホームの過渡期といいますか、品川区だけではなく。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問","question":"分かりました。そして今後、先ほど出石のグループホームは重度障害者も受け入れられるようにとおっしゃったということで言うと、今後区長が公約に掲げているこの障害者グループホームを整備していくにあたっては、重度障害者も受け入れられるグループホームを積極的に増設していきたいという考えであるのかどうか伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"品川区の総合実施計画にもありますように、重症心身障害者が通所できる施設の拡充、今後は安全・安心に通所できる場を整備するという方向も検討してまいりますので、そこは私どもも課題とは捉えております。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"なので、どういう体制のグループホームを造るのかというところでは、もうその時点で重度障害者も対応できるというところが決まってきてしまうと思います。なので、ぜひ今後、区長も１００人分の障害者グループホームの整備を着実に進めていくとおっしゃっていますので、そこは重度障害者もしっかり受け入れられるグループホームのさらなる増設ということで求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"いながき委員","kind":"意見","question":"それとも逆にそうではない、こだわりがあまりない方とか、適応のしやすい方とか、私たちだとそれが中度とか軽度かなと思うのですけれども、そういった方たちのほうの推薦があったのかどうかをお尋ねします。","respondent":"松山障害者支援課長","answer":"例えば病状につきましても、てんかん発作がある方については、てんかん発作の種類、症状、あるいはどのような刺激でどのような環境のときに発作が誘発されるかといったような状況、あるいは服薬の状況、発作時の対応等、安全確保も含めて確認をしておりまして。","id":"exchange-018"},{"speaker":"いながき委員","kind":"質問・要望","question":"選定会議では推薦の可否を決めるとあったのですけれども、一応全員が推薦はされる。そのときに、こういった方はこういった症状がありますよという資料がつけられるという意味でよろしいでしょうかという確認が１つと、それをご覧になって、区立のそういった運営にいるほうの方たちが、その中からお選びになるということでしょうか。","respondent":"松山障害者支援課長","answer":"２点ご質問をいただきました。入居候補者選定会議での情報が、グループホームの運営者に伝わるのかという点です。実際に入居候補者選定会議の中で、外部委員として当該グループホームの運営管理者の方に同席いただいております。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"確認","question":"１点だけ確認をします。ご希望される方が必ず面談をされると先ほどおっしゃっていましたけれども、そういう過程の中でどういう手順を踏んで、運営事業者側が選んでいくのですよということを、希望する方たちにまずご理解をいただく必要があるのではないかと思うのですけれども、その辺りについては何かご説明されていらっしゃるのでしょうか。","respondent":"松山障害者支援課長","answer":"令和２年度につきましては２名の空き、令和３年度につきましては１名の空き、令和４年度については、明日報告します西大井つばさの家の定員増を含めて４名の予定で、今その４名の情報は、相談支援事業所を通じて流しております。","id":"exchange-020"},{"speaker":"いながき委員","kind":"意見","question":"先ほどの民間への支援のところで、私の言い方が悪くてごめんなさい、民間に重度の方をお願いするにあたって、品川区のほうからぜひともより困難なものを抱えている方を優先的に入れてほしいというような添え書きというか、そういった意味での支援というのがあればいいと思っているのですが、今あるのかなというところと、ないのであればお願いしたいです。","respondent":"松山障害者支援課長","answer":"いわゆる有資格者の方ですね。有資格者を常勤配置した場合に対象となるということで、有資格者を配置するということはより支援が必要な方に対応するスキルをアップするですので、配置した場合について助成をしているというものがあります。","id":"exchange-021"},{"speaker":"いながき委員","kind":"質問・要望","question":"ありがとうございました。そういった意味でもその支援はすごく嬉しいなと思います。こういった形はもちろんなのですけれども、選定されるときにお願いをしたいというような、よりプッシュするみたいなものがあればいいと思ったので、もし今現在ないようでしたら、そこの検討もしていただきたいと思っています。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論を出すで、不採択です。先ほど質問をしましたけれども、いわゆるこの方の陳情の趣旨と理由の中に、現在の状況とは異なることでのご認識があったということは、先ほどの中で確認いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"質問の中でも、重度の方も受け入れると明確にしているグループホームはないのだなということが分かりました。やはり受け入れる体制の問題もあると思いますので、出石つばさの家グループホームは今後重度の方も受け入れられるようにと答弁いただいていますけれども、そこは確実にそうしていただきたいですし、毎年当事者団体からは、重度の方も入れるグループホームをということは要望が出されております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由としましては、今あくつ副委員長や高橋しんじ委員からのお話がありましたけれども、過程とかそういったところでの丁寧な説明をしていただいて、そこのところをご理解いただけるような流れをつくっていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"議案審査を改めて行います。(4)第２０号議案、品川区立健康センター条例の一部を改正する条例","agenda":"議案審査を改めて行います。(4)第２０号議案、品川区立健康センター条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"荏原保健センターも暫定でここに移転するというところでは、それは条例の改正にはならないのかということと、条例の荏原健康センターは、建物としてはそもそも以前の説明だと、旧第一日野小学校跡地での運営を基本に今後検討を進めていくということだったので、荏原健康センターはこの旧日野第一小学校の跡地の一部分で運営をしていくということなので、恒久的な建物になっていくのか。","respondent":"若生健康課長","answer":"それから２点目、今後仮移転を旧第一日野小学校跡地のほうにするというところで、昨年９月の厚生委員会でご説明させていただきましたところなのですが、荏原健康センターの建物は、保健センター側の建物、それからもう一方で保育園・児童センターの建物と。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問・要望","question":"それで旧第一日野小学校跡地は、私たちもそうですけれども、様々な福祉施設として使ってほしいという要望も住民の方からいただいて、出していたところですので、そういった要望は何か出たのか、どのような説明会だったのかというのを伺いたいと思います。","respondent":"若生健康課長","answer":"それから住民説明会は、仮設の工事が始まる前の令和４年１０月６日に実施しています。そのときの参加人数はちょっと手持ちで持ち合わせてございませんが、２０人近くはいらっしゃったという記憶です。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"やはり近隣住民の皆さんと住民参加で、跡地としてどう活用していくかという検討をしていただきたいと思います。それで、荏原健康センターは、先ほどの質問で健康センターのみの建物になっていくのか、その辺の検討があるならば教えてください。","respondent":"若生健康課長","answer":"荏原健康センターの仮移転後の建物につきましては、荏原健康センター単体としての利用の目的としての建物となっています。","id":"exchange-028"},{"speaker":"いながき委員","kind":"確認","question":"確認なのですが、この（２）の施設等の一部削除のところなのですけれども、この施設は暫定的に旧第一日野小学校跡地に移転をするから暫定的に削除するというもので、荏原健康センターは、改修後は今あるところにもう一回改修した施設が建つという理解でいいですか。","respondent":"若生健康課長","answer":"そちらの（１）の所在地の変更の件と、（２）の施設等の一部削除の部分は、全く別といいますか、移転するから削除するというわけではなく、この（１）のほうは、単純に移転するので所在地を変更しますという体制になっていまして、（２）の施設等の一部削除につきましては。","id":"exchange-029"},{"speaker":"いながき委員","kind":"確認","question":"ありがとうございました。そうすると、もともとの健康・体力検査ルームというのはカウンセリング、今やっているようなものをやっていたという理解でいいでしょうかというのと、保育室は授乳室が代替でという理解が合っているかどうかの確認だけさせてください。","respondent":"若生健康課長","answer":"当初の事業の名称としても、カウンセリング事業という名称でやっておりましたので、そういった健康関係のいわゆる血圧を測ったりですとか、それはそれでアドバイス、カウンセリング等々をするというような事業でございまして、それを１室。","id":"exchange-030"},{"speaker":"石田委員","kind":"質問","question":"今の質問に関連してですけれども、そうすると、ではそのときに本来は条例改正をするべきだったということですよね。区民の方からも、これがなくなってしまうという声が別に届いていたわけではないので、だからといって問題はないというふうには言えないのではないかと思うのですが、そこはどうでしょうか。","respondent":"若生健康課長","answer":"改正のタイミングとしましては、やはりその部屋の利用が終了した段階で条例改正等すべきだったとは私も思うのですが、２０年以上前のことで可能な限り保存資料等も調べたところだったのですが、当時なぜ改正が行われなかったのかという理由が分からず。","id":"exchange-031"},{"speaker":"石田委員","kind":"質問・要望","question":"この条例自体は賛成をするものですけれども、やはり旧第一日野小学校跡地が、先ほどもご説明あったように、近隣の方からは福祉施設にということで、健康センターだけでなく、様々な福祉施設に活用ができる場所ですので、再開発のための用地などに使うのではなくて、住民参加で住民合意の下で、引き続き丁寧に聞き取りながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-04","title":"第２８号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２８号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"今回これだけ、均等割では令和４年度から４,８００円の値上げです。この１０年間を見ても、均等割の値上げ幅というのは多くて３,３００円だったものが、今回４,８００円ということで、これまでにない値上げになる。そして１人当たりの平均保険料も、前年度との差が１万１,８９５円、約１万２,０００円ですけれども、これだけの値上がりになった理由を伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"ただ、医療費については４７１億円ですけれども、それ以外に被保険者の数も、実を言いますと令和４年度は２６７万４,０００人ということで推定をさせていただきましたけれども、令和５年度については２５９万３,０００人ということで。","id":"exchange-033"},{"speaker":"石田委員","kind":"質問・要望","question":"今、値上げのご説明をいただいたのですけれども、やはりコロナに加えて物価高騰等々でどうやりくりしようかと本当に大変な中ですので、こうした大幅な値上がりを抑えてもらいたいというのが多くの加入者の皆さんの願いだと思うのですけれども、そうしたところで区として軽減するための特別な対策は打たれないのでしょうか。","respondent":"池田国保医療年金課長","answer":"ですので、保険料の減額を各区ごとでやるのではなく、２３区統一の形でできれば政策的なところで、今後どのような形になるか分かりませんけれども、検討は進めているところです。","id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"というか、国もそのようにご説明されましたので、ぜひ軽減策を取っていただきたいです。ですので、できることですのでぜひやっていただきたいということを改めてお願いしたいです。それと、東京都もこの軽減に向けて激変緩和の対策は取れると思うのですけれども、東京都の令和５年度の保険料に対しての激変緩和としてはどれぐらい出されているのでしょうかということを伺いたいです。","respondent":"池田国保医療年金課長","answer":"ですので減額を区独自でやるということについては、一律でやることは難しいと判断いたします。","id":"exchange-035"},{"speaker":"石田委員","kind":"質問・要望","question":"なので私も国に確かめたのです。これは本当に何かできないように見えるけれども、どうなのでしょうかと。それから、東京都からの激変緩和は約１５億円。これは市や島しょ部も合わせての約１５億円ですので、本当に品川区一自治体として見ると本当に微々たるものですので、ぜひ東京都にも軽減に向けてさらなる激変緩和を求めていただきたいと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"もう一つは、あまり数は多くないですが、拘禁のために品川区にいらっしゃらなかった方に対する保険料の減免ということもやっておりますので、全て一律に本人からご申請いただいて減免はしておりまして、それはやらせていただきますので、保険料についてはそういった形で。","id":"exchange-036"},{"speaker":"石田委員","kind":"質問・要望","question":"そもそもの保険料が高いのだということなのですね。もう年収の１２％ほどになるのです。協会けんぽの２倍です。そういうところでの知事会も、軽減のために１兆円の公費投入をということで国に求めているところですので、区としても国や都に求めているというところですが、それではなかなか進まないので、区独自にやっていただきたい。その立場で、引き続き求めていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田委員","kind":"意見","question":"反対です。品川区は令和５年の新年度予算は過去最高の約１,９８８億円、特別区税は約２９億円の増ですし、地方消費税交付金も１６億円の増、そして法人住民税や固定資産税が主な特別区交付金、これも３１億円増。こうした３つだけを見ても１年間で約７６億円の増収をしているわけです。区民生活は追い詰められていますので、今こそ税金投入で引き下げこそすべきだと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"いながき委員","kind":"意見","question":"反対します。少し意見を述べさせてください。出産育児一時金が増えたのはすごくよかったと思います。けれども、やはり全体的には保険料が上昇してしまって、皆保険の仕組みから、それこそ払えないということでこぼれ落ちてしまう人々の増加につながると思います。皆保険制度の必要性、その維持をうたいながら、実際には未保険者を生み出してしまうと思います。なので、この議案には反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":31380,"voices":155}},{"id":"r05-20230227-8","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"建設委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、第２５号議案、品川区立公園条例の一部を改正する条例","agenda":"会議の運営上、予定表の順番を入れ替えまして、第２５号議案、品川区立公園条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、こどもサッカー場が初めてできるということは、子どもたちがスポーツをする機会をつくることにもつながりますし、よいことだと思います。子どもたちから料金を取る、なぜそうしたのか伺いたいと思います。この料金設定、先ほど、軟式こども野球場と同様の設定にしたということですけれども、その野球場の設定は、どういった根拠で決められているのか伺いたいと思います。","respondent":"高梨公園課長","answer":"子どもは１チーム当たり１枠５００円という料金設定ですので、過度な負担のない料金設定であると、区としては、このように考えているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"料金設定のところは、ほかの施設と横並びということは分かったのですけれども、その料金設定をした理由、根拠を伺いたいと思います。そういったものを負わせるのはなぜなのか伺いたいと思います。子どもたちがスポーツに誰でも親しむことができるようにしていくためには、やはり無料にすることが一番だというふうに思うのですが、その点も伺いたいと思います。","respondent":"高梨公園課長","answer":"２点目の子どもからも使用料を取るのはなぜかといったところですが、これは一部繰り返しですが、無料の施設にしてしまうと、利用の予約が殺到したりとか、また、キャンセル等も、無用な予約が入り過ぎてしまうというような運用上の問題もありますので、負担にならない限り。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"公園課として、そういった子どもたちがスポーツをすることについて、子どもたちへの効果、あるいは影響というところで考えているところがあれば伺いたいと思います。やはりこうした子どもたちに、親の経済力とかも関係なく、しっかりスポーツをする機会を与えていくということが私は必要だというふうに思いますけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"一方で、限られた範囲の中で一定のレベルの高いスポーツを行う際に、非常に多くの子どもたちの中で、例えば試合をやるというようなこともなかなか難しいところで、一定の範囲、面積を確保しながら、専用のスポーツ場も一方で必要になってくる。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"多目的広場とかスポーツをする機会はあるということですが、やはり収入のない子どもたちからも使用料を取っていくということは、やめるべきだというふうに思います。そこは子どもにまで使用料を取るということはないように、無料にすべきだということを求めて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点目が、２番、運用時間のところの※の部分ですけれども、「利用当日までに予約が入らなかった枠について一般開放する」というふうにあるのですけれども、この一般開放とは、具体的にどういった利用方法というか、イメージなのかを確認させてください。","respondent":"高梨公園課長","answer":"工事中にサッカー場の利用を開始するということで、工事のエリアとどうしても接する部分が出てきますので、そちらについては、子どもを中心とした利用者の方々の安全に十分に配慮しながら、不安全になることがないような形で整備してまいりたい、このように思っているところです。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"一般開放していただけるということで、こちらは無料で、例えば、サッカーボールを蹴ったりですとか、いろいろな利用ができるということで、ぜひ進めていただきたいというふうに思っておりますので、よろしくお願いいたします。ＡＥＤの場所はパークセンターに備えているということで、こちらは要望になるのですけれども、ＡＥＤは１０分間で取りに行けるということがとても大切になってくるかと思います。","respondent":"高梨公園課長","answer":"今のご意見を踏まえまして、団体等の利用の予約を行うスポーツ推進課とも情報の共有を図りまして、今、委員からご提案がありましたＡＥＤについて、情報の共有はしっかりと進めてまいりたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"サッカー場は、区内に結構いろいろあるのかなという思いも正直ある部分で、今回ここにバスケとか、ほかの種目を検討される中で、こどもサッカー場をつくられるという経緯をまず改めてお聞かせいただきたいのと、あと、今回、ナイターの設備がないということでお話があったと思うのですが、この施設はフットサルもできると、大人のミニサッカーもできるということで、大人がやるとなると。","respondent":"高梨公園課長","answer":"今後についても、様々スポーツのニーズも変わってくるというふうに思いますので、スポーツの所管部署とも連携しながら、公園内で実現できるスポーツ施設については、引き続き研究を進めてまいりたいというふうに考えてあります。２点目のナイター設備についてです。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいと思います。人工芝生でコートがされているということなので、常にいい状態で皆さんに利用していただける環境が必要かなと思うのですが、参考までに、このメンテナンスはどれぐらいの頻度でされるものなのでしょうか。","respondent":"高梨公園課長","answer":"メーカーからは１０年未満ぐらいの耐用年数でといったところですが、その時々の最新の動向をしっかりと設計の中に取り込んで、できるだけ長く、しっかりとした製品で、区民の皆様に使っていただけるように努めてまいりたいと思います。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"私は素人なのでよく分かりませんが、サッカーのシューズでめくれてしまったりとか、常にいい状態で借りていただきたいと思うので、そうしたことから考えると、一定の料金をいただきながら、その整備をしていくということも必要かなというふうにも考えるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"意見","question":"こどもサッカー場ができることは賛成です。今回の条例改正は、小中学生からも使用料を取るという有料化条例です。やはり子どもがスポーツをすることで、体や心の発達、友達とか関係づくりにも役立ちますので、より多くの子どもたちがスポーツをする環境を保障するために無料にすべきだと考えますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回のPark-PFIの件についてですけれども、まず、資料のところから伺いたいと思うのですが、Park-PFIを導入したときに、特定公園施設というものを設定するのですか。この特定公園施設というのはどういったものなのか、ご説明いただきたいと思います。１４事業者が参加したということで、こういった事業はどういったところが参加をするのか伺いたいと思います。","respondent":"高梨公園課長","answer":"各者とも、それぞれ実施したい事業の内容は異なりますけれども、いずれかの公園につきましては、しっかりと事業が成り立つと考えるので積極的に参加したいというような方向でお話を受けているところです。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"１２月には事業者を認定するということで、確かに導入がもう決まっているようなスケジュールになっているのですけれども、もう決まっているのかということと、先ほど、事業の可否についても検討しているというような説明もあったかと思うのですが、そのところはどうなのかということと、可否の結果を出すのはいつ頃になるのか、そこも伺いたいと思います。","respondent":"高梨公園課長","answer":"２点目の導入が決まっているのかといったところですが、先ほど説明の中でも申し上げましたとおり、現段階で導入の公園であったり手法、内容について決まっているところではございませんが、３点目の事業の可否の検討といったところの質問にも関わりますが、区といたしましては。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"年度の終わりか始めのところで決定するということですけれども、実際にこの導入をしていくときに、どういった形になるのかということが、単純にカフェを設置するということもあると思うのですが、そういった形になるのか、どういったことを考えているのかというところを伺いたいと思います。","respondent":"高梨公園課長","answer":"事業の詳しい内容につきましては、現在、検討中ですので、この場でこの手法ですというようなことは申し述べることができませんが、いずれにしろ、その公園の利用者のニーズに合った魅力を高められる。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"具体的にはまだ検討中ということですけれども、実際にこうやっていくと、仮にカフェだとすると、今、検討の中でも２００m2ぐらいの建築物ができるようなところで検討しているということですので、そうすると、今、実際に公園の中の樹木があるところが伐採されてしまうということになると、公園としての役割が損なわれてしまうというふうに思うのですけれども、その辺りはどうなのか伺いたいと思います。","respondent":"高梨公園課長","answer":"２点目につきましては、公園全体を任せてしまうと区のコントロールが及ばなくなるのではですが、あくまでも公園管理者は区ですので、全て公園に関するものを民間事業者に任せるものではないというふうに考えてありますので、公園管理者として公園の主体的な運営の部分については。","id":"exchange-014"},{"speaker":"のだて委員","kind":"提案","question":"あくまでも管理者は区ということですが、最終的には区の責任ということになると思うのです。不満の声が上がりました。そうした中で建物を造って公園を狭めていくということは大きな影響が出るというふうに思いますけれども、その点も伺いたいと思います。そういった現状の使用を制限するという提案が来たときには、区としては断るのか、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"２点目の樹木等の伐採と、公園が狭くなってしまうといったところですが、これも具体的に実施する公園であったり、実質の事業内容が出てからということにはなりますけれども、樹木等の影響が少なくなる、もしくは、さらに増えていくといったところを見定めて。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"利用状況を把握して進めていくということですけれども、西大井広場公園も、この７つの公園の中に入っておりますけれども、様々に使っています。そうすると、ある意味、二重投資という形になってしまうと思うのですけれども、こうしたところで区民公園もPFI導入に向けて選定されるということがあるのか伺いたいと思います。","respondent":"高梨公園課長","answer":"今回、候補公園としては入れさせていただいてありますが、仮に事業実施の段となった際には、今ご指摘のような二重の投資だというふうに区民の方々から思われないような形で整備する必要があると、このように考えているところです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"実際に住民の意見の反映というところで、事業者を認定して事業内容を進めていく中で、住民や議会の意見を聞く仕組みというのはあるのか伺いたいと思います。そして、この陳情の中でも、説明会をやってほしいということで言われておりますので、やはり様々こういった分からないことがたくさんありますので、ぜひ住民の方にも説明をしてほしいと、説明会を開いてほしいと思うのですけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"その手法につきましては、現在のところ、説明会でやりますといったように決めているところではございませんで、その手法については、これから検討してまいりますが、今考えている形ですけれども、公園整備の際に、利用者であったり、周辺にお住まいの方々。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者などの意見も聞くということですけれども、やはり事業内容が決まってからということなのかなと思うのです。やはり事業内容に区民の意見を反映していくということが私は必要だというふうに思いますので、そういった形でやらなければ区民が求めるものにはならないのではないかなというふうに思います。説明会もぜひやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"１点、お伺いいたします。区にPark-PFI制度に関するお問合せがあった際は、現在どのように説明しているのか教えてください。","respondent":"高梨公園課長","answer":"区民の方々から、本制度についてお問合せがあった際には、この制度自体は日本全国で行われている制度ですので、まずはそういった事業そのものの概要のご説明、それと、現在行っている、区のPark-PFI導入に向けた検討の状況といった形で、電話、もしくは対面等をはじめ。","id":"exchange-019"},{"speaker":"西村副委員長","kind":"質問・要望","question":"すみません、２点、お伺いさせてください。実際、ほかの自治体でも、公園の中の飲食店、カフェなどが増えてきているなという実感が確かにありまして、現在取り組まれているほかの自治体の好事例があればイメージがしやすくなりますので、お聞かせいただきたいなと考えています。関連で、宮下公園がPark-PFIではない手法を取り入れていると伺っておりまして、改めてどのような手法かお聞かせください。","respondent":"高梨公園課長","answer":"ほかにも、Park-PFIは１つの事例でございまして、民間事業者が公園の中で事業をする手法には様々ございまして、公園施設の設置管理制度、従来ある制度もありますので、そういった手法を利用してやっているものと推察しています。","id":"exchange-020"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、結論としては不採択でお願いいたします。そもそも品川区、区民の方もしくは利用者の方としては、どのような手法で公園がつくられるかということに、そこまでこだわりがないのではないかなと思っていますので、それよりは、様々な手法を活用して検討していただいて、よりすばらしい公園を模索していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたしたいと思います。どのような区の事業でも、説明するということは大事なことだというように思いますが、今陳情に関するこの件については、先ほどご説明いただきましたが、現在、調査中の段階であるということと、また、具体的な事業計画は、まだ計画されていないという、こうした段階で説明するのは非常に難しいのかなと考えるところです。よって、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。前提として、共産党は、公園という公共空間を特定の民間企業のもうけのために使用し、事業内容に区民の意見が反映される仕組みがない、また、責任を区がとらされるPark-PFIを導入することは反対です。しかし、このPark-PFIについて、検討プロセスや特徴を区民に説明することは、導入の有無の前に最低限のことですので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"本日結論を出すでお願いします。先ほどの質疑の中で様々確認させていただきました。この制度については、まだ現在進行形ということであり、公園の利用者、また住民の方々への可否のアンケートをとっている段階で、また、公園についてもまだ絞り込みをしている段階、また、事業内容についても検討中ということでしたので、まだ決定したわけではないということで、この陳情に関しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"本日結論を出すで、先ほどの議論、説明を踏まえまして、不採択でお願いいたします。他の自治体の導入事例の情報収集からスタートしていただくことを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、先ほど少しご説明がありましたが、先行していた駅前通り地区、パルム駅前地区についても、再開発組合がまだ解散をしていないということで、ちょっと確認になってしまいますが、パルム駅前地区は、この９月で解散をしていくと、清算をしていくということと、あと、武蔵小山駅前通り地区については、３月までというものを延伸するということですけれども、これはいつまで延伸されるのか。","respondent":"多並都市開発課長","answer":"もう１つの武蔵小山駅前通り地区、こちらにつきましては、令和６年３月まで延ばす予定で、今、手続きをしていますけれども、それ以降につきましては、この工事進捗が、今、見込みで進むということで行っていますので、その実施次第。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"総会のところは、質問のところでの報告があったわけですけれども、発言をしたのは地権者ではないかというご説明でしたけれども、質問をしようとして、できなかったというところが１つ問題というか、しっかり意見を拾い上げていくというところでは課題があったのかなというふうに思いますので、そこはしっかり意見を反映させるような形で運営をしていくことが必要ではないかというふうに思いますが。","respondent":"多並都市開発課長","answer":"もう１つの駅前通り地区につきましては、先ほどご説明というか、今、期限を延ばすことを調整していますけれども、それにつきましては、風対策のために施設を一部改修するのですけれども、その改修工事が終わるまでの期間を延伸しているということです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところに、ゼネコン、デベロッパーなどの利益を上げていくために税金を投入して、住民は追い出していくという、こうした再開発の仕組みが、まず私は問題だと思うのですけれども、こうした再開発はやめるべきだというふうに思いますが、いかがでしょうか。そこのところも伺いたいと思います。","respondent":"多並都市開発課長","answer":"１点目ですけれども、再開発事業につきましては、このまちの課題を解決するために、地域の方が地域主体でまちづくりを検討されて、現在、進めてきているところです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"この陳情の中でもいろいろ、移転の補償ですとか、支援のことについても詳しく説明してほしいということで書かれておりますけれども、そこのところをご説明いただきたいのと、直下型地震がもし起こった場合に、防災対策ということで書かれていたと思うのですが、これは恐らく事業として、直下型地震が起こったときにどう対処していくのかということだと思うのですけれども、その点もいかがでしょうか。","respondent":"多並都市開発課長","answer":"そういう事業を進めながら、今の耐震性の課題を皆さんで解決して共同建物にしていこうという事業でありますので、そういう目的のために皆さんで話し合っていただいて、事業計画としてまとめていっていただいているのが現在の状況というふうに理解しています。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"その下で、開発企業は保留床の売却で莫大な利益を得るという状況ですので、やはりこうした住民を追い出し、あるいは、結局、持ち出しが出てしまうという下で、企業には莫大な利益をもたらすという、こうした再開発は、やはりやめるべきではないかと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"ただ、事業計画を立てる際に、そこは権利者の皆さんであったり、また、事務局の方であったり、知恵を出しながら、それをより広くとれるようにできないかということは、皆さんでいろいろ知恵を出しながら検討されているところでもありますので。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"陳情第９号のところをまとめて伺いたいと思うのですけれども、区分所有者が再開発を進めていくに当たっての権利、マンション１棟に１人という換算です。この第二地区の組合の公告をするには発起人が必要だということで、発起人というのはどういうふうに決められていくのか、住民への周知などはどういう形でやられているのかというところも伺います。","respondent":"多並都市開発課長","answer":"アンケートですけれども、これにつきましては、先ほど冒頭のご説明でもさせていただきましたが、これまで住民説明会、準備組合だけではなくて、区のほうも都市計画の手続という形で住民説明会を開かせていただき、また、公告縦覧で意見公募をさせていただいて。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々伺いましたけれども、やはりいろいろ複雑な中身で、住民の方が理解するのは大変な状況ですし、実際問題、住み続けられるのが一番だというふうに思いますけれども、そうした今のまま住み続けるという選択ができないというのがこの再開発で、やはりそうした再開発はやめるべきだと思いますし、住民の不安にはしっかり応えて説明をしていくべきだと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"確認","question":"１点、お伺いいたします。高齢者から、分かりにくい法律などに関してのお問合せがあった際には、区として現在どのような対応をしているのか確認させてください。","respondent":"多並都市開発課長","answer":"直接区のほうにお問合せがあった際は、法律もありますけれども、あとは、もう少し丁寧に、どうしてそういうご質問なのかとよくお聞きして、丁寧に対応させていただいているところです。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いいたします。今の質疑を伺っていて、いろいろと書かれている内容もありますけれども、事実として認識がちょっと違うというようなところが見受けられましたので、本陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択を主張します。本陳情の大筋は、住民を追い出す再開発の廃止を求めるものであり賛同できます。その下で住民には様々な不安があるわけですから、それに応えられない部分もあると思いますけれども、可能な限り丁寧な説明は必要だと考えますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。先ほどもご説明がありましたように、例えば、この武蔵小山駅前地区の再開発組合が開催されていない理由や、防災対策などの説明を受け、また、先ほど他の会派からもありましたように、事実と認識が違うのかなというふうに感じました。そのため、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、結論としては、不採択でお願いいたします。こちらについても、これまで建設委員会で何度もお話をさせていただきましたが、基本的に再開発というのは、品川区が主体というよりは、住民主体であるべきだと思っていますし、この再開発についてもそのように行われているかと考えていますので不採択で。不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いします。この陳情の内容、ほかの号でも、以前に出されていた内容も踏まえて、また、今の質疑も踏まえて、これまでも情報提供をしてくださっていたということもありますので、これからも情報提供をしていただくというところが大事なのかなと思うところで、本陳情については、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"のだて委員","kind":"確認","question":"本日結論を出すということで、採択を主張します。自らが関わる再開発について、分からないことは説明すべきですし、アンケート調査は準備組合の賛否の確認が曖昧なもとで、今こそやるべきですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。今までも我が会派といたしましても、この再開発事業に関しましては、地元の住民と、そして有識者の方々が集まって意見を出し合ってつくられた事業だと認識しておりますので、この件に関しては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"今回のパートナーシップ制度、都の事業を活用するということですけれども、これによって、同性のカップルは今回入ったと思うのですけれども、その同性カップルの子どもですとか、あと、夫婦別姓の方は、このパートナーシップ制度を受けられるのかどうか、そこを伺いたいと思います。","respondent":"竹田住宅課長","answer":"別姓ということですが、その証明は戸籍、住民票等には影響を及ぼさないものですので、姓は別々でも差し障りないものと考えています。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"幅広く適用できる制度なのだなというところで分かったのですけれども、申請のところです。そして、中身に入っていきたいのですが、今回、３つの住宅について改正されるわけですけれども、区営住宅と区民住宅の承継要件には、パートナーシップ関係にある人は入らないのか、今回、改正の中で出てきていないのですけれども、どういった仕組みになっているのかというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"例えば、都営住宅の入居の申込みだとか、それから、都立病院で、通常は親族にしか病状の説明などをしませんが、こういうパートナーシップを受けていらっしゃる方には、病状の説明などもするというようなことを聞いてあります。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたところをほかの住宅施策でも適用できるところは適用していっていただきたいというふうに思うのですが、他の住宅施策で適用することは、ほかに考えているところがあるのかどうか伺いたいと思います。今、区民住宅の申込みの状況ですとか、入居の状況はどうなっているのか伺います。","respondent":"竹田住宅課長","answer":"住替えの状況、どういうお声があるのかですが、お子さんが成長するにしたがって子ども部屋が欲しいとかといったお声がありますので、居住する方のご家族のライフスタイルの考え方も様々ですので、そういった多様な考えに対応できるように、今回、住替えの要件に追加したものです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"このパートナーシップ制度のほかの住宅施策への適用は、今後、研究していくということなので、ほかの自治体のものを見ますと、住宅への入居要件ですとかというものが大体多いのですけれども、あと、住宅関係の助成制度の中で適用しているところもありますので、そうした形で、適用できるところには、ぜひ積極的に適用していっていただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいと思います。参考までにお伺いしたいのは、こういう里親制度で里子を見てくださっているご家族から、これまでに区民住宅などの申込みなどがあったのか、また、今回これが追加された背景などがありましたら、参考までに伺いたいと思います。","respondent":"竹田住宅課長","answer":"今回、どうしてなのかですが、国の特定優良賃貸住宅の供給の促進に関する法律の施行規則が改正されまして、パートナーシップと一緒にといいますか、同時に、親族、児童という形で、児童というのが里子を差すのですけれども、改正されましたので、区も条例改正を行うものです。","id":"exchange-045"},{"speaker":"こんの委員","kind":"質問・要望","question":"改正に伴ってということですが、今までそういう申込みは、またお問合せはなかったということですが、もしかしたら、こういうことによって、これまでそういうものは駄目だったなと思っていた、そういうご家族が、これから入居できる、そうした流れは大変に大事なことだと思いますので、区の制度として、私としては非常に前向きに考えて進めていただきたい、このように思っております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"説明ありがとうございました。２点お伺いいたします。こちらですけれども、周知はどのように行っていく予定なのかを教えてください。区営住宅条例と区民住宅条例の部分ですけれども、改正に当たりまして、応募倍率ですとか、どういった変化があるというふうに区として考えているのかというところをお聞かせください。","respondent":"竹田住宅課長","answer":"これからの要望、ニーズの点ですが、子どもの成長に関しては、たびたびお問合せをいただいておりましたので、要件拡大に伴いまして、住替えのニーズは従来より増えていくものと考えています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"意見","question":"多様な家族の形を認め、同性のパートナーなども、異性の婚姻関係にあるパートナーと同等の対応をするために必要なことで、ジェンダー平等を進めるものであり、また、合理的配慮の主旨を踏まえてということで、介護が必要な単身障害者の除外をなくすということですので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"パートナーシップ関係は、区営住宅と同様の理由で賛成です。住替えについては、住民の声から始まって要望が実現したもので、住民の利益になるものですので、賛成です。ほかのものも区民の利益になるものですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-02","title":"第２３号議案、品川区手数料条例の一部を改正する条例","agenda":"第２３号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"下のところのマンション建替円滑法改正に伴う証明書というところで、税の軽減措置を受けることができる証明書ということで書いてあるのですが、これはどういったもので、現在はどういう形で運用されているのかということを伺いたいと思います。","respondent":"竹田住宅課長","answer":"マンション建替円滑法の証明書の件ですが、こちらはマンションの敷地売却事業のために所有期間が５年を超える土地等を譲渡する場合には、譲渡所得について、所得税、都民税、区民税などの税率の軽減などを受けることができるというものです。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"管理計画のほうは、つまりは、適切に管理しているマンションを区が認定しますよということだと思います。そうした適切に管理していくということは必要だと思います。税のマンション建替円滑法のほう、今回、耐震性だけではなくて、耐火性、また、外壁等剥落の恐れがあるマンションも追加されたわけですけれども、そういった変更になった背景を伺います。","respondent":"竹田住宅課長","answer":"マンション建替円滑法の件ですが、適正に管理されていない、あるいは、もう既に使われていないマンション等がございまして、そういった中で耐震性不足だけでは不十分であり、耐火性や、あるいは外壁等の剥落によりまして、地域の居住者。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"それと、新しく簡易に評価できる仕様ルートというものができたわけですけれども、この中で太陽光発電設備等が考慮できないということで書かれているのですけれども、環境性能を上げていくというところで、こういった評価方法を導入するわけですけれども、そこで、太陽光は再生可能エネルギーですから重要なものだと思うのですけれども、考慮されないというのはどういうことなのか伺います。","respondent":"竹田住宅課長、長尾建築課長","answer":"マンション建替円滑法改正に伴う対象物件が区内にどれぐらいあるかというお話ですが、正確な数は把握してございません。ただ、既にお住まいになっていないようなマンションも見受けられることから、一定数あるものと考えています。今回、住戸ごとの申請が廃止されましたのは、さらに強力に環境に配慮した低炭素の建物を増やしていこうという国の法律改正であったり、全体の計画の改正がございましたので、それに対応する形で。","id":"exchange-052"},{"speaker":"のだて委員","kind":"意見","question":"老朽化したマンションの管理ですとか、脱炭素化は進めるべきものですので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-03","title":"請願・陳情審査を再度行います。 それでは、(1)から(14)に記載の請願・陳情１４件につきましては、関連する内容のため","agenda":"請願・陳情審査を再度行います。 それでは、(1)から(14)に記載の請願・陳情１４件につきましては、関連する内容のため","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、基準値以内ということですけれども、これはＬｄｅｎということで、この１年間、あるいは１日の中で平均して出されるというもので、品川の場合、夕方３時間、あるいは４時間というところで飛んでくるということですから、おのずと値が小さくなってしまいます。こうしたＬｄｅｎの考え方、品川区には適さないというふうに思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"Ｌｄｅｎについての考え方ですが、資料でお示しした数字が国の環境基本法に基づく数字についてお示ししているものです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"合っていると思っているのか、そこを伺いたいと思うのですけれども、実際に冬の間も南風のときがありますので、ひっきりなしに飛んできております。工業系の地域でも最大７０デシベルということになっております。やはりこれを飛行機は超えているということだと思うのですけれども、これは問題ではないかと、生活を実際に壊しているわけですけれども、壊すものではないかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今回の航空機の音、あるいは、国道沿いの車の音ですとか、電車の音ですとか、そうした１つ１つの実際の音は、示されている環境確保条例に当てはまるものではないというところを先ほどご説明したところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"それにもかかわらず、このＬｄｅｎで見ると、あたかも問題がないように見えますけれども、品川の場合は短時間なわけですから、短時間で見ると基準が低くなってしまうということでは、品川の実態にはそぐわないというふうに思うのですが、改めて伺います。","respondent":"鈴木都市計画課長","answer":"先ほど来ご説明し、冒頭でもご報告している内容が、環境基本法に定められた基準の算出によってお示ししている数字です。これでいい悪いというよりも、その事実を先ほどからご報告、ご説明しています。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"事実を報告しているだけだというのですけれども、このＬｄｅｎでは、品川の被害の実態は表わせないというふうに思います。今、国際便の増便のためにこの羽田新ルートをやっていくということで実施されてきたわけですけれども、実際のところ、コロナで減便になっているという状況ですが、現在の国際便の便数、コロナ前と比較してどれだけの割合になっているのか。そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"あるいはＡＮＡ（全日本空輸）が、コロナ前、２０１９年比で５７.１％というような状況です。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"収入というところですけれども、７１％と５７％ということで、恐らく便数としても回復していないのだろうというふうに思います。そうした中で、この羽田新ルートを実施していく必要性はないというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"運行開始当時、正にコロナ禍に突入していったというところで、区のほうでも、当時、区長が直接国交省に赴きまして、そうしたコロナ禍での状況も鑑みながら、内容を含めた要望書を国のほうに直接届けてきたです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"その下で、住民が、必要ないにもかかわらず、騒音や落下物、大気汚染など、様々な被害を今被っているということで、やはりそうした区民の生活を守るために、区として、この羽田新ルート、やめてほしいと、反対だということを言っていくことが必要だと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後も、継続し、こうした申入れをしっかり行うとともに、固定化回避に向けた一刻も早い検討内容の公表を国に求めてまいりたいです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"羽田新ルートは国策だということで、国の責任において行われているものだと言いますけれども、やはり区民の生活が壊されているものですから、区民の生活、財産を守るという立場で、自治体として姿勢を、そういった立場をとることが必要だというふうに思いますけれども、なぜ反対しないのか伺います。それはこれまでも様々言っておりますけれども、滑走路の使い方を変えないというのが検討会の前提です。","respondent":"鈴木都市計画課長","answer":"固定化回避につきましては、基本的には、これは国策として国の責任において進められている取組ですが、いろいろな多角的な検討の中で、この都心上空を飛行するルート案が示されて、今現在行われているわけですが、区の考えとしましては、未来永劫この２ルートが、その後。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり空港に近い自治体の１つですから、ほかの自治体も品川区の動向を見ていると思います。この間、この羽田新ルートが実際に飛んできている中で、区にはメリットがないということですから、そうなれば、ぜひ住民の立場に立って、品川区としても国に撤回を求めていくという姿勢に立っていただきたいというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"固定化回避については、検討が開始されて数年たつわけですが、当初の、品川区のほうでこうした固定化回避に向けた検討を求めていなかった場合、これは正にそのまま何の検討も加えられずに進められてきているものです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"固定化回避では、品川上空を飛ぶことは回避できないということは強く言っておきたいと思います。それで、品川区議会としても、海上ルートに戻すという意見書を、今こそ、検討会で、もう３年もずっと続いて結果が出ていないわけですから、区議会としても出していくべきだと思いますけれども、委員の皆さん、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"誰も発言することはないということなので、皆さん、この意見書を提出するということでいいということでしょうか。この間ずっと、この請願・陳情が継続審査にされてきまして、ずっと店晒しにされてきたわけですけれども、今回継続にすると、４月の改選で、この請願・陳情は全て廃案になってしまうということですから、ぜひ今回、結果を出していただきたいというふうに、これは強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問","question":"固定化回避検討会が出来上がって、その様子を見ようということで趣旨採択がこれまで続いてまいりましたが、先般行われた区長選において、新たな区長から、羽田新ルートに対しては、全区民にアンケートをとる、それをもって、また新たな動きがかかるということでお話を伺っておりますので、それについては様子を見て、区議会だけではなくて、品川区としての動きをこれから決めるものだと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"今回は結論を出したいところですが、以下の観点から、継続とさせていただきたいと思います。それから、固定化回避の検討会、これは私どもも区議会として求めてきた中で行われている検討会で、たとえ時間がかかったとしても、まだ結論が出ていないという、こういう状況です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"本日結論を出すということで、採択を主張します。今回継続にするということは、この４月の区議会改選で廃案になってしまうということです。結論を出さずに採決さえしないというのは、職責を果たしていると言えるでしょうか。結論を出すべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"のだて委員","kind":"意見","question":"この羽田新ルートは、冬の間にも南風があって、品川区の上を飛行機が飛び、騒音や落下物、大気汚染、資産価値の低下など、住民に耐え難い被害を与えています。昨年３月、渋谷区で氷塊落下があり、羽田新ルートにおいても落下物の危険性が現実のものとなっています。以上のことから、この羽田新ルートは撤回すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"意見","question":"我が会派といたしましては、以前から騒音問題に関しましては、リモートワークや学習等が騒音に悩まされて集中できない、落下物に関しましても、事故が起こる前に対策をとるべきであるという声も届いております。こうした理由により、区民の生活の不安と問題を解決するためには、この都心ルートではなく、海上ルートに戻す方法しかないと考えておりますので、我が会派は、この請願に対し採択いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"横山委員","kind":"確認","question":"第６回固定化回避に係る技術的方策検討会は、本年夏から秋頃の開催が予定されているとの説明がありました。今定例会の議論では、区から区民アンケートの方向性が示されました。現時点においては、今後、区がアンケートを適切に進めていく過程を見守っていくことが重要だと考えます。引き続き区民の方々のお心に寄り添い、丁寧に説明、確認していく必要があると考えますので、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"結論を出すということで、採択を主張します。先ほどの令和２年請願第３号と同じ理由とともに、本請願は、町会長、自治会長の過半数を超える１０１名の署名があったもので、運用停止を求める声が区内に広がっているあらわれです。この思いを受け止め、空港に近い被害の大きい自治体の議会として、住民の被害を取り除くために、区議会としても運用停止を求める意見書を提出すべきですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"のだて委員","kind":"意見","question":"今回出されたこの請願ですけれども、この請願にもあるとおり、運用実施から既に３年が経過しようとしています。住民への騒音や落下物など被害は甚大であり、国の検討会では、品川上空を飛行回避することはできないため、羽田新ルートは中止すべきです。こうした住民の声を区議会から国に届けるために、一旦海上ルートに戻す意見書を提出すべきですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。理由は、先ほどの令和５年請願第４号と同様で、羽田新ルートは撤回すべきだと考えますし、被害の多い品川区が国に求めることが撤回への力になると考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。この陳情は、一時凍結を求めるというものですけれども、共産党は、計画当初からこの羽田新ルートは撤回すべきだと言っていますが、新ルートを実施する目的は国際便の増便であり、コロナで減便になっている今は、目的も達成できない中、住民には被害を与えている最悪の状況ですので、少なくとも一旦中止すべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。陳情にもあるとおり、視覚障害者の方は音を頼りに生活しており、新ルートによって、この品川上空を飛行機が飛び、騒音で行動を制限され、命の危険も感じています。この状況を一刻も早く改善する必要がありますので、採択です。ほかの理由は、令和４年陳情第４号と同様です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。落下物の危険が浮き彫りとなり、騒音や大気汚染などの問題もあります。国の検討会では品川上空を回避することはできず、結論が出るまで待っていることが固定化になっています。この羽田新ルートは撤回こそすべきですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":61716,"voices":313}},{"id":"r05-20230227-9","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"文教委員会","time":"午前１０時００分～午後 ２時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"確認","question":"１点なのですけれども、西村直子議員の２月２２日の質問の中で、区民アンケートについてのところで、子どもに対する区民アンケートの取り方に対して、品川区教育委員会とアンケート内容を確認していくといったご答弁があったと思うので、今の品川区教育委員会とのアンケートの調整の状況などをお知らせいただければと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第２６号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第２６号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、現在非常勤ということだということなのですけれども、どんな仕事を週にどれぐらいされているのか。報酬というのは時給なのか、日額なのか。どれぐらいお支払いされているのかというのと、あと、各学校にどれぐらい配置されているのかという配置状況などを教えてください。","respondent":"勝亦学務課長","answer":"配置ですけれども、内科医、眼科医、耳鼻科医、歯科医、薬剤師を各小中学校各１名、義務教育学校等、大きな学校につきましては内科医と歯科医を１名ずつ加配しています。現在、学校を兼ねている方もいらっしゃいますけれども、２１７名の方に従事いただいている状況です。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"都の条例によって区の条例も変わるというのは理解はしているのですけれども、ほかの１５年以上の方たちに対しては、どうして都の条例でも変わらなかったということは、特に都からの説明などはなかったということですか。確認させてください。","respondent":"勝亦学務課長","answer":"こちらの学校医の条例に関しての引上げがなかった部分については、都からの説明はございません。東京都の人事委員会勧告が、若年層について引上げをしまして、それ以上の方については改定されていませんので、現状維持という形になってあります。","id":"exchange-003"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、１点だけ。先ほど安藤委員の質疑の中で、配置状況についてお知らせがあったと思うのですけれども、たしか義務教育学校では、ほかの小中学校とは違う先生も配置されているということだったと思うのですけれども、その理由は何かありますか。何で義務教育学校だけ多く配置されているのかという部分を知りたいです。","respondent":"勝亦学務課長","answer":"義務教育学校につきましては、小中学校、９年間が同居して生徒数が多うありますので、内科医と歯科医を１名ずつ多く配置しているです。","id":"exchange-004"}]},{"id":"topic-03","title":"区立学校における３月１３日以降の教育活動","agenda":"区立学校における３月１３日以降の教育活動","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、裏のチラシなのですけれども、これは分かりやすいかなと思っているのですが、これは周知したと言いますけれども、具体的にはどのような規模でどういう感じで周知して、どれぐらい徹底されていると感じているのか伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"その辺りの配布の仕方は学校によりますけれども、全校が保護者に伝わるように連絡する予定で指示しております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"続いて伺いますが、マスクが個人の判断に委ねられるということになるのですけれども、やはりマスクの感染症対策への効果というのは誰も否定できないと思うので、１つ伺いたいのは、それは個人の判断になったとしても、感染を防ぐ防止の対策というのは、絶対、学校では引き続きやらないと駄目だと思うのですけれども、その両立というのですか、それが必要だと思うのですけれども、その辺は。","respondent":"矢部教育総合支援センター長","answer":"当然、手洗いですとか、マスクのことがありましたけれども、マスクのことですとか、せきエチケットとか、３密を防ぐというのは、これまでどおり進めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは３月３１日以降の話なのですけれども、マスクが個人で判断となった場合に、まずつけない子もたくさん出てくると思うのですけれども、それ以降の感染対策はどうするお考えなのかというのを伺ったので、もう一回聞きます。","respondent":"矢部教育総合支援センター長","answer":"ただ、つけている・つけていないお子さんが両方いることが理解できれば、だんだん、時間がたつと理解も進んでいくのかなとは思っておりますので、そこは大切に、４月以降もしっかりやってまいりたいと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば給食の黙食のルールなのですけれども、かなり、陳情者の方にもお話を伺ったのですが、学校によって全然違うということで、黙食について、給食のルールは今どうなっているのか。ルールがどのように変わってきて、品川区教育委員会としては今どういうルールを発出していて、各学校によっての現状というのですか、実際どうなっているかというのは、分かる範囲でいいけれども教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"２月９日に校長連絡会があったのですが、そちらで私から、かなり具体的に例示して、少なくとも学校の中で隣のクラスと対応が違うようなことがないようにと、改めて伝えたところです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。だから、随分対応が変わって、違うなと思うのですが、感染対策の各学校の把握というのは、品川区教育委員会としては実際どこまで把握しているのかというか、通知を出して、基本的には学校で判断というふうになると思いますけれども、その辺はフォローアップというか、品川区教育委員会としてはどこまで把握しているのかというのは、再度お伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"個々に対応がございましたら、我々のほうできちんと受けて対応してまいりたいと考えています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の陳情は、マスクを外したい子もいるけれども、外せない子どもたちもいる中で、どちらの子どもでも、きちんと尊重されるようにということも含めた陳情です。そういうことを品川区教育委員会として、「きちんと説明をして、このチラシを渡してください」といったお知らせがあったのかという部分を、まず確認させていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"繰り返しますが、個別にもしも足らないところがありましたら対応したいと思いますけれども、ただ配布ということではないと認識しています。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"教員のほうから日直を外されるとか、給食当番をさせないとか、窓側に固定されてしまうとか、こういったことが本当にあったのか。それで、学校や教育委員会に個別に相談しても解決に至らないケースがあるということも書かれているのですが、ここの事実関係を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ただ、全て全件、センターでお預かりしているということではございません。調べられる範囲のところで確認しています。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"電話での確認、電話での連絡があったというご説明だったと思うのですけれども、電話で、マスクをずらしていることによるいじめということですか、そういった件数がどれくらいあったのかということと、また座席を窓側に固定してしまった事実があったという話ですよね。そういったところを、もう一回確認させていただきたいのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"保護者から、窓際や廊下がいいという方もいらっしゃるので、当然、保護者やご本人には聞いているものと認識しています。そこにつきましては、１件につきましては、きちんとこちらからも是正を求めたり、保護者としっかりやり取りするようにとは話しております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、すみません。やはり今、ある専門家の方たちは、今の状況でいくと、４月頃にまたピークが来るという予測も立てられていますし、また、さっきご説明もありましたが、感染症、コロナ以外のものでの学級閉鎖なども実際に今起きているわけで、そういったことも考えて、どうなのかなというところを伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"そこは変わらないと思いますので、ご自身の予防ということを大切にしてあげたいなと思います。これまでの通例の式、特に卒業式につきましては、ほぼ隣でおしゃべりするような指導はしないので、厳粛な雰囲気の中でやることになっていることから、このような対応をしております。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"この間いろいろ本当に大変だったと思います。そのような中で、今日出していただいているこの資料を見ると、すごく見やすくて、令和５年２月品川区教育委員会ということで、子ども向けに配っているやつです。これでよくまとまっていますし、もう難しいことを書くよりも、それがいいかななどと勝手に思うのですが、ちょっとその辺を考えていただきたいと思うのですが、お答えだけすみません。","respondent":"矢部教育総合支援センター長","answer":"２点頂きました。１点目、配布時期ですが、各学校には今月末までということで、あしたまでに配布することになってあります。２点目につきましては、ご意向を理解しましたので、関係の課と連携して検討したいと思います。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、今回は、たまたまというか、コロナが３年前に発生して、大人の社会もそうですけれども、特に子どもの社会、学校の中で、マスクについての様々なこういう事案が発生していると。「いじめなんだよ」というところを、立て分けながら、またうまく融合させながら、子どもにも保護者にも理解していただくということを、いま一度確認させていただきたいなということで、では一回答弁を。","respondent":"矢部教育総合支援センター長","answer":"いろいろな形で、いじめ防止については進めていかなくてはいけませんので、これまでのアンケートもそうですし、先ほど申しましたような目安箱等も使いまして、マスクに限らずしっかり予防して、また発生した場合は解決に力を入れていきたいと考えています。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"もう一つは、教育総合支援センターでお受けいただくということですけれども、一回、子どもも親も含めて、いわゆる外部の方の力をお借り……、よくやられるけれども、ハードル的な部分も含めて、また、いわゆる学校の中、それから社会全体の、マスクというのはまさに大人の社会のことでもあるので、何か学校の教育総合支援センターだけ、教育委員会だけの範疇ではなくて、もう少し、何ですか。","respondent":"矢部教育総合支援センター長","answer":"人権擁護委員の方とも連携していますので、様々な視点でご意見を頂きながら、子どもたちの安全安心を守れるように努めてまいります。","id":"exchange-016"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"要は、ここはすごく課題だなと私もすごく感じているので、例えば、もしこれを町会内に配っていただけるということが、もし可能で、やっていただけるのであれば、そのときに、またさらに学校から校区教育協働委員会を通じて、要は町会長などというところに改めてまた周知をしていって、地域でこういうふうにやっていただきたいというのを、何といいますか、強く要望していくというのですか。","respondent":"矢部教育総合支援センター長","answer":"地域の方にもご理解が必要かなと考えていますので、関係課と連携して検討いたします。","id":"exchange-017"},{"speaker":"江野下委員","kind":"質問・要望","question":"今、商店街と出てしまいましたけれども、地域で言えば町会もそうですけれども、周知が得意な商店街などにも、今、啓発で地域の学校と連携している広め方もありますので、そういったところも要望をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"様々なお知恵を頂きましたので、関係課と連携して進めてまいります。","id":"exchange-018"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出して、この陳情自体は不採択でお願いいたします。学校も一生懸命今やっていただいているのは重々承知はいたしておりますし、今、チラシ、報告事項のほうの中で、私どもの３名からもお話しさせていただきましたが、次はやはり、地域の見守りの中でどうしていくかというステップに移行もしていくのかなというところもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"結論を出すで、不採択でお願いします。陳情の要旨、趣旨、それから、私も含めて各委員から、様々な具体的なこと、また本質的なこともご指摘させていただきました。教育委員会にはしっかりと受け止めていただいて、今後、着実な、確実な運用・施策が進んでいくと理解いたしますので、そういう理由です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"本日結論を出すで、採択なのですけれども。なので採択なのですが、しっかり、今後、議会としても、この内容はもうやっているから採択というのも１つの考え方かもしれませんけれども、むしろこういう内容というのは、もっとさらに徹底してもらいたいわけですから、採択を議会としてもして、さらに促すという立場に立つというのも、ありなのではないか、そうあるべきなのではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張したいと思います。教育委員会でもお知らせをしていただいているというのも確認はできていますが、やはり、それをもっと進めていく。一緒に、その必要性ということを、品川区教育委員会としても区としても、持っていただきたいなということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"第１２号議案ですけれども、今回の内容の児童センターへの反映というのはどういうふうになるのでしょうかということと、あと、いろいろ、計画策定の義務づけ等を課しておりますが、事業者に対して課すとあるのですが、品川区の場合、一部、運営を委託していると思うのですけれども、これは区になるのでしょうかということを伺いたいというのが第１２号議案。","respondent":"廣田子ども育成課長、中元保育支援課長","answer":"２つ目の、事業者に課すというところなのですけれども、運営委託はしておりますが、あくまでも区の事業となっておりますので、区が責任を持って計画等を立てまして、運営委託者に対しては委託の内容で。懲戒権の改正の理由と背景ですが、まず民法改正のところから説明します。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"保護者に対してもきちんと周知していただきたいなというところと、また懲戒に関しては、本当に懲戒そのものについてはもう、削除をずっと求めていた側は、どうしても本当によかったということを思っています。","respondent":"廣田子ども育成課長","answer":"安全計画については全体で、保育関係も同様だと思うのですけれども、この安全計画の策定については、施設・設備の安全点検やマニュアルの策定などというところを、いつ何をなすべきかを具体的に示せというところが書かれているのに加えまして。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"この安全計画の周知について、今どういったことが想定されるのか。例えば各すまいるスクールに行ったときに安全計画が見られる形なのか、それともホームページなどでも広く公開されるものなのかといったところも確認できたらと思うのですが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"現在、策定中でございまして、今後どのような形でしていくかについては、保護者会であるとか、様々あろうと思うのですけれども、まだ策定が令和５年度４月、ここは経過措置で努力義務なのですけれども、令和６年４月からが義務づけになりますので。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"委員長、すみません。ちょっと議案と直接関係ないかもしれないのですけれども、品川区の例えば放課後事業というのは、民間の事業者がオレンジ色の車で迎えに来てとか、品川区の事業者ではないところなどというのがある中で、そういうものは都道府県条例か何かで縛られているのか、国の法律で縛られているのか、ある程度、同程度の内容のことが日本全国で起こっているのか、分かればでいいので教えてください。","respondent":"廣田子ども育成課長","answer":"放課後児童健全育成事業という形で正式にやる場合には、事業内容をつくったものを届出をして、こちらでチェックするという形をしていて、届出をしたところに関しては縛られるはずなのですけれども、区の中で届出をして持ってきた民間業者は１個だけです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"第１６号議案のところで、先ほど対象について質疑があったと思うのですけれども、不勉強でごめんなさい。伺いたいのですけれども、ぷりすくーる西五反田は対象になって、今回の条例のところも反映されるのかどうかというところを伺いたいのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"ぷりすくーる西五反田も対象となります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"提案","question":"１０月以降は、それが、東京都が実施することによってなくなるということになるのかの確認が１つです。３点目は、共産党としては、子どもは社会の宝なので、やはり子育てに特別なお金がかからない社会というのを目指して提案しているのですが、第１子の保育料というのも無料化すべきだと思うのですけれども、区にその考えはあるのか伺いたいと思います。","respondent":"立木保育課長、中元保育支援課長","answer":"第１子のことに関しまして、今のところ検討には挙がっておりません。認証保育所の部分につきまして、私からご説明申し上げます。認証保育所も、同じように令和５年４月分の保育料より、第２子の方につきまして適用します。先ほどの影響額のところで、半年分というお話をさせていただきましたが、資料に記載してあります影響額４億６,８００万円は１年分で計算していますので。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"認証保育所のほうは、よかったなと思います。それと、第１子の無料化というところは、今のところ検討外だということでしたが、森澤区長が施政方針説明などで、社会全体で子育てを支えると。そういうことを伺うと、なぜ第１子からはあえて保育料を取るという措置を継続するのかなというのが分からないので、なぜ第１子から保育料を取るのでしょうか。伺いたいと思います。","respondent":"立木保育課長","answer":"歳入が減るという形ですので、その分、区が使うお金は、入ってこなということになります。第１子の無償化につきましては、今のところは検討はされておりませんが、今後の社会情勢等を見ながら、注視していきたいと考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"社会情勢も大きく変わっておりますし、危機的な少子化ということも言われていますが、子どもを産む・産まないはその人の自由なのですが、今問題なのは、産みたいと思っても産む選択肢がないという。お金がかかって、産みたくても産めないという方がたくさんいらっしゃるということです。ですから、ぜひさらなる強化へ、第１子保育料の無償化に向けてもぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"令和５年請願第１号 一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"令和５年請願第１号 一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"毎年、品川保育問題協議会の皆さんが、今年も１,５００名近くの署名を添えて、こうした請願を出されているということは、改めて、一人ひとり子どもたちを大切にする保育環境をさらに進めてほしいという、区民の皆さんの強い願いなのだなということを実感しています。今、保育園、認可保育園、区立認可保育園の在り方方針というのはどういうふうに検討されていて、それはいつ方針を出すというお考えなのか。","respondent":"立木保育課長","answer":"保育園の在り方の検討のところですが、今、庁内のプロジェクトチームのような形でスタートしています。来年度、検討委員会という形でやっていきたいなと思っているところです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"伊藤幼稚園のほうについては、かなり厳しい現状の中で、２名の幼稚園にやはり行かれたいという方からの応募があるということなので、方針どおり、１年延長は実施されるのかというのを確認させてください。それと、区立幼稚園３園の閉園方針なのですけれども、確認したいのですけれども、森澤区長に一応、区長が替わったわけです。その辺は指示などはないのですかというのを確認させてください。","respondent":"立木保育課長","answer":"こちらの方が引き続きご希望されるということであれば、運営のほうはそのままクラス編成するというようなことで、今、教育委員会とも話はしています。区立幼稚園３園の閉園方針につきましては、区としましては今のところ、変更の予定はございません。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、最後の質問ですけれども、変更がないということは、つまり新しい子育て支援を大きく打ち出す新区長になったとしても、その新区長から、区立幼稚園の閉園するという方針について、見直してくださいとか検討してくださいということはなかったということなのか、伺いたいと思います。","respondent":"立木保育課長","answer":"繰り返しになってしまいますが、区の方針としましては、今のところ変更はございません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"ないということですね。それと、区立認可園の民営化についても触れられていますけれども、こういった話を伺うときがあるのです。民営化した保育園で給食の内容が変わってしまったという声を伺ったのです。区は、民営化は今回、運営委託なので、あくまで区立のままですから、保育の質は落ちることがないという旨の発言をしていたと思います。区として実態を把握されているのでしょうか。伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今、お問合せがございました、民営化後の給食に関してですけれども、基本的には区のガイドラインに沿って進めているところで、内容はもちろん事業者に任せる部分もありますので、多少変わるところもあるかとは思いますけれども、基本的には大きな変更がないような形で。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"当然、その運営費の中で、もうけを出す。株式会社が受託した場合はそうなるわけです。そうなると、保育士の待遇だったり、あるいは子どもに直接、さらに保育士の待遇にも関わるのですけれども、給食の費用をちょっと削ってしまおうというふうなことになり得るということなのでしょうか。そうすると、すごく心配なのですけれども、伺いたいというのがあります。","respondent":"初貝保育教育運営担当課長","answer":"ただいまご指摘がございました、委託先の保育の内容であったり、そういったところのご心配かと思いますけれども、もちろん委託する上で必要な金額に関しましてはお渡しして、あとは中身に関しましても、例えばそういった保護者からの声等々がございましたら。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私はやはり、どんどん公立が、公が、保育や幼稚園の幼児教育などに責任を持つ公営というものをどんどん引き下げていくというのは間違いかなと思います。どうなっているのかというのを伺いたいというのが１つ思います。私は、この請願が求めているように、独自の手厚い基準というのをつくって、さらなる保育環境の改善をすべきだと思いますけれども、いかがでしょうか。","respondent":"立木保育課長、中元保育支援課長","answer":"一部、例えば持ち上がりだったりといったことで、クラスで弾力化されているところもありますが、ほぼ全ての園で弾力化は解消の方向で、今、進んでいるところです。区内保育園の配置基準ですが、現在、私立認可保育園９８園の全園におきまして、国の配置基準以上、平均約２名ぐらい多く配置していますので、常勤保育士の加配で、平均して国基準より２名多く配置しているところもありますので。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、品川区でも、世田谷区でできているわけですから、取りあえずどんどん増やせばいいということでやってきたわけではないと思いますが、増やすと同時に園庭の確保というのも、必要条件としてそれを課して増設を求めるとか、そういうふうにしないと、やはり質と量の両立というのはできないと思うのです。そういったお考えはあるのかということ。そこを最後、３点目で伺いたいと思います。","respondent":"中元保育支援課長","answer":"公園等におきましても、今、複数の保育園が公園を最大限に活用して、保育園同士でもきちんと時間など相談しながら活用していますので、乳幼児が行けないということはないという認識です。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"保育士配置基準のところなのですけれども、これまでの質疑を聞いていると、やはり区としても、「今の国の配置基準ではあまりよくないよね」ということは、認識としてあるというところかなと思ったのですけれども、国の配置基準について、これが今、正しいというか、正当であるかというところについて、区としてのお考えを伺いたいと思います。その２つをお知らせください。","respondent":"中元保育支援課長","answer":"新年度予算でも今度、安全に関して、園庭、外に遊びに行くときなどの安全確保用の人数を雇うことができるような補助制度も設けてまいりますので、様々な形で現場の充実・拡充に努めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったことがないように、やはりきちんとそこの地域の方、子どもたち、保護者と話し合って、どうしていくかということを進めてほしいと思います。来年度の検討委員会についてはこれから検討ということだったのですけれども、ぜひこれは庁内だけではなく、当事者だったり、いろいろな方、保育に関わっている方たちが参加できるような検討委員会にしていただきたいと思うのですが、伺いたいと思います。","respondent":"立木保育課長","answer":"城南幼稚園が１５名の入園予定者となっております。単独園３園の今後の閉園に関しての進め方に関しましては、丁寧な説明をしながら進めていくということで考えておりますので、そのような形でやらせていただきたいと考えています。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"区立保育園在り方方針の庁内プロジェクトのことについては、今の３回の検討状況は、今のところホームページにはまだ出さないのかなという感じだったのですけれども、前回の区立幼稚園のときにも、情報開示をしなくてはいけないのかというやり取りで、品川・生活者ネットワークは情報公開請求をして資料を見ましたが、その後、公開されるようになったので、ぜひもう。","respondent":"立木保育課長、中元保育支援課長、高梨公園課長","answer":"在り方のところの資料の件ですけれども、こちらは中身的には行政運営の情報が大分、入っているもので、これから形にしていくようなところもありますので。園庭確保のところですが、私も何園か見に行って、人工芝を敷いて、上手に屋上で園庭にして活動されているという園があるのは、実態はつかんでいるのですが。公園・児童遊園の整備における、保育園等からの意見収集についてですが、この間。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、ここも駄目だった、ここも駄目だったと、いろいろな公園に、結構な距離を歩いたりもしているので、ぜひ広い範囲で保育園の方たちにお知らせしてほしいし、意見を聞いていただきたいと思いますが、たしか保育園での共有でのメールなどもあったと思うので、今度こういう公園が改修されますとか、新設されますとか、ご意見くださいといった、ウェブ上でのそういうものなどもぜひ利用していただいて。","respondent":"高梨公園課長","answer":"それで、例えば、ちょっと極端ですが、しながわ区民公園のような大きな公園であれば区内全域からおいでいただきたいというような、規模に応じて、来ていただきたいというか、来ていただく区民の方々の範囲というものがあるかなと感じてありますので、公園の規模に応じて。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"ごめんなさい。ぜひ細かな情報発信をしていただきたいと思うのですけれども、その情報の発信の在り方とか、スケジュールについても再度伺いたいと思います。区立保育園の民営化についての先ほどの議論の中で、給食が変わってしまったなどといったお話があったのですけれども、そもそも民間事業者の選定基準というのが、どうされているのかという部分を伺いたいのですけれども、いかがでしょう。","respondent":"高梨公園課長、立木保育課長、初貝保育教育運営担当課長","answer":"最初のご質問ですが、やはり小さな１区画ぐらいの公園で、区内全域の保育園から聞くなどというのは、なかなか難しいこともあります。先ほどと同じになってしまうのですが、スケジュールのところは、今のところはまだはっきり申し上げることはできないのですけれども、進め方につきましては。民営化に当たる事業者の選定基準のところのお問合せですけれども、区では選定に当たって、簡易型プロポーザル方式という形の方式で選定しているところで。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"選定基準のところで１個だけ。プロポーザルということは理解しております。保育の質という視点で、どういった保育の質を品川区として求めているのか。そうではなくて、やはり子どもや保護者からの利用状況などを調べて、とても保育に手厚いなどといった調査がきちんとされて選定がされているのかという部分を伺いたいと思うのですが、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"後段の説明のところで言いますと、そういった視点で事業者をお選びさせていただいているというような状況です。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、要望にとどめます。ぜひ、きちんと、子どもたちのための保育が実現する、できる……。言い方に気をつけなければなと思うのですけれども、お金のために保育園をやるとかではなくて、きちんと子どものことを思って保育を進める、きちんとした、そういう事業者を選定していただきたい。それで、そういった選定基準をきちんと設けていただきたいということを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出して、請願は不採択です。では３歳児・４歳児がどうなのかという話もありますけれども、今きちんとやっていただいているし、何よりも、保育園、皆さん、保護者の方が選ばれていますからね。子どもたちの話は聞いて、地域の話は聞いて、これ以上どうするのだというのもあるのだけど、安全な公園を造ってもらっているし、それだけ、だから利用者がいるのかなというところはあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"若林委員","kind":"意見","question":"結論を出すで、不採択でお願いします。もう、繰り返しになります。項番１、項番２は、議論を経て、理解を十分しています。本当に待機児童対策をやってよかったなと思っています。一方で、やはりこの問題は、今度は物理的な問題になりますので、本当に公園課とも大変なご苦労をされることと思います。引き続き、できる限り今後とも健全保育に向けてご努力は賜りたいなと申し上げて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですが、やはり子育て支援を前面に掲げる区長に替わったとしても、これまでの区立園、幼稚園廃園・閉園方針を変えないと。やはり、ますます、ここに書かれているような請願の趣旨というのが大切になっているなと思いますので、これは採択して、しっかり区の姿勢を政策に反映させていきたいと考えていますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。そして、公園づくりについてもそうです。それで、子どもも含めた品川区民、子どもを含めた市民の声をきちんと反映したまちづくりというのをしていくためにも、ぜひ庁内での連携を強めていただきたいなと強く要望して、この請願は採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"令和２年陳情第４７号 離婚等のこども養育支援にかかる陳情","agenda":"令和２年陳情第４７号 離婚等のこども養育支援にかかる陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今ご説明がありました、元家庭裁判所の調査員の経歴を持つ家庭相談員を配置したというのは、いつからでしょうか。それで、これは何か事業名というのはあるのでしょうか。相談件数と、うち面会交流の相談というのは大体、年間なのか、どれぐらいあるのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"こちらの元家庭裁判所の調査官というのは、たしか令和２年か令和３年、はっきり申すことはできないのですが。相談件数についてです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"８８件、今年度だけでも、いろいろなことを含めて、そこに相談というのはあるということなのですけれども、もし分かれば、面会交流の支援を行ってほしいというような相談というのは、うち何件ぐらい、大体何％とかでもいいのですけれども、もしあればということを教えていただきたいのと、ここにある、結構それなりに年月もたっているので、広がっているとは思いますが。","respondent":"飛田子育て応援課長","answer":"行政の一般職員が支援を実施して、室長と係長は弁護士の資格のある人ということです。アドバイザーとしてＦＰＩＣの理事の経験者も委託で置いているというところで、そういうしっかりした体制が整っているというところが言えます。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれありがとうあります。ただ、やはり何よりも子どもにとって本当に重要な交流であるというところを、ケースによってはそれをどう実現させていくかという点では本当に高度な専門性が必要だと思いますので、ぜひ今の元調査官の方の配置ということからさらに一歩進んで、品川区としても交流支援をさらに進めるような体制充実を行っていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"本当に、面会交流は子どもにとってはとても大事なのは、しっかり認識しているところです。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に、大変慎重な対応が求められるのは間違いないので、すごく、そういう意味では専門性というのを積み重ねていかなくてはいけない事業だと思います。そこは最大限配慮しながら、とはいっても、やはりこれは、今の体制の下でも改善が必要な事業、進めていくべき事業だと思いますので、ぜひ研究を重ねた上に、しっかりした体制をつくることを前提に、進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"田中委員","kind":"確認","question":"区の今の養育費相談支援事業については確認できました。ホームページで公開されている事業、大きく分けて３つの事業で、それ以上、今これから拡充していくなどといった検討がされているのか。具体的に、養育費相談と、養育費に関する公正証書の作成費用の補助と、養育費立替保証契約の初回保証料の補助といった、この３つで、これ以上、拡充していくという考えがあるのかどうかを、まず確認させてください。","respondent":"飛田子育て応援課長","answer":"今のところ、まず国も審議が止まってしまっている状態なので、そこのところを見ながら、ある程度、国で法整備などが整ったら、またそこは、それを見て考えていきたいと考えています。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"養育費相談のところなのですけれども、相談日時が予約制で、月曜日の午前９時から午後１時まで、木・金曜日の午後１時から５時までで、時間的になかなか相談しづらい状況もあるのかなということを思うのですけれども、ここの拡充というものは、今後検討というところでしょうか。","respondent":"飛田子育て応援課長","answer":"「基本的に、相談を受け付けている時間はこの時間ですよ」というご説明はしていますが、条件によっては、この時間でないと、この曜日でないとと、中にはいらっしゃいますので、そのときは、勤務時間などを変えて、今回、相談員の方、家庭相談員の方を、時差出勤など。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"柔軟に対応していただけるということで、分かりました。確認されました。","respondent":"飛田子育て応援課長","answer":"そのところで、職員間で、お子さんの問題や、離婚の相談があって、そういうときはこういう手続というか、実際、家庭相談員の方が職員向けに職場内研修というところで、そういうところをする予定なので、そういうところで連携をより強めて。","id":"exchange-055"},{"speaker":"田中委員","kind":"意見","question":"やはり家庭の中のことで、両親と子どもで担当部署が分かれてしまうというのは、仕方がないのかもしれないのですけれども、やはり家庭のことなので、本当にうまく連携を取っていただいて、また先ほど連れ去りやＤＶの話もありましたが、やはり、その状況にある子どもだと、なかなか自分の思いをうまく話せなかったりということもあるので、そういった聞き取りなどもきちんとして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"先に意見を述べしますけれども、冒頭、この陳情に関して、過去２度ですか、今回３度目になるのでしょうか。しかしながら、相談体制をしっかり構築いただいてやっているわけですから、何かあったら相談に気軽に乗れますよという門戸は開いているというのは、すごくいいことなのだなと。ですから、今回、私たちは継続でいいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"継続でお願いしたいと思います。最初の令和２年度・３年度の議論を経て２年もたちましたけれども、当時からの、今のご説明にもありましたように、状況は、国のほうも含めて進んでいない。実績もお聞きして、今ここで品川区が踏み込むということはちょっと判断できないのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ、継続したいのは山々なのですが、継続したら、今回、案件は残念ながら、選挙が入ってしまうので、そのまま継続で審議が続くということはないので、一定、ここで結論を出したほうがいいのではないかと私は思っているのですけれども、態度については採択を、過去２回も私たちはそういうふうに求めているのですけれども、やはり子どもの権利と子どもの最善の利益を実現するために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、採択を主張します。区でもご両親にお話を伺うなど、制度はどんどん整ってきてはいるのですけれども、やはり子どもたちの声もきちんと聞いていただける仕組みがもっと充実できたらいいなという願いを込めてです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"区で商品券を買って、子ども食堂ネットワークにお渡しして、そこからというところをもう一回確認したいのと、あと区内商品券を使える場所というのが拡充されたのかなと。個人店だったりが使えなかったりというのがあったので。逆でしたっけ。その状況も確認させていただきたいと思います。食品などにも使えるのかなというところを特に知りたいです。","respondent":"飛田子育て応援課長","answer":"区内商品券ですので、子ども食堂から、ふだん、お野菜やお肉などを寄附してもらっているお店に、そういうところに逆に商品券で買って恩返しができるとか、そういうところで、逆にウィン・ウィンみたいな感じで、商品券という声があったのかなと考えています。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問","question":"商品券を使った子ども食堂からの利用の状況とか、実績というのですか、もしあれば教えてください。","respondent":"飛田子育て応援課長","answer":"実績は３月末に報告してくださいということですので、まだこちらには来ていないのですけれども、非常に評判がいいです。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":52968,"voices":222}}]);
